"use client";

import { useRef, type ComponentProps } from "react";
import type { ReactNode } from "react";

import { cn } from "../lib/cn";
import { warnOnce } from "../lib/warn-once";
import { Avatar } from "../avatar/avatar";
import type { ChatLabels } from "./labels";
import type { ChatMessageStatus, ChatParticipant, ChatPresence } from "./types";
import { useLoopPlayback } from "../motion/gate";
import { CheckCheckIcon, CheckIcon, ClockIcon } from "./icons";
import { AlertIcon } from "../status-icons/icons";

/* ---------- Keyframes and chat tokens ---------- */

/*
 * Chat-only keyframes and component tokens. React 19 hoists a <style> with href + precedence
 * into <head> once, however many chat components render it. Transform/opacity only. Reduced
 * motion (OS or [data-motion="reduced"]) finishes every CSS animation at once (styles/motion.css),
 * so the dots rest and nothing pulses; entrances then use a short opacity transition instead.
 *
 * Tokens (tier 3, built from the theme's primitives, no literal colours; override them on any
 * ancestor). :where() keeps them at zero specificity.
 *   --sheen-chat-in-fill         incoming bubbles and day labels: a light lift over the chat's
 *                                glass (no blur of their own), text-sheen-fg on it
 *   --sheen-chat-own-well(-hover) quote, file and link wells inside your own (accent) bubble
 *   --sheen-chat-media-scrim(-strong) veils over photos (time, +N, the photo viewer) that keep
 *                                --sheen-chat-media-fg text >= 4.5:1 on any photo
 */
const KEYFRAMES = `
:where(:root) {
  --sheen-chat-in-fill: light-dark(color-mix(in oklab, var(--sheen-ink-0) 82%, transparent), color-mix(in oklab, var(--sheen-ink-0) 9%, transparent));
  --sheen-chat-own-well: color-mix(in oklab, var(--sheen-ink-950) 18%, transparent);
  --sheen-chat-own-well-hover: color-mix(in oklab, var(--sheen-ink-950) 26%, transparent);
  --sheen-chat-media-scrim: color-mix(in oklab, var(--sheen-ink-950) 58%, transparent);
  --sheen-chat-media-scrim-strong: color-mix(in oklab, var(--sheen-ink-950) 80%, transparent);
  --sheen-chat-media-fg: var(--sheen-ink-0);
}
@keyframes sheen-chat-typing { 0%, 60%, 100% { transform: translateY(0); opacity: .45 } 30% { transform: translateY(-3px); opacity: 1 } }
@keyframes sheen-chat-attention { 0% { transform: scale(1); opacity: .55 } 100% { transform: scale(1.65); opacity: 0 } }
@keyframes sheen-chat-flash { 0%, 100% { opacity: 0 } 18%, 60% { opacity: 1 } }
@keyframes sheen-chat-in { from { transform: translateY(8px) scale(.96) } to { transform: none } }
@keyframes sheen-chat-fade { from { opacity: 0 } to { opacity: 1 } }
@keyframes sheen-chat-pop { 0% { transform: scale(.4) } 60% { transform: scale(1.18) } 100% { transform: scale(1) } }
`;

/**
 * Accessibility: Styles only; renders no visible element.
 * Motion: Defines the chat keyframes; the components that use them wrap them in `motion-ok:` so reduced motion cuts them.
 *
 * @internal Injects the chat's keyframes and tokens (typing wave, attention ring, message entrance) once per page as a hoisted `<style>`. Chat components render it for you; no props.
 *
 * @example
 * ```tsx
 * import { ChatKeyframes } from "./chat-parts";
 *
 * export const Root = () => (
 *   <>
 *     <ChatKeyframes />
 *     <div className="motion-ok:animate-[sheen-chat-in_.3s_ease-out]">New message</div>
 *   </>
 * );
 * ```
 *
 * @see /chat/thread
 */
export function ChatKeyframes() {
  return (
    <style href="sheen-chat-keyframes" precedence="default">
      {KEYFRAMES}
    </style>
  );
}

/*
 * Something new appearing (a message, the typing bubble, a badge). With motion: the keyframe
 * (rise + scale + fade). Reduced motion: CSS animations are cut to 1ms there, so it fades in
 * with a 150ms opacity transition from @starting-style instead (state changes stay visible).
 */
/** The glass look (fill, rim, shadow) without its own backdrop blur: for glass that sits on the chat's glass already (keeps the page within its blur budget). */
export const chatNoBlur = "[-webkit-backdrop-filter:none] [backdrop-filter:none]";

/** Reduced-motion counterpart of the chat's entrance animations: a short opacity fade-in (via `starting:opacity-0`), to add next to a `motion-ok:animate-*` class. */
export const chatAppearReduced =
  "motion-reduced:transition-opacity motion-reduced:duration-(--sheen-duration-fast) motion-reduced:ease-sheen-out motion-reduced:starting:opacity-0";

/* ---------- Avatars ---------- */

const avatarBox = {
  sm: "size-8",
  md: "size-10",
  lg: "size-12",
  xl: "size-14",
  "2xl": "size-20",
} as const;

/*
 * Avatar's circle is glass-1. Here it sits on the chat's own glass, where a second blur shows
 * nothing and costs a backdrop-filter pass per avatar (a list shows a dozen): the circle keeps
 * its glass fill and rim, without the blur.
 */
const avatarNoBlur = "[&>span:first-child]:[-webkit-backdrop-filter:none] [&>span:first-child]:[backdrop-filter:none]";

/* Avatar ships sm (32) / md (40) / lg (56): lg here is resized to 48px and 2xl to 80px through its root. */
const avatarBase = { sm: "sm", md: "md", lg: "md", xl: "lg", "2xl": "lg" } as const;
const avatarResize = {
  sm: "",
  md: "",
  lg: "[&>span:first-child]:size-12 [&>span:first-child]:text-sm",
  xl: "",
  "2xl": "[&>span:first-child]:size-20 [&>span:first-child]:text-2xl",
} as const;

const presenceStyle: Record<ChatPresence, string> = {
  online: "bg-sheen-success",
  away: "bg-sheen-warning",
  // Offline is a hollow ring: the three states differ by shape, not only colour.
  offline: "bg-(--sheen-surface-solid) border-2 border-sheen-fg-subtle",
};

/** Avatar diameter: "sm" 32px, "md" 40px, "lg" 48px, "xl" 56px, "2xl" 80px. */
export type ChatAvatarSize = keyof typeof avatarBox;

/** Props of {@link PresenceDot}. */
export type PresenceDotProps = {
  /** "online", "away" or "offline" (a hollow ring, so the states differ by shape too). */
  presence: ChatPresence;
  /**
   * The avatar size the dot sits on; it scales with it.
   * @default "md"
   */
  size?: ChatAvatarSize;
  /** Adds extra classes to the dot. */
  className?: string;
};

/**
 * The presence dot on an avatar. Decorative: say the presence in words next to it. Place it
 * inside a `relative` wrapper; it anchors to the bottom end corner.
 *
 * Accessibility: `aria-hidden`: the state must be written next to it. Offline is a hollow ring, and forced colors use system colours with an edge.
 *
 * @example
 * ```tsx
 * import { PresenceDot } from "@sheenui/theme";
 *
 * export const Online = () => (
 *   <span className="relative inline-block size-10 rounded-full bg-sheen-hover">
 *     <PresenceDot presence="online" />
 *   </span>
 * );
 * ```
 *
 * @see /chat/list
 */
export function PresenceDot({ presence, size = "md", className }: PresenceDotProps) {
  return (
    <span
      aria-hidden
      data-slot="presence-dot"
      data-presence={presence}
      className={cn(
        "absolute end-0 bottom-0 rounded-full ring-2 ring-(--sheen-surface-solid)",
        size === "sm" ? "size-2.5" : size === "2xl" ? "end-1 bottom-1 size-4" : size === "xl" ? "size-3.5" : "size-3",
        presenceStyle[presence],
        "forced-colors:border forced-colors:border-[CanvasText] forced-colors:ring-[Canvas]",
        presence === "online" && "forced-colors:bg-[CanvasText]",
        className,
      )}
    />
  );
}

/** Props of {@link ChatAvatar}. */
export type ChatAvatarProps = {
  /** One person (direct chat or a sender), or the group's members for a stacked group avatar. */
  people: ChatParticipant[];
  /** Group photo (wins over the stack). */
  src?: string;
  /** Group name, for its initials when there is a photo but it fails to load. */
  name?: string;
  /**
   * Diameter of the avatar: "sm" 32px, "md" 40px, "lg" 48px, "xl" 56px or "2xl" 80px.
   * @default "md"
   */
  size?: ChatAvatarSize;
  /** Show this presence dot (direct chats). */
  presence?: ChatPresence;
  /** Adds extra classes to the avatar. */
  className?: string;
};

/**
 * A person's avatar (photo or initials) with an optional presence dot, or two stacked
 * avatars for a group without a photo. Always decorative here: the name is written next to
 * it, so it is hidden from screen readers.
 *
 * Accessibility: `aria-hidden`: always shown beside the person's written name. Without a photo it shows initials on a soft accent tint over a near-opaque surface (4.5:1).
 * Glass: The circle keeps glass-1's fill and rim without its own backdrop blur, so a list of a dozen avatars costs no extra blur passes.
 *
 * @example
 * ```tsx
 * import { ChatAvatar } from "@sheenui/theme";
 *
 * export const Sender = () => <ChatAvatar people={[{ id: "u1", name: "Ada Lovelace" }]} presence="online" size="lg" />;
 * ```
 *
 * @see /chat/list
 */
export function ChatAvatar({ people, src, name, size = "md", presence, className }: ChatAvatarProps) {
  const first = people[0];
  const second = people[1];
  if (!src && first && second) {
    // Two members, overlapping corner to corner (iMessage style).
    const inner =
      size === "sm"
        ? "[&>span:first-child]:size-5 [&>span:first-child]:text-[0.5rem]"
        : size === "md"
          ? "[&>span:first-child]:size-7 [&>span:first-child]:text-2xs"
          : size === "lg"
            ? "[&>span:first-child]:size-8 [&>span:first-child]:text-xs"
            : size === "xl"
              ? "[&>span:first-child]:size-10 [&>span:first-child]:text-sm"
              : "[&>span:first-child]:size-14 [&>span:first-child]:text-base";
    return (
      <span aria-hidden className={cn("relative inline-flex shrink-0", avatarBox[size], className)}>
        <Avatar
          name={second.name}
          src={second.avatarUrl}
          size="sm"
          className={cn("absolute end-0 top-0", inner, avatarNoBlur)}
        />
        <Avatar
          name={first.name}
          src={first.avatarUrl}
          size="sm"
          className={cn(
            "absolute start-0 bottom-0 rounded-full ring-2 ring-(--sheen-surface-solid)",
            inner,
            avatarNoBlur,
          )}
        />
      </span>
    );
  }
  const person = first;
  return (
    <span aria-hidden className={cn("relative inline-flex shrink-0", avatarBox[size], className)}>
      <Avatar
        name={src ? (name ?? person?.name ?? "") : (person?.name ?? name ?? "")}
        src={src ?? person?.avatarUrl}
        size={avatarBase[size]}
        className={cn(avatarResize[size], avatarNoBlur)}
      />
      {presence && <PresenceDot presence={presence} size={size} />}
    </span>
  );
}

/* ---------- Delivery ticks ---------- */

/** Props of {@link DeliveryStatus}. */
export type DeliveryStatusProps = {
  /** "sending", "sent", "delivered", "read" or "failed". */
  status: ChatMessageStatus;
  /** The chat labels; only `status` (the spoken text per state) is used. */
  labels: Pick<ChatLabels, "status">;
  /**
   * "bubble": on the accent fill of your own bubble. "list": on glass.
   * @default "list"
   */
  variant?: "bubble" | "list";
  /**
   * Old name of `variant` (it is a visual form, not a semantic colour). Still honoured; `variant` wins.
   * @deprecated Use `variant`.
   * @default undefined
   */
  tone?: "bubble" | "list";
  /**
   * Say the state to screen readers here (off when you say it elsewhere, e.g. after the text).
   * @default true
   */
  spoken?: boolean;
  /** Adds extra classes to the icon wrapper. */
  className?: string;
};

/**
 * sending (clock) → sent (✓) → delivered (✓✓) → read (✓✓, coloured), failed (!). The state is
 * also written for screen readers, and the shapes differ, so colour is never the only cue.
 *
 * Accessibility: A hidden text ("Read") is spoken next to the icon unless `spoken` is false. Forced colors use the current text colour.
 *
 * @example
 * ```tsx
 * import { DeliveryStatus, defaultChatLabels } from "@sheenui/theme";
 *
 * export const Ticks = () => <DeliveryStatus status="read" labels={defaultChatLabels} />;
 * ```
 *
 * @see /chat/thread
 */
export function DeliveryStatus({
  status,
  labels,
  variant: variantProp,
  // eslint-disable-next-line @typescript-eslint/no-deprecated -- the deprecated alias is still honoured for one release
  tone,
  spoken = true,
  className,
}: DeliveryStatusProps) {
  if (tone !== undefined) warnOnce("DeliveryStatus: `tone` is deprecated, use `variant`.");
  const variant = variantProp ?? tone ?? "list";
  const icon =
    status === "sending" ? (
      <ClockIcon className="size-3.5" />
    ) : status === "sent" ? (
      <CheckIcon className="size-3.5" />
    ) : status === "failed" ? (
      <AlertIcon className="size-3.5 shrink-0" />
    ) : (
      <CheckCheckIcon className="size-4" />
    );
  return (
    <span
      data-status={status}
      className={cn(
        "inline-flex shrink-0 items-center",
        variant === "list"
          ? status === "read"
            ? "text-sheen-accent"
            : status === "failed"
              ? "text-sheen-danger-text"
              : "text-sheen-fg-subtle"
          : status === "read"
            ? // A light teal on the violet fill: >= 3:1 as a graphic, distinct from the white ticks.
              "text-(--sheen-teal-300)"
            : "text-sheen-accent-fg",
        "forced-colors:text-current",
        className,
      )}
    >
      {icon}
      {spoken && <span className="sr-only">{labels.status[status]}</span>}
    </span>
  );
}

/* ---------- Unread badge ---------- */

/** Props of {@link UnreadBadge}. */
export type UnreadBadgeProps = {
  /** Unread messages. Zero or less renders nothing. */
  count: number;
  /** Muted chats get a quiet grey badge. */
  muted?: boolean;
  /**
   * Text shown when the count is above 99.
   * @default "99+"
   */
  overflow?: string;
  /** Sets the screen-reader text, e.g. "3 unread messages". */
  label?: string;
  /** Adds extra classes to the badge. */
  className?: string;
};

/**
 * A round count badge for unread messages. Nothing renders at zero; above 99 it shows `overflow`.
 *
 * Accessibility: The visible number is `aria-hidden` and `label` is spoken instead, so screen readers get a full sentence. Muted badges keep an edge in forced colors.
 *
 * @example
 * ```tsx
 * import { UnreadBadge } from "@sheenui/theme";
 *
 * export const Unread = () => <UnreadBadge count={3} label="3 unread messages" />;
 * ```
 *
 * @see /chat/list
 */
export function UnreadBadge({ count, muted, overflow = "99+", label, className }: UnreadBadgeProps) {
  if (count <= 0) return null;
  return (
    <span
      data-slot="unread-badge"
      className={cn(
        "inline-flex h-5 min-w-5 shrink-0 items-center justify-center rounded-full px-1.5 text-2xs font-semibold tabular-nums",
        muted
          ? "bg-sheen-fg-subtle text-(--sheen-surface-solid) forced-colors:border forced-colors:border-[CanvasText]"
          : "sheen-fill text-sheen-accent-fg [background-image:var(--sheen-accent-fill)] shadow-[0_4px_12px_-6px_var(--sheen-accent-glow)]",
        className,
      )}
    >
      <span aria-hidden>{count > 99 ? overflow : count}</span>
      {label && <span className="sr-only">{label}</span>}
    </span>
  );
}

/* ---------- Typing dots ---------- */

/**
 * Three dots in a wave. The loop pauses while it is off screen or the tab is hidden, and rests
 * under reduced motion. Takes `className` (the dots use the current text colour).
 *
 * Accessibility: Decorative (`aria-hidden`): announce who is typing in text next to it.
 * Motion: A 1.2 s wave, paused off screen and in hidden tabs; at rest under reduced motion.
 *
 * @example
 * ```tsx
 * import { TypingDots } from "@sheenui/theme";
 *
 * export const Typing = () => (
 *   <span className="text-sheen-fg-muted">
 *     <TypingDots />
 *     <span className="sr-only">Ada is typing</span>
 *   </span>
 * );
 * ```
 *
 * @see /chat/thread
 */
export function TypingDots({ className }: { className?: string }) {
  const ref = useRef<HTMLSpanElement>(null);
  // The wave is CSS, which already rests under reduced motion; it pauses off screen and in a hidden tab (`data-paused`).
  const playing = useLoopPlayback(ref, { respectReducedMotion: false });
  return (
    <span
      ref={ref}
      aria-hidden
      data-slot="typing-dots"
      data-paused={playing ? undefined : ""}
      className={cn("inline-flex items-center gap-[3px] data-paused:*:[animation-play-state:paused]", className)}
    >
      {[0, 1, 2].map((i) => (
        <span
          key={i}
          className="size-[5px] rounded-full bg-current opacity-60 motion-ok:animate-[sheen-chat-typing_var(--sheen-duration-loop-quick)_var(--sheen-ease-in-out)_infinite]"
          style={{ animationDelay: `${i * 0.16}s` }}
        />
      ))}
    </span>
  );
}

/* ---------- Small round icon button used across the chat UI ---------- */

/** Class list for the round 36 px ghost icon buttons used across the chat UI (hover tint, focus ring, press scale). */
export const chatIconButton = cn(
  "relative inline-flex size-9 shrink-0 cursor-pointer items-center justify-center rounded-full text-sheen-fg-muted",
  "transition-[color,background-color,scale] duration-(--sheen-duration-fast) ease-sheen-out",
  "hover:bg-sheen-hover hover:text-sheen-fg motion-ok:active:scale-95",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
  "disabled:cursor-not-allowed disabled:opacity-45 disabled:hover:bg-transparent",
  "touch-manipulation [-webkit-tap-highlight-color:transparent] [&_svg]:size-[1.125rem]",
  // 44px hit area on touch screens without changing the look.
  "any-pointer-coarse:after:absolute any-pointer-coarse:after:top-1/2 any-pointer-coarse:after:left-1/2 any-pointer-coarse:after:size-11 any-pointer-coarse:after:-translate-1/2",
);

/**
 * Accessibility: Read by screen readers, hidden visually.
 *
 * @internal Text for screen readers only (the `sr-only` pattern): present in the accessibility tree, invisible on screen.
 *
 * @example
 * ```tsx
 * import { VisuallyHidden } from "./chat-parts";
 *
 * export const Count = () => (
 *   <button type="button">
 *     3<VisuallyHidden> unread messages</VisuallyHidden>
 *   </button>
 * );
 * ```
 *
 * @see /chat/list
 */
export function VisuallyHidden({ children }: { children: ReactNode }) {
  return <span className="sr-only">{children}</span>;
}

/** Props of {@link TypingDots}. Three dots in a wave. */
export type TypingDotsProps = ComponentProps<typeof TypingDots>;

"use client";

import { useCallback, useDeferredValue, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import { cn } from "../lib/cn";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { useConfirm } from "../alert-dialog/alert-dialog";
import { ContextMenu, ContextMenuContent, ContextMenuTrigger } from "../context-menu/context-menu";
import { Menu, MenuContent } from "../menu/menu";
import { Skeleton } from "../skeleton/skeleton";
import { ChatAvatar, ChatKeyframes } from "./chat-parts";
import { ChatComposer, type ChatComposerHandle } from "./composer";
import { defaultQuickReactions } from "./emoji";
import {
  conversationTitle,
  firstName,
  formatDateTime,
  isGroup,
  otherMembers,
  toDate,
  toParticipantMap,
} from "./format";
import { useAnnouncer, useCoarsePointer, useKeyboardInset, useNow } from "./hooks";
import { resolveChatLabels } from "./labels";
import { ImageLightbox } from "./message-parts";
import { TypingBubble } from "./message-row";
import { createToolbarStore } from "./toolbar-store";
import type { ChatMessage } from "./types";
import { type ChatThreadProps } from "./thread/types";
import { buildDays, type Day } from "./thread/layout";
import { usePrependedMessages } from "./thread/use-prepend";
import { useThreadOverlays } from "./thread/use-thread-overlays";
import { useMessageActions } from "./thread/use-message-actions";
import { useThreadScroll } from "./thread/use-thread-scroll";
import { MessageMenuItems, type MessageMenuContext } from "./thread/menu-items";
import { ThreadDays } from "./thread/days";
import { ThreadHeader } from "./thread/header";
import { ReactionPanel, ReactionPicker, MessageInfo, JumpToLatest, ThreadNotice } from "./thread/parts";
import { useMergedRef } from "../lib/form";

export { type ChatThreadProps } from "./thread/types";

/**
 * One conversation: header, the message log and the composer. WhatsApp / iMessage-style
 * bubbles grouped by sender, sticky day labels, replies, reactions, photos, files, link
 * previews, delivery ticks, edits and deletes, typing, "Jump to latest" and loading of earlier
 * messages that keeps the reader's place.
 *
 * Keyboard: the log is one tab stop. ↑ / ↓ move between messages (Home / End, Page Up / Down),
 * Enter opens a message's actions, R replies, E edits your own; Tab moves on through that
 * message's links and buttons, then out of the log. Right-click (or long-press on touch, or
 * Shift + F10) opens the same actions.
 *
 * Screen readers: the log is role="log", but it is not a live region itself: only new incoming
 * messages are announced (once), never history that loads above or your own messages.
 *
 * Props: see {@link ChatThreadProps}. The chat is controlled: pass `conversation`, `messages`
 * (oldest first), `participants` and `currentUserId`, and handle `onSend`, `onEdit`, `onDelete`,
 * `onReact`, `onRetry`, `onLoadOlder` (with `hasOlder` / `loadingOlder`), `onRead`, `onTyping`.
 * Look: `showHeader` true, `showComposer` true, `density` "comfortable", `surface` "glass",
 * `labels`, `locale`, `className`.
 *
 * Accessibility: The header names the chat (heading level set by `headingLevel`); presence is written in words; delivery state, reactions and typing are spoken; the "Jump to latest" button and composer controls have names. Targets are 44px on touch screens, and forced colors give bubbles real borders.
 * Glass: One glass panel (`surface="glass"`); incoming bubbles reuse the look without their own blur so a long thread stays within the backdrop-blur budget.
 * Motion: New messages spring in, the typing dots wave and the log scrolls smoothly; reduced motion shortens these to fades and instant jumps.
 *
 * @example
 * ```tsx
 * import { useState } from "react";
 * import { ChatThread, type ChatDraft, type ChatMessage } from "@sheenui/theme";
 *
 * const people = [
 *   { id: "me", name: "You" },
 *   { id: "riya", name: "Riya Sharma", presence: "online" as const },
 * ];
 *
 * export function Support() {
 *   const [messages, setMessages] = useState<ChatMessage[]>([
 *     { id: "1", senderId: "riya", text: "Hi! How can I help?", createdAt: "2026-11-08T09:00:00Z" },
 *   ]);
 *   const send = (draft: ChatDraft) =>
 *     setMessages((list) => [...list, { id: String(list.length + 1), senderId: "me", text: draft.text, createdAt: new Date(), status: "sent" }]);
 *   return (
 *     <ChatThread
 *       conversation={{ id: "c1", participantIds: ["me", "riya"] }}
 *       messages={messages}
 *       participants={people}
 *       currentUserId="me"
 *       onSend={send}
 *     />
 *   );
 * }
 * ```
 *
 * @see /chat/thread
 */
export function ChatThread({
  conversation,
  messages: messagesProp,
  participants,
  currentUserId,
  onSend,
  onEdit,
  onDelete,
  onReact,
  onRetry,
  onLoadOlder,
  hasOlder = false,
  loadingOlder = false,
  onRead,
  onTyping,
  firstUnreadId,
  showHeader = true,
  onBack,
  onCall,
  onVideoCall,
  onInfo,
  headerActions,
  headingLevel = 2,
  headingRef,
  showComposer = true,
  draft,
  onDraftChange,
  quickReplies,
  quickReactions = defaultQuickReactions,
  allowAttachments = true,
  accept,
  composerRef: composerRefProp,
  autoFocus = false,
  density = "comfortable",
  surface = "glass",
  emptyState,
  now: nowProp,
  locale,
  labels: labelsProp,
  className,
}: ChatThreadProps) {
  const L = useMemo(() => resolveChatLabels(labelsProp), [labelsProp]);
  /*
   * A big change (30 earlier messages at once) renders in the background in small slices, so
   * scrolling and typing never wait for it; a single new message still shows in the next frame.
   * Everything below works from this value, so what is measured is what is on screen.
   */
  const messages = useDeferredValue(messagesProp);
  const reduced = useSheenReducedMotion();
  const coarse = useCoarsePointer();
  const now = useNow(nowProp);
  const baseId = useId();
  const titleId = `${baseId}-title`;
  const hintId = `${baseId}-hint`;
  const [announce, announcer] = useAnnouncer();
  const [confirm, confirmDialog] = useConfirm();

  const people = useMemo(() => toParticipantMap(participants), [participants]);
  const group = isGroup(conversation);
  const others = useMemo(
    () => otherMembers(conversation, people, currentUserId),
    [conversation, people, currentUserId],
  );
  const title = conversationTitle(conversation, people, currentUserId);
  const nameOf = useCallback(
    (id: string) => (id === currentUserId ? L.you : (people.get(id)?.name ?? id)),
    [people, currentUserId, L.you],
  );
  const domIdOf = useCallback((id: string) => `${baseId}-m-${id}`, [baseId]);
  const byId = useMemo(() => new Map(messages.map((m) => [m.id, m])), [messages]);

  /* ----- Earlier messages, a few at a time (see thread/use-prepend.ts) ----- */
  const { hiddenOlder, shown } = usePrependedMessages(messages);

  /* ----- Days and runs ----- */
  const days = useMemo<Day[]>(
    () => buildDays(shown, { firstUnreadId, now, locale, group, currentUserId }),
    [shown, firstUnreadId, now, locale, group, currentUserId],
  );

  /* ----- Roving focus ----- */
  const lastId = messages[messages.length - 1]?.id ?? null;
  const [activeIdState, setActiveId] = useState<string | null>(null);
  const activeId = activeIdState && byId.has(activeIdState) ? activeIdState : lastId;
  /*
   * Which row shows the hover toolbar (pinned while its menu is open, else hovered, else keyboard-focused).
   * An external store, not state: a hover re-renders the two rows involved, not the whole thread.
   */
  const [toolbar] = useState(createToolbarStore);
  const setPinnedId = toolbar.setPinned;
  const setKeyboardFocusId = toolbar.setKeyboard;
  useLayoutEffect(() => toolbar.setCoarse(coarse), [toolbar, coarse]);

  /* ----- Overlays: reply / edit, photos, reactions, info, context menu, notices (see thread/use-thread-overlays.ts) ----- */
  const ov = useThreadOverlays(announce);

  /* ----- Composer ref (ours + the caller's) ----- */
  const composer = useRef<ChatComposerHandle | null>(null);
  const setComposer = useMergedRef(composer, composerRefProp);

  /* ----- On-screen keyboard: the composer stays just above it (touch, while typing) ----- */
  const sectionRef = useRef<HTMLElement>(null);
  const [typingHere, setTypingHere] = useState(false);
  const keyboardInset = useKeyboardInset(sectionRef, coarse && typingHere && showComposer);

  /* ----- Scrolling (see thread/use-thread-scroll.ts) ----- */
  const {
    scrollRef,
    contentRef,
    setStick,
    jump,
    dayPillRef,
    noteUserScroll,
    onScroll,
    jumpToLatest,
    typingPeople,
    appearing,
    setPendingFocusUp,
  } = useThreadScroll({
    messages,
    conversation,
    people,
    currentUserId,
    lastId,
    hiddenOlder,
    firstUnreadId,
    hasOlder,
    loadingOlder,
    onLoadOlder,
    onRead,
    reduced,
    showComposer,
    composer,
    domIdOf,
    announce,
    L,
    nameOf,
  });

  /* ----- Message actions and the log's keyboard model (see thread/use-message-actions.ts) ----- */
  const { startReply, canEdit, startEdit, toggleReaction, copy, remove, actions, editLast } = useMessageActions({
    messages,
    currentUserId,
    hasOlder,
    loadingOlder,
    onEdit,
    onDelete,
    onReact,
    onRetry,
    onLoadOlder,
    L,
    reduced,
    nameOf,
    domIdOf,
    announce,
    confirm,
    showNotice: ov.showNotice,
    flash: ov.flash,
    setStick,
    setPendingFocusUp,
    toolbar,
    moreMenu: ov.moreMenu,
    setActiveId,
    setReplyTo: ov.setReplyTo,
    setEditing: ov.setEditing,
    setLightbox: ov.setLightbox,
    setReactionTarget: ov.setReactionTarget,
    setReactionFromId: ov.setReactionFromId,
  });

  /* ----- Menus ----- */
  const menuMessage = (id: string | null | undefined) => (id ? byId.get(id) : undefined);
  const contextMessage = menuMessage(ov.contextId);

  const openReactionsFor = (m: ChatMessage) => {
    const node = document.getElementById(domIdOf(m.id));
    setPinnedId(m.id);
    ov.setReactionFromId(m.id);
    ov.setReactionTarget({
      messageId: m.id,
      anchor: node?.querySelector<HTMLElement>("[data-message-id] > div:last-child") ?? node,
    });
  };
  const openInfoFor = (m: ChatMessage) => {
    ov.setInfoFromId(m.id);
    ov.setInfoId(m.id);
  };
  const menuContext: MessageMenuContext = {
    currentUserId,
    L,
    coarse,
    quickReactions,
    hasReact: Boolean(onReact),
    onRetry,
    hasDelete: Boolean(onDelete),
    toggleReaction,
    openReactionsFor,
    openInfoFor,
    startReply,
    startEdit,
    canEdit,
    copy,
    remove,
  };

  const messageIdFrom = (target: EventTarget | null) => {
    const node = target instanceof Element ? target.closest<HTMLElement>("[data-message-id]") : null;
    if (!node || node.dataset.system !== undefined) return null;
    const m = byId.get(node.dataset.messageId ?? "");
    return m && !m.deleted ? m.id : null;
  };

  const reactionMessage = menuMessage(ov.reactionTarget?.messageId);
  const infoMessage = menuMessage(ov.infoId);
  const lightboxMessage = menuMessage(ov.lightbox?.messageId);
  const lightboxImages = (lightboxMessage?.attachments ?? []).filter((a) => a.kind === "image");
  const empty = messages.length === 0;

  const closeReactions = () => {
    ov.setReactionTarget(null);
    setPinnedId(null);
  };
  /*
   * Back to the message once the picker (or info) has closed. Base UI moves focus there itself
   * after its exit, only when focus was still inside the popup: a click elsewhere keeps its focus.
   */
  const messageNode = (id: string | null) => () => (id ? document.getElementById(domIdOf(id)) : null) ?? true;

  return (
    <section
      ref={sectionRef}
      role="group"
      aria-labelledby={titleId}
      data-slot="chat-thread"
      className={cn(
        "@container relative flex h-full min-h-0 w-full min-w-0 flex-col overflow-hidden [--chat-own-fill:var(--sheen-accent-fill)]",
        surface === "glass" && "glass-3 rounded-sheen-xl",
        className,
      )}
    >
      <ChatKeyframes />

      <ThreadHeader
        showHeader={showHeader}
        conversation={conversation}
        others={others}
        typingPeople={typingPeople}
        group={group}
        title={title}
        titleId={titleId}
        headingLevel={headingLevel}
        headingRef={headingRef}
        density={density}
        L={L}
        now={now}
        locale={locale}
        onBack={onBack}
        onCall={onCall}
        onVideoCall={onVideoCall}
        onInfo={onInfo}
        headerActions={headerActions}
      />

      {/* Log */}
      <div className="relative flex min-h-0 flex-1 flex-col">
        <div
          ref={scrollRef}
          data-chat-log=""
          // Observer-only listeners: any scroll gesture or key press tells the log the reader took over; the messages inside carry the roles.
          role="presentation"
          onScroll={onScroll}
          onWheel={noteUserScroll}
          onTouchStart={noteUserScroll}
          onKeyDown={noteUserScroll}
          // The scrollbar (a press on the log itself, not on a message).
          onPointerDown={(e) => e.target === e.currentTarget && noteUserScroll()}
          className={cn(
            "group/log min-h-0 flex-1 overflow-x-hidden overflow-y-auto overscroll-contain [overflow-anchor:none] [scrollbar-gutter:stable] [scrollbar-width:thin]",
            // A faint dotted wallpaper, like a chat app's background.
            "[background-image:radial-gradient(var(--sheen-border)_1px,transparent_1.2px)] [background-size:20px_20px]",
          )}
        >
          {empty ? (
            (emptyState ?? (
              <div className="flex min-h-full flex-col items-center justify-center gap-3 p-6 text-center">
                <ChatAvatar people={others.slice(0, 2)} src={conversation.avatarUrl} name={title} size="xl" />
                <p className="text-base font-semibold">{title}</p>
                <p className="max-w-xs text-sm text-sheen-fg-muted">{L.beginning(title)}</p>
              </div>
            ))
          ) : (
            <ContextMenu onOpenChangeComplete={ov.onContextOpenChangeComplete} onOpenChange={ov.onContextOpenChange}>
              <ContextMenuTrigger
                {...ov.longPressGuard}
                role="log"
                aria-live="off"
                aria-label={L.messagesWith(title)}
                aria-describedby={hintId}
                aria-busy={loadingOlder || hiddenOlder > 0 || undefined}
                onPointerDownCapture={(e) =>
                  (e.button === 2 || e.pointerType === "touch") && ov.setContextId(messageIdFrom(e.target))
                }
                onContextMenuCapture={(e) => {
                  const id = messageIdFrom(e.target);
                  if (!id) {
                    // Not on a message: leave the browser's own menu alone.
                    e.stopPropagation();
                    return;
                  }
                  ov.setContextId(id);
                }}
                onFocusCapture={(e) => {
                  const node = (e.target as HTMLElement).closest<HTMLElement>("[data-message-id]");
                  const visible = (e.target as HTMLElement).matches(":focus-visible");
                  setKeyboardFocusId(node && visible ? (node.dataset.messageId ?? null) : null);
                }}
                onBlurCapture={(e) => {
                  if (!e.currentTarget.contains(e.relatedTarget)) setKeyboardFocusId(null);
                }}
                className="flex min-h-full flex-col justify-end pb-3 select-text group-data-[scrolling]/log:pointer-events-none pointer-coarse:select-none focus-visible:outline-none"
              >
                <div ref={contentRef} className="flex flex-col">
                  {/* Top: earlier messages loading, or the start of the chat */}
                  {hasOlder || hiddenOlder > 0 ? (
                    // The space is kept (no jump when loading starts); the shimmering skeletons exist only while loading.
                    <div aria-hidden className="flex flex-col gap-2 px-4 pt-4" style={{ height: 136 }}>
                      {(loadingOlder || hiddenOlder > 0) && (
                        <>
                          <Skeleton shape="rect" width="52%" height={36} className="rounded-[1.25rem]" />
                          <Skeleton shape="rect" width="38%" height={36} className="ms-auto rounded-[1.25rem]" />
                          <Skeleton shape="rect" width="44%" height={36} className="rounded-[1.25rem]" />
                        </>
                      )}
                    </div>
                  ) : (
                    <div className="flex flex-col items-center gap-2 px-6 pt-8 pb-2 text-center">
                      <ChatAvatar people={others.slice(0, 2)} src={conversation.avatarUrl} name={title} size="lg" />
                      <p className="max-w-xs text-xs text-sheen-fg-muted">{L.beginning(title)}</p>
                    </div>
                  )}
                  {loadingOlder && <p className="sr-only">{L.loadingOlder}</p>}

                  <ThreadDays
                    days={days}
                    people={people}
                    currentUserId={currentUserId}
                    group={group}
                    activeId={activeId}
                    flashId={ov.flashId}
                    appearing={appearing}
                    nameOf={nameOf}
                    domIdOf={domIdOf}
                    density={density}
                    locale={locale}
                    L={L}
                    actions={actions}
                  />

                  {typingPeople.length > 0 && (
                    <TypingBubble
                      people={typingPeople}
                      avatarColumn={group}
                      label={L.typing(
                        typingPeople.map((p) => firstName(p.name)),
                        group,
                      )}
                    />
                  )}
                </div>
              </ContextMenuTrigger>
              <ContextMenuContent className="min-w-60">
                {contextMessage ? <MessageMenuItems message={contextMessage} from="context" ctx={menuContext} /> : null}
              </ContextMenuContent>
            </ContextMenu>
          )}
        </div>

        <p id={hintId} hidden>
          {L.logHint}
        </p>

        {/* The day at the top of the log, while scrolling (see updateDayPill). Its own glass fades, nothing else. */}
        <div aria-hidden className="pointer-events-none absolute inset-x-0 top-2 z-[2] flex justify-center">
          <span
            ref={dayPillRef}
            className={cn(
              "glass-2 rounded-full px-3 py-1 text-xs font-medium text-sheen-fg-muted shadow-sm empty:hidden",
              "opacity-0 transition-opacity duration-(--sheen-duration-fast) ease-sheen-out data-show:opacity-100",
            )}
          />
        </div>

        {/* Jump to latest */}
        <div className="pointer-events-none absolute end-3 bottom-3 z-[3] flex flex-col items-end gap-2 @lg:end-5">
          <JumpToLatest
            store={jump}
            empty={empty}
            reduced={reduced}
            label={L.jumpToLatest}
            newBelow={L.newBelow}
            onJump={jumpToLatest}
          />
        </div>

        {/* "Copied" and similar short notes */}
        <div className="pointer-events-none absolute inset-x-0 bottom-3 z-[3] flex justify-center px-16">
          <ThreadNotice notice={ov.notice} reduced={reduced} />
        </div>
      </div>

      {showComposer && (
        <div
          className="relative z-[4] shrink-0 border-t border-sheen-border"
          // Raised above the on-screen keyboard; the log shrinks (and keeps its newest message in view).
          style={keyboardInset ? { paddingBottom: keyboardInset } : undefined}
          onFocusCapture={(e) => (e.target as HTMLElement).localName === "textarea" && setTypingHere(true)}
          onBlurCapture={(e) => (e.target as HTMLElement).localName === "textarea" && setTypingHere(false)}
        >
          <ChatComposer
            ref={setComposer}
            onSend={(d) => {
              onSend?.(d);
              ov.setReplyTo(null);
              setStick(true);
            }}
            value={draft}
            onValueChange={onDraftChange}
            replyTo={ov.replyTo}
            onCancelReply={() => ov.setReplyTo(null)}
            editing={ov.editing}
            onSaveEdit={(id, text) => {
              onEdit?.(id, text);
              ov.setEditing(null);
            }}
            onCancelEdit={() => ov.setEditing(null)}
            onEditLast={onEdit ? editLast : undefined}
            onTyping={onTyping}
            nameOf={nameOf}
            title={title}
            quickReplies={quickReplies}
            allowAttachments={allowAttachments}
            accept={accept}
            // eslint-disable-next-line jsx-a11y/no-autofocus -- an opt-in prop (default false) forwarded to the composer; the integrator decides when the thread is the page's main task
            autoFocus={autoFocus}
            density={density}
            locale={locale}
            labels={labelsProp}
          />
        </div>
      )}

      {/* The ⋯ menu of the hover toolbar (one for every message) */}
      <Menu
        handle={ov.moreMenu}
        onOpenChange={(open, details) => {
          if (open) {
            const id = (details.trigger as HTMLElement | undefined)?.closest<HTMLElement>("[data-message-id]")?.dataset
              .messageId;
            if (id) setPinnedId(id);
          } else if (!ov.reactionTarget) setPinnedId(null);
        }}
      >
        {({ payload }: { payload: string | undefined }) => {
          const m = menuMessage(payload);
          return (
            <MenuContent className="min-w-60" side="bottom" align="end">
              {m ? <MessageMenuItems message={m} from="more" ctx={menuContext} /> : null}
            </MenuContent>
          );
        }}
      </Menu>

      {/* Reaction picker: a popover beside the bubble (mouse), a bottom sheet (touch) */}
      <ReactionPicker
        open={Boolean(reactionMessage)}
        coarse={coarse}
        anchor={ov.reactionTarget?.anchor ?? null}
        align={reactionMessage?.senderId === currentUserId ? "end" : "start"}
        label={L.addReaction}
        finalFocus={messageNode(ov.reactionFromId)}
        onClose={closeReactions}
      >
        {reactionMessage && (
          <ReactionPanel
            message={reactionMessage}
            currentUserId={currentUserId}
            quickReactions={quickReactions}
            labels={L}
            labelsProp={labelsProp}
            coarse={coarse}
            onPick={(emoji) => {
              toggleReaction(reactionMessage, emoji);
              closeReactions();
            }}
          />
        )}
      </ReactionPicker>

      {/* Message info */}
      <MessageInfo
        message={infoMessage}
        coarse={coarse}
        locale={locale}
        labels={L}
        returnFocus={messageNode(ov.infoFromId)}
        onClose={() => ov.setInfoId(null)}
      />

      {/* Photos */}
      <ImageLightbox
        images={lightboxImages}
        index={ov.lightbox?.index ?? null}
        onIndexChange={(index) => ov.setLightbox((l) => (l ? { ...l, index } : null))}
        labels={L}
        caption={
          lightboxMessage
            ? `${nameOf(lightboxMessage.senderId)} · ${formatDateTime(toDate(lightboxMessage.createdAt) ?? now, locale)}`
            : undefined
        }
        finalFocus={() =>
          ov.lightbox
            ? document
                .getElementById(domIdOf(ov.lightbox.messageId))
                ?.querySelector<HTMLElement>(`[data-photo-index="${ov.lightbox.from}"]`)
            : null
        }
      />

      {confirmDialog}
      {announcer}
    </section>
  );
}

"use client";

import { useCallback, useEffect, useId, useMemo, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { AnimatePresence, motion } from "motion/react";

import { cn } from "../lib/cn";
import { HEADING_TAGS, headingBelow, type HeadingLevelOption } from "../lib/heading";
import { useControllable } from "../hooks/use-controllable";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { duration, spring } from "../motion/tokens";
import { exitTransition } from "../motion/presets";
import { Button } from "../button/button";
import { Tooltip } from "../tooltip/tooltip";
import { ChatAvatar, ChatKeyframes, UnreadBadge, chatAppearReduced, chatIconButton } from "./chat-parts";
import { ChatThread, type ChatThreadProps } from "./chat-thread";
import type { ChatComposerHandle } from "./composer";
import { conversationTitle, formatListTime, messageSummary, toDate, toParticipantMap, toTime } from "./format";
import { PHONE_QUERY, useCoarsePointer, useMediaQuery, useModalIsolation, useNow, useVisualViewport } from "./hooks";
import { resolveChatLabels, type ChatLabels } from "./labels";
import type { ChatConversation, ChatDraft, ChatMessage, ChatParticipant } from "./types";
import { ChatFilledIcon, ChevronDownIcon, ChevronLeftIcon, ChevronRightIcon, SendIcon } from "./icons";

/** Props of {@link ChatWidget}. Required: `conversations`, `messages`, `participants`, `currentUserId`. */
export type ChatWidgetProps = {
  /** The support chats this visitor has had, newest activity first. */
  conversations: ChatConversation[];
  /** Takes messages per chat id (oldest first). */
  messages: Record<string, ChatMessage[] | undefined>;
  /** Everyone who can appear: the visitor and the team. */
  participants: ChatParticipant[];
  /** Id of the visitor, used to tell which messages are theirs. */
  currentUserId: string;
  /** The team shown in the header (participant ids); defaults to everyone except you. */
  teamIds?: string[];
  /** Whether the panel is open (controlled). */
  open?: boolean;
  /**
   * Whether the panel starts open (uncontrolled).
   * @default false
   */
  defaultOpen?: boolean;
  /** Called with the new state when the panel opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /** The chat shown in the panel; null shows the home view. */
  conversationId?: string | null;
  /**
   * The chat shown on mount (uncontrolled); null is the home view.
   * @default null
   */
  defaultConversationId?: string | null;
  /** Called with the chat id when the visitor opens a chat, or null when they go back home. */
  onConversationChange?: (conversationId: string | null) => void;
  /** "Send us a message": create a chat and return its id (it opens once it is in `conversations`). */
  onNewConversation?: (() => string) | (() => void);
  /** The visitor sent a message in the chat with this id. */
  onSend?: (conversationId: string, draft: ChatDraft) => void;
  /** Called when the visitor adds or removes a reaction. */
  onReact?: (conversationId: string, message: ChatMessage, emoji: string, add: boolean) => void;
  /** The visitor pressed Retry on a failed message. */
  onRetry?: (conversationId: string, message: ChatMessage) => void;
  /** The visitor saw the newest message of this chat: mark it read. */
  onRead?: (conversationId: string) => void;
  /** Chips that send a ready-made message (shown in a chat until you write something). */
  quickReplies?: string[];
  /** Extra props for the chat view inside the panel. */
  threadProps?: Partial<ChatThreadProps>;
  /** Content above "Send us a message" on the home view (a status line…). */
  homeContent?: ReactNode;
  /** Help articles under the recent conversations on the home view ("Find an answer"). */
  helpLinks?: ChatWidgetLink[];
  /**
   * Sets the physical corner of the launcher.
   * @default "right"
   */
  position?: "right" | "left";
  /**
   * "fixed" to the window, or "absolute" inside a positioned box (previews, docs).
   * @default "fixed"
   */
  strategy?: "fixed" | "absolute";
  /** The launcher's badge; defaults to the unread count of every chat. */
  unreadCount?: number;
  /**
   * The current time for "5m" labels. Default: the real clock, refreshed every 30 seconds. On a
   * prerendered or server-rendered page pass a fixed date, so the HTML matches what the browser
   * renders when it hydrates.
   */
  now?: Date;
  /** Sets the BCP 47 locale for times and dates. Default: the browser's; pass one on prerendered pages. */
  locale?: string;
  /** Any UI string (i18n); see {@link ChatLabels}. */
  labels?: Partial<ChatLabels>;
  /**
   * Heading level (2 or 3) of the panel's headings ("Recent conversations", help articles) and of the open conversation's title, to fit the page outline.
   * `"none"` renders them as paragraphs, for a widget shown as an example.
   * @default 3
   */
  headingLevel?: HeadingLevelOption;
  /** Classes for the outer element (the launcher's corner). */
  className?: string;
};

/** A help article on the widget's home view. */
export type ChatWidgetLink = {
  /** Link text. */
  label: string;
  /** Link address. */
  href: string;
  /** A second line (e.g. the section of the help centre). */
  description?: string;
  /** Open in a new tab. */
  newTab?: boolean;
};

/* Cards on the panel's own glass: the glass look without a second blur (nothing but the panel is behind them). */
const homeCard = "glass-2 [-webkit-backdrop-filter:none] [backdrop-filter:none] flex flex-col rounded-sheen-lg";

/**
 * A support chat in the corner of the page (Intercom style). The launcher shows unread
 * messages and pulses gently until the first open. The glass panel springs out of it (a quick
 * fade with reduced motion) and is a non-modal dialog: the page stays usable, Escape or the
 * minimise button closes it and focus goes back to the launcher. Home shows a greeting, recent
 * chats and "Send us a message"; a chat is the full chat view in compact density, with
 * quick-reply chips. Under 640px wide the panel is a full-screen sheet that stays above the
 * on-screen keyboard.
 *
 * Props: see {@link ChatWidgetProps}. Data: `conversations`, `messages` (per chat id),
 * `participants`, `currentUserId`, `teamIds`. State: `open` / `defaultOpen` / `onOpenChange`,
 * `conversationId` / `defaultConversationId` / `onConversationChange`. Events: `onNewConversation`,
 * `onSend`, `onReact`, `onRetry`, `onRead`. Look: `position` "right", `strategy` "fixed",
 * `quickReplies`, `homeContent`, `helpLinks`, `unreadCount`, `threadProps`, `labels`, `locale`, `now`.
 *
 * Keyboard: Enter or Space on the launcher opens the panel; Escape or the minimise button closes it and returns focus to the launcher (Escape inside a menu, the emoji picker or the photo viewer closes only that). The chat inside follows the ChatThread keys. On phones the full-screen sheet is modal: Tab stays inside it.
 * Accessibility: A dialog named by the team header (`aria-modal` only on phones, where the sheet covers the page); the launcher has `aria-expanded` and an unread count in its name; the sheet makes the page behind inert and keeps the composer above the on-screen keyboard.
 * Glass: One glass panel; home cards and bubbles reuse the look without extra blur layers.
 * Motion: The launcher pulses gently until the first open, and the panel springs out of it; reduced motion uses a quick fade.
 *
 * @example
 * ```tsx
 * import { useState } from "react";
 * import { ChatWidget, type ChatConversation, type ChatMessage } from "@sheenui/theme";
 *
 * const people = [
 *   { id: "me", name: "You" },
 *   { id: "sam", name: "Sam from Support", role: "Support" },
 * ];
 *
 * export function SupportWidget() {
 *   const [conversations] = useState<ChatConversation[]>([{ id: "c1", participantIds: ["me", "sam"] }]);
 *   const [messages] = useState<Record<string, ChatMessage[]>>({
 *     c1: [{ id: "1", senderId: "sam", text: "Hi! Need a hand?", createdAt: "2026-11-08T09:00:00Z" }],
 *   });
 *   return <ChatWidget conversations={conversations} messages={messages} participants={people} currentUserId="me" onSend={(id, draft) => console.log(id, draft.text)} />;
 * }
 * ```
 *
 * @see /chat/widget
 */
export function ChatWidget({
  conversations,
  messages,
  participants,
  currentUserId,
  teamIds,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  conversationId: conversationProp,
  defaultConversationId = null,
  onConversationChange,
  onNewConversation,
  onSend,
  onReact,
  onRetry,
  onRead,
  quickReplies,
  threadProps,
  homeContent,
  helpLinks,
  position = "right",
  strategy = "fixed",
  unreadCount,
  now: nowProp,
  locale,
  labels: labelsProp,
  headingLevel = 3,
  className,
}: ChatWidgetProps) {
  const SectionHeading = HEADING_TAGS[headingBelow(headingLevel, 0)];
  const L = useMemo(() => resolveChatLabels(labelsProp), [labelsProp]);
  const reduced = useSheenReducedMotion();
  const coarse = useCoarsePointer();
  const now = useNow(nowProp);
  const id = useId();
  const panelId = `${id}-panel`;
  const titleId = `${id}-title`;
  const subtitleId = `${id}-subtitle`;
  const people = useMemo(() => toParticipantMap(participants), [participants]);
  // Inside the panel the chat is "with the team": a neutral placeholder and start note.
  const threadLabels = useMemo<Partial<ChatLabels>>(
    () => ({ placeholder: () => L.placeholder(undefined), beginning: () => L.greetingDescription, ...labelsProp }),
    [L, labelsProp],
  );

  const [open, setOpenValue] = useControllable(openProp, defaultOpen, onOpenChange);
  const [conversationId, setConversation] = useControllable<string | null>(
    conversationProp,
    defaultConversationId,
    onConversationChange,
  );

  const launcherRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const composerRef = useRef<ChatComposerHandle | null>(null);
  const [opened, setOpened] = useState(defaultOpen);

  const setOpen = useCallback(
    (next: boolean, returnFocus = true) => {
      if (next) setOpened(true);
      setOpenValue(next);
      if (!next && returnFocus) {
        // Back to the launcher when focus was in the panel (or on the launcher).
        const active = document.activeElement;
        if (
          !active ||
          active === document.body ||
          panelRef.current?.contains(active) ||
          active === launcherRef.current
        ) {
          requestAnimationFrame(() => launcherRef.current?.focus({ preventScroll: true }));
        }
      }
    },
    [setOpenValue],
  );

  // Open: focus moves into the panel (the dialog itself, so its name is read first).
  useEffect(() => {
    if (open) requestAnimationFrame(() => panelRef.current?.focus({ preventScroll: true }));
  }, [open]);

  const narrow = useMediaQuery(PHONE_QUERY);
  const sheet = narrow;
  const box = useVisualViewport(open && sheet && strategy === "fixed");
  /*
   * A full-screen sheet covers the whole page, so it is modal (aria-modal, the page behind is
   * inert and doesn't scroll): Tab and a screen reader's swipe stay in the chat. The desktop
   * panel (and a sheet inside a box, strategy="absolute") stays non-modal: the page is usable.
   */
  const modal = sheet && strategy === "fixed";
  useModalIsolation(panelRef, open && modal);

  const team = useMemo(() => {
    const ids = teamIds ?? participants.filter((p) => p.id !== currentUserId).map((p) => p.id);
    return ids.flatMap((pid) => people.get(pid) ?? []);
  }, [teamIds, participants, currentUserId, people]);

  const badge = unreadCount ?? conversations.reduce((n, c) => n + (c.unreadCount ?? 0), 0);
  const conversation = conversationId ? conversations.find((c) => c.id === conversationId) : undefined;
  const recent = useMemo(
    () =>
      [...conversations]
        .sort(
          (a, b) => toTime(b.lastMessage?.createdAt ?? b.updatedAt) - toTime(a.lastMessage?.createdAt ?? a.updatedAt),
        )
        .slice(0, 3),
    [conversations],
  );

  // Where to put focus after switching views.
  const view = conversation ? "thread" : "home";
  const lastView = useRef(view);
  const backTarget = useRef<string | null>(null);
  useEffect(() => {
    if (lastView.current === view) return;
    lastView.current = view;
    requestAnimationFrame(() => {
      const panel = panelRef.current;
      if (!panel) return;
      if (view === "thread") {
        if (!coarse) composerRef.current?.focus();
        else panel.querySelector<HTMLElement>("[data-widget-back]")?.focus({ preventScroll: true });
      } else {
        const target = backTarget.current
          ? panel.querySelector<HTMLElement>(`[data-widget-conversation="${CSS.escape(backTarget.current)}"]`)
          : null;
        (target ?? panel.querySelector<HTMLElement>("[data-widget-start]"))?.focus({ preventScroll: true });
      }
    });
  }, [view, coarse]);

  function onPanelKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key !== "Escape" || event.defaultPrevented) return;
    // React events bubble out of portals: Escape in a menu, the emoji picker or the photo viewer
    // opened from the panel closes that popup, not the whole chat.
    if (!(event.target instanceof Node) || !event.currentTarget.contains(event.target)) return;
    event.preventDefault();
    setOpen(false);
  }

  function startNew() {
    const created = onNewConversation?.();
    if (created) {
      backTarget.current = null;
      setConversation(created);
    }
  }

  const right = position === "right";
  const corner = right
    ? "right-[max(1.25rem,env(safe-area-inset-right))]"
    : "left-[max(1.25rem,env(safe-area-inset-left))]";
  const origin = right ? "bottom right" : "bottom left";

  const headerPeople = team.slice(0, 3);
  const agent = conversation
    ? (conversation.participantIds.map((p) => people.get(p)).find((p) => p && p.id !== currentUserId) ?? team[0])
    : team[0];

  /* ----- Panel ----- */
  const panelMotion = reduced
    ? {
        initial: { opacity: 0 },
        animate: { opacity: 1, transition: { duration: duration.fast } },
        exit: { opacity: 0, transition: exitTransition },
      }
    : sheet
      ? {
          initial: { y: "100%" },
          animate: { y: 0, transition: spring.gentle },
          exit: { y: "100%", transition: { ...exitTransition, duration: duration.base } },
        }
      : {
          initial: { opacity: 0, scale: 0.4, y: 28 },
          animate: {
            opacity: 1,
            scale: 1,
            y: 0,
            transition: { ...spring.gentle, opacity: { duration: duration.fast } },
          },
          exit: { opacity: 0, scale: 0.85, y: 16, transition: exitTransition },
        };

  const slide = (direction: 1 | -1) =>
    reduced
      ? { initial: false as const, animate: { x: 0 }, exit: { x: 0, transition: { duration: 0 } } }
      : {
          initial: { x: `${direction * 100}%` },
          animate: { x: 0, transition: spring.gentle },
          exit: { x: `${direction * -30}%`, transition: exitTransition },
        };

  const minimize = (
    <Tooltip content={L.minimize} delay={300}>
      <button
        type="button"
        onClick={() => setOpen(false)}
        aria-label={L.minimize}
        className={cn(chatIconButton, "text-current hover:bg-sheen-accent-fg/15 hover:text-current")}
      >
        <ChevronDownIcon className="size-5" />
      </button>
    </Tooltip>
  );

  return (
    <>
      <ChatKeyframes />
      <AnimatePresence>
        {open && (
          <motion.div
            key="panel"
            ref={panelRef}
            id={panelId}
            role="dialog"
            aria-modal={modal ? "true" : "false"}
            aria-labelledby={titleId}
            aria-describedby={subtitleId}
            tabIndex={-1}
            onKeyDown={onPanelKeyDown}
            data-slot="chat-widget-panel"
            {...panelMotion}
            style={{
              transformOrigin: origin,
              ...(box && sheet ? { top: box.offsetTop, height: box.height, bottom: "auto" } : null),
            }}
            className={cn(
              "glass-3 z-50 flex flex-col overflow-hidden overscroll-contain outline-none [--chat-own-fill:var(--sheen-accent-fill)]",
              strategy === "fixed" ? "fixed" : "absolute",
              sheet
                ? cn(
                    "inset-x-0 bottom-0 rounded-none border-0",
                    // Fixed: the whole screen (above the keyboard via visualViewport). Absolute: the whole box it lives in.
                    strategy === "fixed"
                      ? "h-dvh max-h-dvh pt-[env(safe-area-inset-top)] pb-[env(safe-area-inset-bottom)]"
                      : "top-0",
                  )
                : cn(
                    "bottom-[calc(max(1.25rem,env(safe-area-inset-bottom))+4.5rem)] h-[min(40rem,calc(100dvh-7.5rem))] w-[min(24rem,calc(100vw-2.5rem))] rounded-sheen-xl",
                    corner,
                    strategy === "absolute" && "h-[min(40rem,calc(100%-7.5rem))]",
                  ),
            )}
          >
            <div className="relative min-h-0 flex-1 overflow-hidden">
              <AnimatePresence initial={false} mode="popLayout">
                {conversation ? (
                  <motion.div
                    key={`thread-${conversation.id}`}
                    {...slide(1)}
                    className="absolute inset-0 flex flex-col"
                  >
                    {/* Thread header */}
                    <div className="flex shrink-0 items-center gap-2 border-b border-sheen-border px-2 py-2">
                      <Tooltip content={L.backToHome} delay={300}>
                        <button
                          type="button"
                          data-widget-back=""
                          onClick={() => {
                            backTarget.current = conversation.id;
                            setConversation(null);
                          }}
                          aria-label={L.backToHome}
                          className={chatIconButton}
                        >
                          <ChevronLeftIcon className="size-5" />
                        </button>
                      </Tooltip>
                      {agent && <ChatAvatar people={[agent]} size="md" presence={agent.presence} />}
                      <div className="flex min-w-0 flex-1 flex-col">
                        <p id={titleId} className="truncate text-sm leading-5 font-semibold">
                          {agent?.name ?? L.widgetTitle}
                        </p>
                        <p id={subtitleId} className="truncate text-xs leading-4 text-sheen-fg-muted">
                          {(conversation.typingIds ?? []).some((t) => t !== currentUserId) ? (
                            <span className="font-medium text-sheen-accent">{L.typing([], false)}</span>
                          ) : (
                            L.widgetSubtitle
                          )}
                        </p>
                      </div>
                      <Tooltip content={L.minimize} delay={300}>
                        <button
                          type="button"
                          onClick={() => setOpen(false)}
                          aria-label={L.minimize}
                          className={chatIconButton}
                        >
                          <ChevronDownIcon className="size-5" />
                        </button>
                      </Tooltip>
                    </div>
                    <ChatThread
                      conversation={conversation}
                      messages={messages[conversation.id] ?? []}
                      participants={participants}
                      currentUserId={currentUserId}
                      showHeader={false}
                      headingLevel={headingLevel}
                      surface="none"
                      density="compact"
                      quickReplies={
                        (messages[conversation.id] ?? []).some((m) => m.senderId === currentUserId)
                          ? undefined
                          : quickReplies
                      }
                      onSend={(draft) => onSend?.(conversation.id, draft)}
                      onReact={onReact ? (m, emoji, add) => onReact(conversation.id, m, emoji, add) : undefined}
                      onRetry={onRetry ? (m) => onRetry(conversation.id, m) : undefined}
                      onRead={() => onRead?.(conversation.id)}
                      composerRef={composerRef}
                      now={now}
                      locale={locale}
                      labels={threadLabels}
                      {...threadProps}
                      className={cn("min-h-0 flex-1", threadProps?.className)}
                    />
                  </motion.div>
                ) : (
                  <motion.div
                    key="home"
                    {...slide(-1)}
                    className="absolute inset-0 flex flex-col overflow-y-auto overscroll-contain [scrollbar-width:thin]"
                  >
                    {/* Hero */}
                    {/* Fades out under the greeting card (a mask on the hero itself, which holds no glass), so no hard edge shows through. */}
                    <div className="sheen-fill relative shrink-0 overflow-hidden px-5 pt-4 pb-14 text-sheen-accent-fg [background-image:var(--sheen-accent-fill)] [mask-image:linear-gradient(to_bottom,var(--sheen-ink-0)_calc(100%-3.5rem),transparent)]">
                      <span
                        aria-hidden
                        className="pointer-events-none absolute -end-10 -top-16 size-48 rounded-full bg-sheen-accent-fg/12 blur-2xl"
                      />
                      <span
                        aria-hidden
                        className="pointer-events-none absolute -bottom-20 -start-8 size-40 rounded-full bg-(--sheen-teal-400)/35 blur-2xl"
                      />
                      <div className="relative flex items-center justify-between gap-3">
                        <span className="flex -space-x-2.5">
                          {headerPeople.map((p) => (
                            <ChatAvatar
                              key={p.id}
                              people={[p]}
                              size="md"
                              className="rounded-full ring-2 ring-sheen-accent-fg/70"
                            />
                          ))}
                        </span>
                        {minimize}
                      </div>
                      <p className="relative mt-5 text-2xl leading-tight font-semibold tracking-tight">{L.greeting}</p>
                      <p id={titleId} className="relative mt-1 text-sm font-medium text-sheen-accent-fg">
                        {L.widgetTitle}
                      </p>
                      <p
                        id={subtitleId}
                        className="relative mt-0.5 flex items-center gap-1.5 text-xs text-sheen-accent-fg"
                      >
                        <span
                          aria-hidden
                          className="size-2 rounded-full bg-(--sheen-green-400) ring-2 ring-sheen-accent-fg/30 forced-colors:bg-[CanvasText]"
                        />
                        {L.widgetSubtitle}
                      </p>
                    </div>

                    <div className="relative -mt-9 flex flex-col gap-3 px-3 pb-4">
                      {/* The one card that blurs (it sits over the hero); the rest sit on the panel's own glass. */}
                      <div className="glass-2 flex flex-col gap-3 rounded-sheen-lg p-4">
                        <p className="text-sm text-sheen-fg-muted">{L.greetingDescription}</p>
                        {homeContent}
                        <Button
                          data-widget-start=""
                          onClick={startNew}
                          disabled={!onNewConversation}
                          trailing={<SendIcon className="size-4" />}
                          fullWidth
                          className="any-pointer-coarse:h-11"
                        >
                          {L.sendUsMessage}
                        </Button>
                      </div>

                      {recent.length > 0 && (
                        <section aria-labelledby={`${id}-recent`} className={cn(homeCard, "py-2")}>
                          <SectionHeading
                            id={`${id}-recent`}
                            className="px-4 pt-1 pb-1.5 text-xs font-semibold text-sheen-fg-muted"
                          >
                            {L.recentConversations}
                          </SectionHeading>
                          <ul className="flex flex-col">
                            {recent.map((c) => {
                              const last = c.lastMessage;
                              const sender = last ? people.get(last.senderId) : undefined;
                              const date = toDate(last?.createdAt ?? c.updatedAt);
                              const time = date ? formatListTime(date, now, locale, L.justNow) : null;
                              const unread = c.unreadCount ?? 0;
                              const name = conversationTitle(c, people, currentUserId);
                              return (
                                <li key={c.id}>
                                  <button
                                    type="button"
                                    data-widget-conversation={c.id}
                                    onClick={() => setConversation(c.id)}
                                    className={cn(
                                      "group/recent flex w-full cursor-pointer items-center gap-3 px-4 py-2.5 text-start",
                                      "transition-[background-color] duration-(--sheen-duration-fast) hover:bg-sheen-hover",
                                      "focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sheen-focus",
                                    )}
                                  >
                                    <ChatAvatar
                                      people={sender && sender.id !== currentUserId ? [sender] : team.slice(0, 1)}
                                      size="md"
                                    />
                                    <span className="flex min-w-0 flex-1 flex-col">
                                      <span className="flex items-center gap-2">
                                        <span
                                          className={cn(
                                            "min-w-0 flex-1 truncate text-sm",
                                            unread ? "font-semibold" : "font-medium",
                                          )}
                                        >
                                          {name}
                                        </span>
                                        {time && (
                                          <span className="shrink-0 text-xs text-sheen-fg-muted">
                                            <span aria-hidden>{time.short}</span>
                                            <span className="sr-only">, {time.long}</span>
                                          </span>
                                        )}
                                      </span>
                                      <span className="flex items-center gap-2">
                                        <span className="min-w-0 flex-1 truncate text-xs text-sheen-fg-muted">
                                          {last
                                            ? `${last.senderId === currentUserId ? `${L.youPrefix} ` : ""}${messageSummary(last, L, last.senderId === currentUserId)}`
                                            : ""}
                                        </span>
                                        <UnreadBadge count={unread} label={L.unreadCount(unread)} />
                                      </span>
                                    </span>
                                    <ChevronRightIcon className="size-4 shrink-0 text-sheen-fg-muted transition-[translate] duration-(--sheen-duration-fast) motion-ok:group-hover/recent:translate-x-0.5 rtl:motion-ok:group-hover/recent:-translate-x-0.5" />
                                  </button>
                                </li>
                              );
                            })}
                          </ul>
                        </section>
                      )}

                      {helpLinks && helpLinks.length > 0 && (
                        <nav aria-labelledby={`${id}-help`} className={cn(homeCard, "py-2")}>
                          <SectionHeading
                            id={`${id}-help`}
                            className="px-4 pt-1 pb-1.5 text-xs font-semibold text-sheen-fg-muted"
                          >
                            {L.helpHeading}
                          </SectionHeading>
                          <ul className="flex flex-col">
                            {helpLinks.map((link) => (
                              <li key={link.href}>
                                <a
                                  href={link.href}
                                  target={link.newTab ? "_blank" : undefined}
                                  rel={link.newTab ? "noopener noreferrer" : undefined}
                                  className={cn(
                                    "group/help flex min-h-11 items-center gap-3 px-4 py-2 text-start",
                                    "transition-[background-color] duration-(--sheen-duration-fast) hover:bg-sheen-hover",
                                    "focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sheen-focus",
                                  )}
                                >
                                  <span className="flex min-w-0 flex-1 flex-col">
                                    <span className="truncate text-sm font-medium">{link.label}</span>
                                    {link.description && (
                                      <span className="truncate text-xs text-sheen-fg-muted">{link.description}</span>
                                    )}
                                  </span>
                                  <ChevronRightIcon className="size-4 shrink-0 text-sheen-fg-muted transition-[translate] duration-(--sheen-duration-fast) motion-ok:group-hover/help:translate-x-0.5 rtl:motion-ok:group-hover/help:-translate-x-0.5" />
                                </a>
                              </li>
                            ))}
                          </ul>
                        </nav>
                      )}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Launcher */}
      <div
        className={cn(
          strategy === "fixed" ? "fixed" : "absolute",
          "bottom-[max(1.25rem,env(safe-area-inset-bottom))] z-50",
          corner,
          open && sheet && "hidden",
          className,
        )}
      >
        <button
          ref={launcherRef}
          type="button"
          onClick={() => setOpen(!open)}
          aria-label={open ? L.closeChat : badge > 0 ? `${L.openChat}, ${L.widgetUnread(badge)}` : L.openChat}
          aria-expanded={open}
          aria-controls={open ? panelId : undefined}
          aria-haspopup="dialog"
          className={cn(
            "sheen-fill group/launcher relative flex size-14 cursor-pointer items-center justify-center rounded-full text-sheen-accent-fg [background-image:var(--sheen-accent-fill)]",
            "shadow-(--sheen-accent-fill-shadow)",
            "transition-[scale,filter] duration-(--sheen-duration-snappy) ease-sheen-snappy hover:brightness-110 motion-ok:hover:scale-105 motion-ok:active:scale-95",
            "focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-sheen-focus",
          )}
        >
          {/*
            A gentle pulse until the first open: two rings (under 5s, so it never needs a pause
            button), again whenever the unread count goes up. Gone with reduced motion.
          */}
          {!opened && (
            <span
              key={badge}
              aria-hidden
              className="pointer-events-none absolute inset-0 rounded-full bg-sheen-accent opacity-0 motion-ok:animate-[sheen-chat-attention_var(--sheen-duration-loop-slow)_var(--sheen-ease-out)_2] forced-colors:hidden"
            />
          )}
          <AnimatePresence initial={false} mode="popLayout">
            <motion.span
              key={open ? "close" : "chat"}
              className="relative flex"
              initial={reduced ? { opacity: 0 } : { opacity: 0, rotate: open ? -90 : 90, scale: 0.5 }}
              animate={{ opacity: 1, rotate: 0, scale: 1 }}
              exit={
                reduced
                  ? { opacity: 0, transition: exitTransition }
                  : { opacity: 0, rotate: open ? 90 : -90, scale: 0.5, transition: exitTransition }
              }
              transition={reduced ? { duration: duration.fast } : spring.bouncy}
            >
              {open ? <ChevronDownIcon className="size-7" /> : <ChatFilledIcon className="size-7" />}
            </motion.span>
          </AnimatePresence>
          {!open && badge > 0 && (
            <UnreadBadge
              count={badge}
              overflow={L.unreadOverflow}
              label={L.widgetUnread(badge)}
              className={cn(
                "absolute -end-0.5 -top-0.5 bg-(--sheen-danger-solid) [background-image:var(--sheen-danger-fill)] shadow-none ring-2 ring-(--sheen-surface-solid)",
                "motion-ok:animate-[sheen-chat-pop_var(--sheen-duration-snappy)_var(--sheen-ease-snappy)]",
                chatAppearReduced,
              )}
            />
          )}
        </button>
      </div>
    </>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useImperativeHandle,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ChangeEvent,
  type DragEvent,
  type KeyboardEvent,
  type Ref,
  type SyntheticEvent,
} from "react";
import { AnimatePresence, motion } from "motion/react";

import { cn } from "../lib/cn";
import { useControllable } from "../hooks/use-controllable";
import { isImeComposing } from "../lib/ime";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { duration, spring } from "../motion/tokens";
import { exitTransition } from "../motion/presets";
import { Button } from "../button/button";
import { Popover, PopoverContent, PopoverTrigger } from "../popover/popover";
import { Tooltip } from "../tooltip/tooltip";
import { chatIconButton, chatNoBlur } from "./chat-parts";
import { EmojiPicker } from "./emoji-picker";
import { formatFileSize } from "./format";
import { chatUid, useAnnouncer, useCoarsePointer } from "./hooks";
import { useLatest } from "../hooks/use-latest";
import { resolveChatLabels, type ChatLabels } from "./labels";
import { QuoteBlock } from "./message-parts";
import type { ChatDraft, ChatDraftAttachment, ChatReplyRef } from "./types";
import { FileIcon, PaperclipIcon, PencilIcon, ReplyIcon, SendIcon, SmileIcon, XIcon } from "./icons";

/** A message being edited in the composer: its `id` and the text to start from. */
export type ChatComposerEditing = { id: string; text: string };

/** Imperative handle: focus the field, insert text at the caret. */
export type ChatComposerHandle = {
  /** Move focus into the text field. */
  focus: () => void;
  /** Insert `text` at the caret (or replace the selection). */
  insert: (text: string) => void;
  /** The underlying `<textarea>` (null before mount). */
  textarea: HTMLTextAreaElement | null;
};

/** Props of {@link ChatComposer}. Only `onSend` is required. */
export type ChatComposerProps = {
  /** Called with the text, picked files and the quoted message. Hand-over: image preview URLs now belong to you (revoke them when the message goes). */
  onSend: (draft: ChatDraft) => void;
  /** The draft text (controlled). Keep a draft per conversation by storing it per id. */
  value?: string;
  /**
   * The draft text on mount (uncontrolled).
   * @default ""
   */
  defaultValue?: string;
  /** Called with the text as it changes. */
  onValueChange?: (text: string) => void;
  /** The message being replied to: shows a bar above the field with a cancel button. */
  replyTo?: ChatReplyRef | null;
  /** Called when the reply bar's cancel button is pressed. */
  onCancelReply?: () => void;
  /** Edit mode: the field holds this message's text; Enter saves, Escape cancels. */
  editing?: ChatComposerEditing | null;
  /** Called with the message id and new text when an edit is saved. */
  onSaveEdit?: (id: string, text: string) => void;
  /** Called when an edit is cancelled. */
  onCancelEdit?: () => void;
  /** ↑ in an empty field: start editing your last message. */
  onEditLast?: () => void;
  /** true while the person types, false after 4s of quiet, on send and on blur. */
  onTyping?: (typing: boolean) => void;
  /** Name of a sender, for the reply bar. */
  nameOf?: (participantId: string) => string;
  /** The conversation's name, for the placeholder ("Message Riya"). */
  title?: string;
  /** Sets the placeholder text. Default: "Message {title}". */
  placeholder?: string;
  /**
   * Show the attach button and accept pasted or dropped files.
   * @default true
   */
  allowAttachments?: boolean;
  /** File types the picker offers (input accept). */
  accept?: string;
  /**
   * Maximum number of files a person can attach to one message.
   * @default 10
   */
  maxAttachments?: number;
  /** Text tapped to send at once (support chats): shown as chips above the field. */
  quickReplies?: string[];
  /**
   * Tallest the field grows before it scrolls, in lines.
   * @default 6
   */
  maxRows?: number;
  /**
   * Disable the field and every button.
   * @default false
   */
  disabled?: boolean;
  /**
   * Focus the field on mount.
   * @default false
   */
  autoFocus?: boolean;
  /**
   * Sets the row density: "compact" uses tighter padding (the chat widget).
   * @default "comfortable"
   */
  density?: "comfortable" | "compact";
  /** Ref to the imperative handle ({@link ChatComposerHandle}). */
  ref?: Ref<ChatComposerHandle>;
  /** BCP 47 locale for file sizes. Default: the browser's. */
  locale?: string;
  /** Any UI string (i18n); see {@link ChatLabels}. */
  labels?: Partial<ChatLabels>;
  /** Adds extra classes to the composer. */
  className?: string;
};

const TYPING_IDLE = 4000;

/**
 * The message field: grows with its text, emoji picker, attachments with thumbnails, reply and
 * edit bars, and a send button. Enter sends, Shift + Enter adds a line (touch keyboards: the
 * Return key adds a line, the button sends). Input methods that compose text (Japanese, Chinese,
 * Korean) are left alone until the word is committed. ↑ in an empty field edits your last message.
 * Text is 16px on touch screens, so iOS doesn't zoom the page when the field is focused.
 *
 * Props: see {@link ChatComposerProps} (`onSend` required; `value` / `defaultValue` /
 * `onValueChange`, `replyTo`, `editing`, `onTyping`, `quickReplies`, `allowAttachments` true,
 * `accept`, `maxAttachments` 10, `maxRows` 6, `disabled`, `autoFocus`, `density`, `ref`, `labels`).
 *
 * Keyboard: Enter sends (on touch keyboards Return adds a line and the button sends), Shift+Enter adds a line, Up in an empty field edits your last message, Escape cancels a reply or an edit. Attach, emoji and send are buttons in the tab order; pasting or dropping files attaches them.
 * Accessibility: The field is a labelled textarea with a hint (how to send, how many files are allowed); attaching, removing, replying and errors are announced politely; buttons have names and 44px hit areas on touch; text is 16px on touch screens so iOS does not zoom. Input methods that compose text are left alone until the word is committed.
 * Glass: One glass field; the emoji popover is the shared glass popover. Reply and attachment bars reuse the look without extra blur.
 * Motion: Bars and chips slide in and out with the SheenUI spring; reduced motion removes the movement.
 *
 * @example
 * ```tsx
 * import { ChatComposer } from "@sheenui/theme";
 *
 * export const Reply = () => (
 *   <ChatComposer title="Riya" onSend={(draft) => console.log(draft.text, draft.attachments.length)} quickReplies={["Thanks!", "On it"]} />
 * );
 * ```
 *
 * @see /chat/thread
 */
export function ChatComposer({
  onSend,
  value,
  defaultValue = "",
  onValueChange,
  replyTo,
  onCancelReply,
  editing,
  onSaveEdit,
  onCancelEdit,
  onEditLast,
  onTyping,
  nameOf,
  title,
  placeholder,
  allowAttachments = true,
  accept,
  maxAttachments = 10,
  quickReplies,
  maxRows = 6,
  disabled = false,
  autoFocus = false,
  density = "comfortable",
  ref,
  locale,
  labels: labelsProp,
  className,
}: ChatComposerProps) {
  const L = useMemo(() => resolveChatLabels(labelsProp), [labelsProp]);
  const reduced = useSheenReducedMotion();
  const coarse = useCoarsePointer();
  const fieldId = useId();
  const hintId = useId();
  const [announce, announcer] = useAnnouncer();

  const [draft, setDraft] = useControllable(value, defaultValue, onValueChange);

  // Edit mode has its own text, so the unsent draft comes back after editing.
  const [editText, setEditText] = useState(editing?.text ?? "");
  const editingId = editing?.id ?? null;
  // Only when a different message is opened for editing (adjusted in the same render, before it paints).
  const [seenEditingId, setSeenEditingId] = useState(editingId);
  if (seenEditingId !== editingId) {
    setSeenEditingId(editingId);
    if (editing) setEditText(editing.text);
  }
  const text = editing ? editText : draft;
  const setText = editing ? setEditText : setDraft;

  const [files, setFiles] = useState<ChatDraftAttachment[]>([]);
  const filesRef = useLatest(files);
  const [dragging, setDragging] = useState(false);
  const [emojiOpen, setEmojiOpen] = useState(false);
  const fieldRef = useRef<HTMLTextAreaElement>(null);
  // Emoji picker focus return: after inserting an emoji, back to the field (keep typing); on a plain dismiss, back to the button that opened it.
  const emojiTrigger = useRef<HTMLButtonElement>(null);
  const emojiPicked = useRef(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const selection = useRef<{ start: number; end: number } | null>(null);

  /* Revoke previews of files never sent. */
  useEffect(
    () => () => {
      for (const f of filesRef.current) if (f.previewUrl) URL.revokeObjectURL(f.previewUrl);
    },
    [filesRef],
  );

  /* ----- Auto-grow ----- */
  const resize = useCallback(() => {
    const el = fieldRef.current;
    if (!el) return;
    const style = getComputedStyle(el);
    const line = parseFloat(style.lineHeight) || 24;
    const padding = parseFloat(style.paddingTop) + parseFloat(style.paddingBottom);
    const max = line * maxRows + padding;
    el.style.height = "auto";
    const full = el.scrollHeight;
    el.style.height = `${Math.min(full, max)}px`;
    el.style.overflowY = full > max + 1 ? "auto" : "hidden";
  }, [maxRows]);

  useLayoutEffect(() => {
    resize();
  }, [text, resize]);

  useEffect(() => {
    const el = fieldRef.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    let width = el.offsetWidth;
    const observer = new ResizeObserver(() => {
      if (el.offsetWidth === width) return;
      width = el.offsetWidth;
      resize();
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [resize]);

  useEffect(() => {
    if (autoFocus) fieldRef.current?.focus({ preventScroll: true });
  }, [autoFocus]);

  // Opening a reply or an edit puts the caret in the field (at the end).
  const replyKey = replyTo?.id ?? null;
  useEffect(() => {
    if (!replyKey && !editingId) return;
    const el = fieldRef.current;
    if (!el) return;
    el.focus({ preventScroll: true });
    const end = el.value.length;
    el.setSelectionRange(end, end);
  }, [replyKey, editingId]);

  /* ----- Typing signal ----- */
  const typing = useRef(false);
  const typingTimer = useRef<number | undefined>(undefined);
  const onTypingRef = useLatest(onTyping);
  const stopTyping = useCallback(() => {
    window.clearTimeout(typingTimer.current);
    if (typing.current) {
      typing.current = false;
      onTypingRef.current?.(false);
    }
  }, [onTypingRef]);
  const noteTyping = () => {
    if (!onTypingRef.current || editing) return;
    if (!typing.current) {
      typing.current = true;
      onTypingRef.current(true);
    }
    window.clearTimeout(typingTimer.current);
    typingTimer.current = window.setTimeout(stopTyping, TYPING_IDLE);
  };
  useEffect(() => () => stopTyping(), [stopTyping]);

  /* ----- Imperative handle ----- */
  const insert = useCallback(
    (snippet: string) => {
      const el = fieldRef.current;
      const current = el?.value ?? text;
      const sel = selection.current ?? { start: current.length, end: current.length };
      const next = current.slice(0, sel.start) + snippet + current.slice(sel.end);
      const caret = sel.start + snippet.length;
      selection.current = { start: caret, end: caret };
      setText(next);
      requestAnimationFrame(() => {
        if (!el) return;
        el.setSelectionRange(caret, caret);
      });
    },
    [text, setText],
  );
  useImperativeHandle(
    ref,
    () => ({ focus: () => fieldRef.current?.focus({ preventScroll: true }), insert, textarea: fieldRef.current }),
    [insert],
  );

  /* ----- Files ----- */
  function addFiles(list: FileList | File[]) {
    const picked = Array.from(list);
    if (picked.length === 0) return;
    const room = Math.max(0, maxAttachments - files.length);
    const taken = picked.slice(0, room).map<ChatDraftAttachment>((file) => ({
      id: chatUid("file"),
      file,
      name: file.name,
      size: file.size,
      mimeType: file.type,
      previewUrl: file.type.startsWith("image/") ? URL.createObjectURL(file) : undefined,
    }));
    if (taken.length) {
      setFiles((f) => [...f, ...taken]);
      announce(taken.map((t) => t.name).join(", "));
    }
  }

  function removeFile(file: ChatDraftAttachment) {
    setFiles((f) => f.filter((x) => x.id !== file.id));
    if (file.previewUrl) URL.revokeObjectURL(file.previewUrl);
    announce(L.removeAttachment(file.name));
    fieldRef.current?.focus({ preventScroll: true });
  }

  /* ----- Send / save ----- */
  const trimmed = text.trim();
  const canSend =
    !disabled &&
    (editing ? trimmed.length > 0 && trimmed !== editing.text.trim() : trimmed.length > 0 || files.length > 0);

  function submit(event?: SyntheticEvent) {
    event?.preventDefault();
    if (!canSend) return;
    if (editing) {
      onSaveEdit?.(editing.id, trimmed);
      setEditText("");
    } else {
      onSend({ text: trimmed, attachments: files, replyTo: replyTo ?? undefined });
      // The previews now belong to the sent message.
      setFiles([]);
      setDraft("");
      stopTyping();
    }
    selection.current = null;
    fieldRef.current?.focus({ preventScroll: true });
  }

  function onKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (isImeComposing(event.nativeEvent)) return;
    if (event.key === "Escape") {
      if (editing) {
        event.preventDefault();
        event.stopPropagation();
        onCancelEdit?.();
        return;
      }
      if (replyTo) {
        event.preventDefault();
        event.stopPropagation();
        onCancelReply?.();
        return;
      }
      return;
    }
    if (
      event.key === "ArrowUp" &&
      !editing &&
      text === "" &&
      files.length === 0 &&
      onEditLast &&
      !event.shiftKey &&
      !event.altKey &&
      !event.metaKey &&
      !event.ctrlKey
    ) {
      event.preventDefault();
      onEditLast();
      return;
    }
    if (event.key !== "Enter" || event.shiftKey || event.altKey) return;
    // Touch keyboards: Return adds a line (Cmd/Ctrl + Enter still sends).
    if (coarse && !event.metaKey && !event.ctrlKey) return;
    event.preventDefault();
    submit();
  }

  const hasFiles = (event: DragEvent) =>
    allowAttachments && !editing && Array.from(event.dataTransfer.types).includes("Files");
  const compact = density === "compact";
  const replyName = replyTo ? (nameOf?.(replyTo.senderId) ?? "") : "";
  const banner = editing ? "edit" : replyTo ? "reply" : null;

  const rise = {
    initial: reduced ? { opacity: 0 } : { opacity: 0, y: 8 },
    animate: { opacity: 1, y: 0 },
    exit: reduced ? { opacity: 0, transition: exitTransition } : { opacity: 0, y: 4, transition: exitTransition },
    transition: reduced ? { duration: duration.fast } : spring.snappy,
  };

  return (
    <form
      onSubmit={submit}
      data-slot="chat-composer"
      className={cn(
        "flex w-full min-w-0 flex-col gap-2",
        compact ? "px-2.5 pt-1.5 pb-2.5" : "px-3 pt-2 pb-3 @lg:px-4",
        className,
      )}
    >
      {quickReplies && quickReplies.length > 0 && !editing && (
        // Touch: py-1 leaves room for the chips' 44px hit area (the scroller clips anything outside its padding).
        <ul
          aria-label={L.quickReplies}
          className="-mx-1 flex gap-1.5 overflow-x-auto overscroll-x-contain px-1 py-0.5 [scrollbar-width:none] *:shrink-0 any-pointer-coarse:py-1"
        >
          {quickReplies.map((reply) => (
            <li key={reply}>
              <button
                type="button"
                disabled={disabled}
                onClick={() => {
                  onSend({ text: reply, attachments: [] });
                  fieldRef.current?.focus({ preventScroll: true });
                }}
                className={cn(
                  // The glass look without a blur of its own (it sits on the chat's glass already).
                  "glass-1 [-webkit-backdrop-filter:none] [backdrop-filter:none] relative inline-flex h-8 cursor-pointer items-center rounded-full border-sheen-accent-border px-3 text-xs font-medium text-sheen-accent",
                  "transition-[background-color,scale] duration-(--sheen-duration-fast) ease-sheen-out hover:bg-sheen-accent-soft motion-ok:active:scale-95",
                  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
                  // Touch: a 44px-tall hit area (insets are % of the chip's own box, so the border doesn't eat into it).
                  "any-pointer-coarse:h-9 any-pointer-coarse:after:absolute any-pointer-coarse:after:inset-x-0 any-pointer-coarse:after:inset-y-[min(0px,calc((100%-2.75rem)/2))]",
                )}
              >
                {reply}
              </button>
            </li>
          ))}
        </ul>
      )}

      <div
        // Drag and drop is a pointer shortcut; the attach button is the keyboard route.
        role="presentation"
        className="relative flex min-w-0 flex-col"
        onDragEnter={(e) => hasFiles(e) && setDragging(true)}
        onDragOver={(e) => {
          if (!hasFiles(e)) return;
          e.preventDefault();
          e.dataTransfer.dropEffect = "copy";
        }}
        onDragLeave={(e) => {
          if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setDragging(false);
        }}
        onDrop={(e) => {
          if (!hasFiles(e)) return;
          e.preventDefault();
          setDragging(false);
          addFiles(e.dataTransfer.files);
        }}
      >
        {/* Reply / edit bar */}
        <AnimatePresence initial={false}>
          {banner && (
            <motion.div key={banner} {...rise} className="mb-1.5 flex min-w-0 items-center gap-2 ps-1">
              <span aria-hidden className="flex size-8 shrink-0 items-center justify-center text-sheen-accent">
                {banner === "edit" ? <PencilIcon className="size-4" /> : <ReplyIcon className="size-4" />}
              </span>
              <QuoteBlock
                variant="composer"
                senderName={banner === "edit" ? L.editingMessage : L.replyingTo(replyName)}
                text={
                  banner === "edit"
                    ? (editing?.text ?? "")
                    : (replyTo?.text ?? (replyTo?.attachmentKind ? L.attachmentSummary(replyTo.attachmentKind, 1) : ""))
                }
                className="flex-1"
              />
              <Tooltip content={banner === "edit" ? `${L.cancelEdit} (Esc)` : L.cancelReply} delay={300}>
                <button
                  type="button"
                  aria-label={banner === "edit" ? L.cancelEdit : L.cancelReply}
                  onClick={() => {
                    if (banner === "edit") onCancelEdit?.();
                    else onCancelReply?.();
                    fieldRef.current?.focus({ preventScroll: true });
                  }}
                  className={chatIconButton}
                >
                  <XIcon />
                </button>
              </Tooltip>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Picked files */}
        {files.length > 0 && !editing && (
          <ul
            aria-label={L.attachments}
            className="mb-1.5 flex gap-2 overflow-x-auto overscroll-x-contain px-1 pt-1.5 pb-1 [scrollbar-width:thin] *:shrink-0"
          >
            <AnimatePresence initial={false}>
              {files.map((f) => (
                <motion.li
                  key={f.id}
                  layout={reduced ? false : "position"}
                  initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.8 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={
                    reduced
                      ? { opacity: 0, transition: exitTransition }
                      : { opacity: 0, scale: 0.85, transition: exitTransition }
                  }
                  transition={reduced ? { duration: duration.fast } : spring.snappy}
                  className="relative"
                >
                  {f.previewUrl ? (
                    <img
                      src={f.previewUrl}
                      alt={f.name}
                      width={64}
                      height={64}
                      className="size-16 rounded-sheen-md border border-sheen-border object-cover"
                    />
                  ) : (
                    <span className="flex h-16 w-44 items-center gap-2 rounded-sheen-md border border-sheen-border bg-sheen-hover px-2.5">
                      <FileIcon className="size-5 shrink-0 text-sheen-accent" />
                      <span className="flex min-w-0 flex-col">
                        <span className="truncate text-xs font-medium">{f.name}</span>
                        <span className="text-2xs text-sheen-fg-muted">{formatFileSize(f.size, locale)}</span>
                      </span>
                    </span>
                  )}
                  <button
                    type="button"
                    onClick={() => removeFile(f)}
                    aria-label={L.removeAttachment(f.name)}
                    className={cn(
                      "absolute -end-1.5 -top-1.5 flex size-6 cursor-pointer items-center justify-center rounded-full bg-sheen-fg text-sheen-bg shadow-md",
                      "hover:scale-110 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
                      "forced-colors:border forced-colors:border-[ButtonText]",
                      "any-pointer-coarse:after:absolute any-pointer-coarse:after:size-11",
                    )}
                  >
                    <XIcon className="size-3" />
                  </button>
                </motion.li>
              ))}
            </AnimatePresence>
          </ul>
        )}

        <div className="flex min-w-0 items-end gap-2">
          <div
            // A click on the padding around the field focuses it (a pointer convenience; the field is the real control).
            role="presentation"
            onMouseDown={(e) => {
              if (e.target === e.currentTarget) {
                e.preventDefault();
                fieldRef.current?.focus();
              }
            }}
            className={cn(
              "glass-2 flex min-w-0 flex-1 items-end gap-0.5 rounded-[1.375rem] border-sheen-control-border/60 p-1",
              // On the chat's glass already: the glass look without a second blur.
              chatNoBlur,
              "transition-[box-shadow,border-color] duration-(--sheen-duration-fast) ease-sheen-out",
              "focus-within:border-sheen-accent-border focus-within:shadow-[0_0_0_4px_var(--sheen-ring)]",
              "has-[textarea:focus-visible]:outline-2 has-[textarea:focus-visible]:outline-offset-2 has-[textarea:focus-visible]:outline-sheen-focus",
              disabled && "opacity-55",
            )}
          >
            <Popover
              open={emojiOpen}
              onOpenChange={(next) => {
                if (next) emojiPicked.current = false;
                setEmojiOpen(next);
              }}
            >
              <Tooltip content={L.emoji} delay={300}>
                <PopoverTrigger
                  ref={emojiTrigger}
                  disabled={disabled}
                  aria-label={L.emoji}
                  className={cn(chatIconButton, "data-popup-open:bg-sheen-hover data-popup-open:text-sheen-accent")}
                >
                  <SmileIcon />
                </PopoverTrigger>
              </Tooltip>
              <PopoverContent
                side="top"
                align="start"
                sideOffset={12}
                className="w-auto p-3"
                aria-label={L.emoji}
                finalFocus={() => (emojiPicked.current ? fieldRef.current : emojiTrigger.current) ?? true}
              >
                <EmojiPicker
                  autoFocusSearch={!coarse}
                  labels={labelsProp}
                  onSelect={(emoji) => {
                    emojiPicked.current = true;
                    insert(emoji);
                    noteTyping();
                  }}
                />
              </PopoverContent>
            </Popover>

            <label htmlFor={fieldId} className="sr-only">
              {editing ? L.editingMessage : L.message}
            </label>
            <textarea
              ref={fieldRef}
              id={fieldId}
              rows={1}
              value={text}
              disabled={disabled}
              onChange={(e: ChangeEvent<HTMLTextAreaElement>) => {
                setText(e.target.value);
                selection.current = { start: e.target.selectionStart, end: e.target.selectionEnd };
                if (e.target.value) noteTyping();
                else stopTyping();
              }}
              onSelect={(e) => {
                const el = e.currentTarget;
                selection.current = { start: el.selectionStart, end: el.selectionEnd };
              }}
              onBlur={() => stopTyping()}
              onKeyDown={onKeyDown}
              onPaste={(e) => {
                if (!allowAttachments || editing || e.clipboardData.files.length === 0) return;
                if (e.clipboardData.getData("text/plain").trim()) return;
                e.preventDefault();
                addFiles(e.clipboardData.files);
              }}
              placeholder={placeholder ?? L.placeholder(title)}
              aria-describedby={hintId}
              enterKeyHint={coarse ? "enter" : "send"}
              autoComplete="off"
              dir="auto"
              spellCheck
              className={cn(
                "block min-h-9 w-full min-w-0 flex-1 resize-none bg-transparent px-1.5 py-1.5 text-[0.9375rem] leading-6 text-sheen-fg outline-none placeholder:truncate placeholder:text-sheen-fg-subtle",
                "[scrollbar-width:thin] any-pointer-coarse:py-2.5 any-pointer-coarse:text-base",
                "disabled:cursor-not-allowed forced-colors:focus-visible:outline-none!",
              )}
            />

            {allowAttachments && !editing && (
              <>
                <input
                  ref={fileRef}
                  type="file"
                  multiple
                  accept={accept}
                  tabIndex={-1}
                  aria-hidden
                  className="sr-only"
                  onChange={(e) => {
                    if (e.target.files) addFiles(e.target.files);
                    e.target.value = "";
                  }}
                />
                <Tooltip content={L.attach} delay={300}>
                  <button
                    type="button"
                    aria-label={L.attach}
                    disabled={disabled || files.length >= maxAttachments}
                    onClick={() => fileRef.current?.click()}
                    className={chatIconButton}
                  >
                    <PaperclipIcon />
                  </button>
                </Tooltip>
              </>
            )}
          </div>

          <Button
            type="submit"
            variant="primary"
            size="icon"
            aria-label={editing ? L.saveEdit : L.send}
            disabled={!canSend}
            className={cn("size-11 shrink-0 rounded-full [&_svg]:size-[1.125rem]", compact && "size-10")}
          >
            <AnimatePresence initial={false} mode="popLayout">
              <motion.span
                key={editing ? "save" : "send"}
                className="flex"
                initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.4, rotate: -30 }}
                animate={{ opacity: 1, scale: 1, rotate: 0 }}
                exit={
                  reduced
                    ? { opacity: 0, transition: exitTransition }
                    : { opacity: 0, scale: 0.4, transition: exitTransition }
                }
                transition={reduced ? { duration: duration.fast } : spring.bouncy}
              >
                {editing ? <CheckSaveIcon /> : <SendIcon />}
              </motion.span>
            </AnimatePresence>
          </Button>
        </div>

        {dragging && (
          <div
            aria-hidden
            className="pointer-events-none absolute inset-0 flex items-center justify-center gap-2 rounded-[1.375rem] border-2 border-dashed border-sheen-accent bg-sheen-accent-soft text-sm font-medium text-sheen-accent"
          >
            <PaperclipIcon className="size-4" />
            {L.attach}
          </div>
        )}
      </div>

      <p id={hintId} hidden>
        {editing ? L.editHint : coarse ? L.keyHintTouch : L.keyHint}
      </p>
      {announcer}
    </form>
  );
}

function CheckSaveIcon() {
  return (
    <svg
      aria-hidden
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2.4"
      strokeLinecap="round"
      strokeLinejoin="round"
      className="size-4"
    >
      <path d="M4.5 12.5l4.5 4.5L19.5 6.5" />
    </svg>
  );
}

"use client";

import {
  useCallback,
  useDeferredValue,
  useEffect,
  useEffectEvent,
  useId,
  useImperativeHandle,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
} from "react";

import { cn } from "../lib/cn";
import { HEADING_TAGS, headingBelow } from "../lib/heading";
import { useControllable } from "../hooks/use-controllable";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { ContextMenu, ContextMenuContent, ContextMenuTrigger } from "../context-menu/context-menu";
import { EmptyState } from "../empty-state/empty-state";
import { Input } from "../input/input";
import { Menu, MenuContent, MenuItem, MenuSeparator, createMenuHandle } from "../menu/menu";
import { SegmentedControl } from "../segmented/segmented";
import { Skeleton, SkeletonGroup } from "../skeleton/skeleton";
import { ChatKeyframes, chatNoBlur } from "./chat-parts";
import { conversationTitle, toParticipantMap } from "./format";
import { useAnnouncer, useCoarsePointer, useLongPressMenuGuard, useNow } from "./hooks";
import { useLatest } from "../hooks/use-latest";
import { resolveChatLabels } from "./labels";
import type { ChatConversation, ChatConversationAction, ChatListFilter } from "./types";
import {
  ArchiveIcon,
  BellIcon,
  BellOffIcon,
  ChatsIcon,
  MailDotIcon,
  MailOpenIcon,
  PinIcon,
  PinOffIcon,
  SearchIcon,
  UnarchiveIcon,
  UsersIcon,
  XIcon,
} from "./icons";

import {
  type ConversationListProps,
  type Item,
  HEADER_HEIGHT,
  ROW_HEIGHT,
  activity,
  haystack,
  inFilter,
} from "./conversation-list/model";
import { ListWindow, type RowActions, ConversationRow } from "./conversation-list/row";

export { type ConversationListHandle, type ConversationListProps } from "./conversation-list/model";
/**
 * The chat list ("inbox"): search that filters and highlights, All / Unread / Groups / Archived
 * with counts, Pinned and All chats sections, and rows with avatar and presence, name, the
 * last message (or "typing…", or your draft), time, unread count, pinned / muted marks and
 * delivery ticks for your own last message.
 *
 * Accessibility: a single-select listbox. It is one tab stop: ↑ / ↓, Home / End and
 * Page Up / Down move between chats, typing a name jumps to it, Enter or Space opens one
 * (aria-selected marks the open chat), Shift + F10 or the Menu key opens a chat's actions.
 * The ⋯ button (mouse) and swipe actions (touch) are shortcuts to the same menu.
 *
 * Thousands of chats: above `windowThreshold` rows only the rows in view (plus a few) are in the
 * page; each row says its position (aria-posinset / aria-setsize).
 *
 * Props: see {@link ConversationListProps}. Data: `conversations`, `participants`,
 * `currentUserId`, `selectedId`. Events: `onSelect`, `onAction` (pin, mute, archive, mark read),
 * `onFilterChange`, `onQueryChange`. Look: `title`, `headingLevel` 2, `headerActions`,
 * `showSearch` true, `showFilters` true, `swipeActions` true, `emptyAction`, `density`
 * "comfortable", `windowThreshold` 150, `loading`, `labels`, `locale`, `now`, `ref`.
 *
 * Keyboard: One tab stop: Up / Down, Home / End and Page Up / Down move between chats, typing a name jumps to it, Enter or Space opens one, Shift+F10 or the Menu key opens its actions. The search field and filters are ordinary tab stops.
 * Accessibility: A single-select listbox (`aria-selected` marks the open chat); rows read as name, last message, time, unread count and state; each row says its position (aria-posinset / aria-setsize) even when windowed; filter and search results are announced politely. The swipe and "more" buttons are shortcuts to the same menu, so nothing is gesture-only. Presence is written in words.
 * Glass: One glass panel; rows reuse the look without extra blur.
 * Motion: Rows slide in, the swipe follows the finger, and the typing dots wave and pause off screen; reduced motion removes the movement.
 *
 * @example
 * ```tsx
 * import { useState } from "react";
 * import { ConversationList, type ChatConversation } from "@sheenui/theme";
 *
 * const people = [
 *   { id: "me", name: "You" },
 *   { id: "riya", name: "Riya Sharma", presence: "online" as const },
 * ];
 * const chats: ChatConversation[] = [
 *   { id: "c1", participantIds: ["me", "riya"], unreadCount: 2, lastMessage: { id: "m1", senderId: "riya", text: "See you at 6?", createdAt: "2026-11-08T09:00:00Z" } },
 * ];
 *
 * export function Inbox() {
 *   const [selected, setSelected] = useState<string | null>(null);
 *   return <ConversationList conversations={chats} participants={people} currentUserId="me" selectedId={selected} onSelect={(c) => setSelected(c.id)} />;
 * }
 * ```
 *
 * @see /chat/list
 */
export function ConversationList({
  conversations,
  participants,
  currentUserId,
  selectedId = null,
  onSelect,
  onAction,
  filter: filterProp,
  defaultFilter = "all",
  onFilterChange,
  query: queryProp,
  defaultQuery = "",
  onQueryChange,
  loading = false,
  title,
  headingLevel = 2,
  headerActions,
  showSearch = true,
  showFilters = true,
  swipeActions = true,
  emptyAction,
  density = "comfortable",
  windowThreshold = 150,
  ref,
  now: nowProp,
  locale,
  labels: labelsProp,
  className,
}: ConversationListProps) {
  const L = useMemo(() => resolveChatLabels(labelsProp), [labelsProp]);
  const reduced = useSheenReducedMotion();
  const coarse = useCoarsePointer();
  const now = useNow(nowProp);
  const id = useId();
  const headingId = `${id}-heading`;
  const hintId = `${id}-hint`;
  const [announce, announcer] = useAnnouncer();
  const people = useMemo(() => toParticipantMap(participants), [participants]);

  const [filter, setFilter] = useControllable<ChatListFilter>(filterProp, defaultFilter, onFilterChange);
  const [query, setQuery] = useControllable(queryProp, defaultQuery, onQueryChange);
  // Typing stays instant with thousands of chats: the list catches up in a background render.
  const deferredQuery = useDeferredValue(query);
  const q = deferredQuery.trim().toLocaleLowerCase();

  /* ----- Counts, filtering, sections ----- */
  const counts = useMemo(() => {
    const c: Record<ChatListFilter, number> = { all: 0, unread: 0, groups: 0, archived: 0 };
    for (const conv of conversations)
      for (const f of ["all", "unread", "groups", "archived"] as const) if (inFilter(conv, f)) c[f] += 1;
    return c;
  }, [conversations]);

  // Built once per change of the chats, not on every keystroke.
  const haystacks = useMemo(
    () => new Map(conversations.map((c) => [c.id, haystack(c, people, currentUserId)])),
    [conversations, people, currentUserId],
  );

  // Newest first, sorted once per change of the chats (filtering keeps the order).
  const sorted = useMemo(
    () =>
      conversations
        .map((c) => ({ c, t: activity(c) }))
        .sort((a, b) => b.t - a.t)
        .map((x) => x.c),
    [conversations],
  );

  const items = useMemo<Item[]>(() => {
    const visible = sorted.filter((c) => inFilter(c, filter) && (!q || (haystacks.get(c.id) ?? "").includes(q)));
    const pinned = filter === "archived" ? [] : visible.filter((c) => c.pinned);
    const rest = filter === "archived" ? visible : visible.filter((c) => !c.pinned);
    const out: Item[] = [];
    let index = 0;
    if (pinned.length) {
      out.push({ type: "header", key: "h-pinned", label: L.pinnedSection });
      for (const c of pinned) out.push({ type: "row", key: c.id, conversation: c, index: index++ });
    }
    if (rest.length) {
      if (pinned.length)
        out.push({ type: "header", key: "h-all", label: filter === "archived" ? L.filters.archived : L.allSection });
      for (const c of rest) out.push({ type: "row", key: c.id, conversation: c, index: index++ });
    }
    return out;
  }, [sorted, filter, q, haystacks, L]);

  const rows = useMemo(() => items.filter((i): i is Extract<Item, { type: "row" }> => i.type === "row"), [items]);
  const rowCount = rows.length;

  // Announce how many chats match, once typing pauses.
  const firstAnnounce = useRef(true);
  // The count and the wording are read when the timer fires: only a new query or filter announces.
  const speakCount = useEffectEvent(() => announce(L.resultsCount(rowCount)));
  useEffect(() => {
    if (firstAnnounce.current) {
      firstAnnounce.current = false;
      return;
    }
    const timer = window.setTimeout(speakCount, 600);
    return () => window.clearTimeout(timer);
  }, [q, filter]);

  /* ----- Layout (offsets for windowing) ----- */
  const rowHeight = ROW_HEIGHT[density];
  const windowed = rowCount > windowThreshold;
  const offsets = useMemo(() => {
    const out: number[] = [];
    let y = 0;
    for (const item of items) {
      out.push(y);
      y += item.type === "header" ? HEADER_HEIGHT : rowHeight;
    }
    out.push(y);
    return out;
  }, [items, rowHeight]);
  const total = offsets[offsets.length - 1] ?? 0;

  // The scroller is also held in state (a callback ref): the windowed rows are its children, so their
  // effects run before a plain ref is attached on the very first commit; state re-runs them once it is.
  const scrollRef = useRef<HTMLDivElement | null>(null);
  const [scroller, setScroller] = useState<HTMLDivElement | null>(null);
  const attachScroller = useCallback((node: HTMLDivElement | null) => {
    scrollRef.current = node;
    setScroller(node);
  }, []);

  /* ----- Roving focus ----- */
  const [activeIndex, setActiveIndex] = useState(0);
  const selectedIndex = rows.findIndex((r) => r.conversation.id === selectedId);
  const current = Math.min(Math.max(0, activeIndex), Math.max(0, rowCount - 1));
  const tabStop = activeIndex < 0 || activeIndex >= rowCount ? Math.max(0, selectedIndex) : current;
  const tabRow = rows[tabStop];
  // The list's tab stop follows the open chat until the person moves it.
  const followSelection = useRef(true);
  useEffect(() => {
    if (followSelection.current && selectedIndex >= 0) setActiveIndex(selectedIndex);
  }, [selectedIndex]);

  const pendingFocus = useRef<number | null>(null);
  const domIdOf = useCallback((conversationId: string) => `${id}-c-${conversationId}`, [id]);

  const focusRow = useCallback(
    (index: number) => {
      const target = rows[Math.max(0, Math.min(rowCount - 1, index))];
      if (!target) return;
      followSelection.current = false;
      setActiveIndex(target.index);
      const el = scrollRef.current;
      const itemIndex = items.indexOf(target);
      const node = document.getElementById(domIdOf(target.conversation.id));
      if (node) {
        node.focus({ preventScroll: true });
        node.scrollIntoView({ block: "nearest" });
      } else if (el) {
        // Not rendered yet (windowed): scroll it into view, focus after the render.
        const y = offsets[itemIndex] ?? 0;
        if (y < el.scrollTop) el.scrollTop = y - HEADER_HEIGHT;
        else el.scrollTop = y + rowHeight - el.clientHeight;
        pendingFocus.current = target.index;
      }
    },
    [rows, rowCount, items, offsets, rowHeight, domIdOf],
  );

  // A row asked for focus before it was rendered (windowed): focus it once it is in the page.
  const flushPendingFocus = () => {
    if (pendingFocus.current === null) return;
    const target = rows[pendingFocus.current];
    const node = target ? document.getElementById(domIdOf(target.conversation.id)) : null;
    if (node) {
      pendingFocus.current = null;
      node.focus({ preventScroll: true });
      node.scrollIntoView({ block: "nearest" });
    }
  };
  useLayoutEffect(flushPendingFocus);

  useImperativeHandle(
    ref,
    () => ({
      focus: (conversationId) => {
        const index = rows.findIndex((r) => r.conversation.id === (conversationId ?? selectedId));
        focusRow(index >= 0 ? index : 0);
      },
    }),
    [rows, selectedId, focusRow],
  );

  /* ----- Type-ahead ----- */
  const typeahead = useRef({ text: "", timer: 0 });
  function typeAhead(char: string, from: number) {
    const t = typeahead.current;
    window.clearTimeout(t.timer);
    t.text += char.toLocaleLowerCase();
    t.timer = window.setTimeout(() => (t.text = ""), 600);
    const titles = rows.map((r) => conversationTitle(r.conversation, people, currentUserId).toLocaleLowerCase());
    const start = t.text.length === 1 ? from + 1 : from;
    for (let k = 0; k < rowCount; k++) {
      const i = (start + k) % rowCount;
      if (titles[i]?.startsWith(t.text)) {
        focusRow(i);
        return;
      }
    }
  }

  const liveRef = useLatest({ onSelect, rows, focusRow, rowCount, onAction, typeAhead });
  const onRowKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>, index: number) => {
      const { onSelect: select, rows: list, focusRow: focus, rowCount: count, typeAhead: search } = liveRef.current;
      const row = list[index];
      if (!row) return;
      const page = Math.max(1, Math.floor((scrollRef.current?.clientHeight ?? 400) / ROW_HEIGHT.comfortable) - 1);
      switch (event.key) {
        case "ArrowDown":
          event.preventDefault();
          focus(index + 1);
          return;
        case "ArrowUp":
          event.preventDefault();
          focus(index - 1);
          return;
        case "Home":
          event.preventDefault();
          focus(0);
          return;
        case "End":
          event.preventDefault();
          focus(count - 1);
          return;
        case "PageDown":
          event.preventDefault();
          focus(index + page);
          return;
        case "PageUp":
          event.preventDefault();
          focus(index - page);
          return;
        case "Enter":
        case " ":
          event.preventDefault();
          select?.(row.conversation, "keyboard");
          return;
      }
      if (event.key.length === 1 && /\S/.test(event.key) && !event.ctrlKey && !event.metaKey && !event.altKey) {
        event.preventDefault();
        search(event.key, index);
      }
    },
    [liveRef],
  );

  /* ----- Row actions: one ⋯ menu and one context menu for every row ----- */
  const rowMenu = useMemo(() => createMenuHandle<string>(), []);
  const [contextId, setContextIdState] = useState<string | null>(null);
  // Read synchronously when the menu opens (the state is a render behind for keyboard opens).
  const contextRef = useRef<string | null>(null);
  const setContextId = useCallback((value: string | null) => {
    contextRef.current = value;
    setContextIdState(value);
  }, []);
  // A long-press menu stays open when the finger is held past a second (see useLongPressMenuGuard).
  const contextOpen = useRef(false);
  const longPressGuard = useLongPressMenuGuard(useCallback(() => contextOpen.current, []));
  const byId = useMemo(() => new Map(conversations.map((c) => [c.id, c])), [conversations]);
  const contextConversation = contextId ? byId.get(contextId) : undefined;

  const runAction = useCallback(
    (conversation: ChatConversation, action: ChatConversationAction) => {
      onAction?.(conversation, action);
      const name = conversationTitle(conversation, people, currentUserId);
      const words: Record<ChatConversationAction, string> = {
        pin: L.pin,
        unpin: L.unpin,
        mute: L.mute,
        unmute: L.unmute,
        archive: L.archive,
        unarchive: L.unarchive,
        markRead: L.markRead,
        markUnread: L.markUnread,
      };
      announce(`${words[action]}: ${name}`);
    },
    [onAction, people, currentUserId, L, announce],
  );

  function actionItems(c: ChatConversation) {
    const unread = (c.unreadCount ?? 0) > 0;
    return [
      <MenuItem
        key="pin"
        icon={c.pinned ? <PinOffIcon /> : <PinIcon />}
        onClick={() => runAction(c, c.pinned ? "unpin" : "pin")}
        disabled={Boolean(c.archived)}
      >
        {c.pinned ? L.unpin : L.pin}
      </MenuItem>,
      <MenuItem
        key="mute"
        icon={c.muted ? <BellIcon /> : <BellOffIcon />}
        onClick={() => runAction(c, c.muted ? "unmute" : "mute")}
      >
        {c.muted ? L.unmute : L.mute}
      </MenuItem>,
      <MenuItem
        key="read"
        icon={unread ? <MailOpenIcon /> : <MailDotIcon />}
        onClick={() => runAction(c, unread ? "markRead" : "markUnread")}
      >
        {unread ? L.markRead : L.markUnread}
      </MenuItem>,
      <MenuSeparator key="sep" />,
      <MenuItem
        key="archive"
        icon={c.archived ? <UnarchiveIcon /> : <ArchiveIcon />}
        onClick={() => runAction(c, c.archived ? "unarchive" : "archive")}
      >
        {c.archived ? L.unarchive : L.archive}
      </MenuItem>,
    ];
  }

  /* ----- Swipe (touch) ----- */
  const [swipedId, setSwipedId] = useState<string | null>(null);

  // One stable object for every row, so rows stay memoised.
  const rowActionsRef = useLatest({ onSelect, runAction });
  const rowActions = useMemo<RowActions>(
    () => ({
      select: (c, via) => rowActionsRef.current.onSelect?.(c, via),
      focus: (index) => {
        followSelection.current = false;
        setActiveIndex(index);
      },
      swipe: (conversationId, open) =>
        setSwipedId((current) => (open ? conversationId : current === conversationId ? null : current)),
      action: (c, action) => rowActionsRef.current.runAction(c, action),
      keyDown: onRowKeyDown,
    }),
    [rowActionsRef, onRowKeyDown],
  );
  useEffect(() => {
    if (!swipedId) return;
    // Any tap outside the open row closes it.
    const close = (event: PointerEvent) => {
      const row = (event.target as Element | null)?.closest("[data-conversation-row]");
      if (row?.getAttribute("data-conversation-row") !== swipedId) setSwipedId(null);
    };
    document.addEventListener("pointerdown", close, true);
    return () => document.removeEventListener("pointerdown", close, true);
  }, [swipedId]);

  /* ----- Render ----- */
  const Heading = HEADING_TAGS[headingBelow(headingLevel, 0)];
  const showTitle = title !== false;
  const filterItems = (["all", "unread", "groups", "archived"] as const).map((f) => ({
    value: f,
    "aria-label": f === "all" ? L.filters[f] : `${L.filters[f]}, ${L.resultsCount(counts[f])}`,
    label: (
      <span className="inline-flex min-w-0 items-center gap-1">
        <span className="min-w-0 truncate">{L.filters[f]}</span>
        {/* A real space, so the visible text reads "Unread 2" and contains the start of the name ("Unread, 2 chats"). */}
        {counts[f] > 0 && f !== "all" && " "}
        {counts[f] > 0 && f !== "all" && (
          <span
            aria-hidden
            className="shrink-0 rounded-full bg-sheen-hover px-1 text-2xs leading-4 font-semibold tabular-nums text-sheen-fg-muted group-data-[fit=tight]/segmented:hidden"
          >
            {counts[f] > 99 ? L.unreadOverflow : counts[f]}
          </span>
        )}
      </span>
    ),
  }));

  const empty = !loading && rowCount === 0;

  const renderItem = (item: Item, i: number) => {
    const style = windowed
      ? {
          position: "absolute" as const,
          top: offsets[i],
          insetInline: 0,
          height: item.type === "header" ? HEADER_HEIGHT : rowHeight,
        }
      : undefined;
    if (item.type === "header") {
      return (
        <div key={item.key} role="none" style={style} className="flex h-[34px] items-end px-4 pb-1.5">
          <span aria-hidden className="text-2xs font-semibold tracking-[0.08em] text-sheen-fg-muted uppercase">
            {item.label}
          </span>
        </div>
      );
    }
    const c = item.conversation;
    return (
      <ConversationRow
        key={item.key}
        // A number, not a style object: a fresh object every render would defeat the row's memo.
        windowTop={windowed ? offsets[i] : undefined}
        conversation={c}
        index={item.index}
        count={rowCount}
        domId={domIdOf(c.id)}
        selected={c.id === selectedId}
        tabbable={item.index === tabStop}
        swiped={swipedId === c.id}
        swipeEnabled={swipeActions && Boolean(onAction) && coarse}
        people={people}
        currentUserId={currentUserId}
        query={q}
        now={now}
        locale={locale}
        labels={L}
        density={density}
        reduced={reduced}
        selectionId={`${id}-selection`}
        actions={rowActions}
        rowMenu={onAction ? rowMenu : null}
        hasActions={Boolean(onAction)}
      />
    );
  };

  return (
    <section
      role="group"
      aria-labelledby={headingId}
      data-slot="conversation-list"
      className={cn("@container flex h-full min-h-0 w-full min-w-0 flex-col", className)}
    >
      <ChatKeyframes />
      <div className="flex shrink-0 flex-col gap-3 px-3 pt-3 pb-2 @sm:px-4">
        <div className={cn("flex min-h-9 items-center gap-2", !showTitle && "sr-only")}>
          <Heading id={headingId} className="min-w-0 flex-1 truncate text-lg font-semibold tracking-tight">
            {showTitle ? (title ?? L.chats) : L.chats}
          </Heading>
          {headerActions}
        </div>
        {showSearch && (
          <Input
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "ArrowDown" && rowCount > 0) {
                e.preventDefault();
                focusRow(0);
              } else if (e.key === "Escape" && query) {
                e.preventDefault();
                e.stopPropagation();
                setQuery("");
              }
            }}
            aria-label={L.search}
            placeholder={L.searchPlaceholder}
            enterKeyHint="search"
            autoComplete="off"
            // Its field is glass-1 inside the wrapper: no second blur on the list's surface.
            className="w-full [&_.glass-1]:[-webkit-backdrop-filter:none] [&_.glass-1]:[backdrop-filter:none]"
            inputClassName="[&::-webkit-search-cancel-button]:hidden"
            leading={<SearchIcon className="size-4" />}
            trailing={
              query ? (
                <button
                  type="button"
                  onClick={(e) => {
                    setQuery("");
                    (
                      e.currentTarget
                        .closest("[data-slot='conversation-list']")
                        ?.querySelector("input[type='search']") as HTMLInputElement | null
                    )?.focus();
                  }}
                  aria-label={L.clearSearch}
                  className="relative -me-1.5 flex size-7 cursor-pointer items-center justify-center rounded-full hover:bg-sheen-hover hover:text-sheen-fg focus-visible:outline-2 focus-visible:outline-sheen-focus any-pointer-coarse:after:absolute any-pointer-coarse:after:size-11"
                >
                  <XIcon className="size-3.5" />
                </button>
              ) : undefined
            }
          />
        )}
        {showFilters && (
          <SegmentedControl
            aria-label={L.filtersLabel}
            items={filterItems}
            value={filter}
            onValueChange={(v) => setFilter(v as ChatListFilter)}
            size="sm"
            fullWidth
            className={chatNoBlur}
          />
        )}
      </div>

      <div
        ref={attachScroller}
        className="group/scroller relative min-h-0 flex-1 overflow-x-hidden overflow-y-auto overscroll-contain [scrollbar-width:thin]"
      >
        {loading ? (
          <SkeletonGroup labels={{ loading: L.loadingChats }} className="flex flex-col">
            {Array.from({ length: 8 }, (_, i) => (
              <div key={i} className="flex h-[72px] items-center gap-3 px-4">
                <Skeleton shape="circle" width={48} />
                <div className="flex min-w-0 flex-1 flex-col gap-2">
                  <div className="flex justify-between gap-6">
                    <Skeleton shape="text" width={`${45 + ((i * 17) % 30)}%`} height={12} />
                    <Skeleton shape="text" width={32} height={10} />
                  </div>
                  <Skeleton shape="text" width={`${60 + ((i * 23) % 35)}%`} height={10} />
                </div>
              </div>
            ))}
          </SkeletonGroup>
        ) : empty ? (
          <div className="flex min-h-full items-center justify-center p-6">
            {q ? (
              <EmptyState
                icon={<SearchIcon className="size-6" />}
                title={L.noResultsTitle(query.trim())}
                description={L.noResultsDescription}
                headingLevel={false}
                announce
              />
            ) : conversations.length === 0 ? (
              <EmptyState
                icon={<ChatsIcon className="size-6" />}
                title={L.noChatsTitle}
                description={L.noChatsDescription}
                action={emptyAction}
                headingLevel={false}
              />
            ) : (
              <EmptyState
                variant="compact"
                icon={
                  filter === "archived" ? (
                    <ArchiveIcon className="size-6" />
                  ) : filter === "groups" ? (
                    <UsersIcon className="size-6" />
                  ) : (
                    <MailOpenIcon className="size-6" />
                  )
                }
                title={filter === "all" ? L.noChatsTitle : L.emptyFilter[filter]}
                headingLevel={false}
              />
            )}
          </div>
        ) : (
          <ContextMenu
            onOpenChangeComplete={(open) => !open && !contextRef.current && setContextIdState(null)}
            onOpenChange={(open, details) => {
              if (open && !contextRef.current) details.cancel();
              if (!open) contextRef.current = null;
              contextOpen.current = open && !details.isCanceled;
            }}
          >
            <ContextMenuTrigger
              {...longPressGuard}
              role="listbox"
              aria-labelledby={headingId}
              aria-describedby={hintId}
              aria-orientation="vertical"
              onPointerDownCapture={(e) => {
                if (e.button !== 2 && e.pointerType !== "touch") return;
                const row = (e.target as Element).closest<HTMLElement>("[data-conversation-row]");
                setContextId(onAction && row ? (row.dataset.conversationRow ?? null) : null);
              }}
              onContextMenuCapture={(e) => {
                const row = (e.target as Element).closest<HTMLElement>("[data-conversation-row]");
                if (!row || !onAction) {
                  e.stopPropagation();
                  return;
                }
                setContextId(row.dataset.conversationRow ?? null);
              }}
              className={cn(
                "relative pb-2 select-auto focus-visible:outline-none group-data-[scrolling]/scroller:pointer-events-none",
                windowed && "contain-strict",
              )}
              style={windowed ? { height: total + 8 } : undefined}
            >
              {windowed ? (
                <ListWindow
                  items={items}
                  offsets={offsets}
                  rowHeight={rowHeight}
                  keepIndex={tabRow ? items.indexOf(tabRow) : -1}
                  scroller={scroller}
                  renderItem={renderItem}
                  afterRender={flushPendingFocus}
                />
              ) : (
                items.map(renderItem)
              )}
            </ContextMenuTrigger>
            <ContextMenuContent className="min-w-52">
              {contextConversation ? actionItems(contextConversation) : null}
            </ContextMenuContent>
          </ContextMenu>
        )}
      </div>

      <p id={hintId} hidden>
        {L.listHint}
      </p>

      {onAction && (
        <Menu handle={rowMenu}>
          {({ payload }: { payload: string | undefined }) => {
            const c = payload ? byId.get(payload) : undefined;
            return (
              // Back to the chat's row (the ⋯ button is a mouse shortcut, hidden from screen readers and the Tab order).
              <MenuContent
                className="min-w-52"
                align="end"
                finalFocus={() => (payload ? document.getElementById(domIdOf(payload)) : null) ?? true}
              >
                {c ? actionItems(c) : null}
              </MenuContent>
            );
          }}
        </Menu>
      )}
      {announcer}
    </section>
  );
}

import type { HeadingLevelOption } from "../../lib/heading";
import { type ReactNode, type Ref } from "react";

import { conversationTitle, isGroup, otherMembers, toTime, type ParticipantMap } from "../format";
import { type ChatLabels } from "../labels";
import type { ChatConversation, ChatConversationAction, ChatListFilter, ChatParticipant } from "../types";

/** Imperative handle of {@link ConversationList}: focus a row from your own code. */
export type ConversationListHandle = {
  /** Focus a chat's row (the selected one, or the first, when no id is given). */
  focus: (conversationId?: string | null) => void;
};

/** Props of {@link ConversationList}. Required: `conversations`, `participants`, `currentUserId`. */
export type ConversationListProps = {
  /** The chats to list (any order: pinned first, then newest activity). */
  conversations: ChatConversation[];
  /** Everyone who can appear: names, avatars and presence come from here. */
  participants: ChatParticipant[];
  /** Your id (to name direct chats after the other person, and to mark your own last message). */
  currentUserId: string;
  /** The open chat: marked as selected (aria-selected). */
  selectedId?: string | null;
  /** A row was opened (click, tap, Enter or Space). `via` tells keyboard from pointer, to move focus sensibly. */
  onSelect?: (conversation: ChatConversation, via: "pointer" | "keyboard") => void;
  /** Pin, mute, archive, mark read… from the ⋯ menu, right-click, long-press or a swipe. Leave out to hide them. */
  onAction?: (conversation: ChatConversation, action: ChatConversationAction) => void;
  /** The active filter: "all", "unread", "groups" or "archived" (controlled). */
  filter?: ChatListFilter;
  /**
   * The filter on mount (uncontrolled).
   * @default "all"
   */
  defaultFilter?: ChatListFilter;
  /** Called with the new filter. */
  onFilterChange?: (filter: ChatListFilter) => void;
  /** Sets the search text when controlled. */
  query?: string;
  /**
   * The search text on mount (uncontrolled).
   * @default ""
   */
  defaultQuery?: string;
  /** Called with the search text as it changes. */
  onQueryChange?: (query: string) => void;
  /**
   * Shows skeleton rows while the list loads.
   * @default false
   */
  loading?: boolean;
  /** Heading above the list (defaults to "Chats"); false hides it (it stays the list's name). */
  title?: ReactNode | false;
  /**
   * Level of the list's heading.
   * Pass `"none"` for a paragraph with no heading role (for an example).
   * @default 2
   */
  headingLevel?: HeadingLevelOption;
  /** Shows the buttons beside the heading ("New chat"). */
  headerActions?: ReactNode;
  /**
   * Show the search field.
   * @default true
   */
  showSearch?: boolean;
  /**
   * Show the All / Unread / Groups / Archived filters.
   * @default true
   */
  showFilters?: boolean;
  /**
   * Touch: swipe a row towards the start to reveal Pin / Mute / Archive.
   * @default true
   */
  swipeActions?: boolean;
  /** Under the "No chats yet" message (a "Start a chat" button). */
  emptyAction?: ReactNode;
  /**
   * Sets the row height: 72px comfortable, 64px compact.
   * @default "comfortable"
   */
  density?: "comfortable" | "compact";
  /**
   * Above this many rows, only the visible ones are rendered (smooth with thousands of chats).
   * @default 150
   */
  windowThreshold?: number;
  /** Ref to the imperative handle ({@link ConversationListHandle}). */
  ref?: Ref<ConversationListHandle>;
  /** Fixes the current time used for relative dates (for tests and screenshots). */
  now?: Date;
  /** BCP 47 locale for times. Pass one for prerendered pages. */
  locale?: string;
  /** Any UI string (i18n); see {@link ChatLabels}. */
  labels?: Partial<ChatLabels>;
  /** Adds extra classes to the outer element. */
  className?: string;
};

/** One virtual list item: a group header or a conversation row. @internal */
export type Item =
  | { type: "header"; key: string; label: string }
  | { type: "row"; key: string; conversation: ChatConversation; index: number };

/** The height of a group header, in pixels. @internal */
export const HEADER_HEIGHT = 34;
/** The height of a conversation row for each density, in pixels. @internal */
export const ROW_HEIGHT = { comfortable: 72, compact: 64 } as const;
/** The extra rows rendered beyond the viewport. @internal */
export const OVERSCAN = 8;
/** The width of the revealed swipe actions, in pixels. @internal */
export const SWIPE_ACTION_WIDTH = 72;

/** Newest activity first. */
export function activity(c: ChatConversation) {
  return Math.max(toTime(c.lastMessage?.createdAt), toTime(c.updatedAt));
}

/** What search looks through: the name, the members, the last message and the draft (lower case). */
export function haystack(c: ChatConversation, people: ParticipantMap, currentUserId: string) {
  return [
    conversationTitle(c, people, currentUserId),
    ...otherMembers(c, people, currentUserId).map((p) => p.name),
    c.lastMessage?.deleted ? "" : (c.lastMessage?.text ?? ""),
    c.draft ?? "",
  ]
    .join("\n")
    .toLocaleLowerCase();
}

/** True when a conversation matches a list filter. @internal */
export function inFilter(c: ChatConversation, filter: ChatListFilter) {
  if (filter === "archived") return Boolean(c.archived);
  if (c.archived) return false;
  if (filter === "unread") return (c.unreadCount ?? 0) > 0;
  if (filter === "groups") return isGroup(c);
  return true;
}

"use client";

import {
  memo,
  useEffect,
  useEffectEvent,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
} from "react";
import { motion } from "motion/react";

import { cn } from "../../lib/cn";
import { spring } from "../../motion/tokens";
import { MenuTrigger, createMenuHandle } from "../../menu/menu";
import { ChatAvatar, DeliveryStatus, TypingDots, UnreadBadge, chatAppearReduced } from "../chat-parts";
import {
  conversationTitle,
  firstName,
  formatListTime,
  isGroup,
  messageSummary,
  otherMembers,
  toDate,
  type ParticipantMap,
} from "../format";
import { type ChatLabels } from "../labels";
import { Highlight } from "../message-parts";
import type { ChatConversation, ChatConversationAction } from "../types";
import { ArchiveIcon, BellIcon, BellOffIcon, MoreIcon, PinIcon, PinOffIcon, UnarchiveIcon } from "../icons";
import { isRtlAt } from "../../hooks/use-direction";
import { type Item, OVERSCAN, SWIPE_ACTION_WIDTH } from "./model";

/* ---------- Windowing ---------- */

/*
 * The rows in view (plus overscan), and the focused row when it is scrolled away (so focus is
 * never lost). It owns the scroll position, so scrolling re-renders only this, never the
 * heading, search or filters above (whose sliding indicator would measure layout every time),
 * and only when the window moves by half the overscan (4 rows). One sorted array: a row that
 * moves between "kept" and "in view" stays the same node (from two arrays React would remount
 * it and drop its focus).
 */
/** Renders the visible window of the virtual conversation list, keeping the focused row mounted. @internal */
export function ListWindow({
  items,
  offsets,
  rowHeight,
  keepIndex,
  scroller,
  renderItem,
  afterRender,
}: {
  items: Item[];
  offsets: number[];
  rowHeight: number;
  /** The focused row's index in `items` (-1: none). */
  keepIndex: number;
  /** The scrolling element (null until it is attached, then the effect below binds to it). */
  scroller: HTMLDivElement | null;
  renderItem: (item: Item, index: number) => ReactNode;
  /** Runs after each render of the window (focus a row that just came into the page). */
  afterRender: () => void;
}) {
  const [viewport, setViewport] = useState({ top: 0, height: 800 });
  useLayoutEffect(() => afterRender());
  useLayoutEffect(() => {
    const el = scroller;
    if (!el) return;
    const chunk = (OVERSCAN / 2) * rowHeight;
    let height = el.clientHeight;
    let idle = 0;
    // Layout is read outside React's render (never inside a state updater).
    const update = () => {
      const top = Math.floor(el.scrollTop / chunk) * chunk;
      setViewport((v) => (v.top === top && v.height === height ? v : { top, height }));
    };
    const onScroll = () => {
      update();
      // While it scrolls, rows passing under a still pointer don't light up (no repaint, no hit-testing per row).
      el.setAttribute("data-scrolling", "");
      window.clearTimeout(idle);
      idle = window.setTimeout(() => el.removeAttribute("data-scrolling"), 120);
    };
    update();
    const observer =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(() => {
            height = el.clientHeight;
            update();
          });
    observer?.observe(el);
    el.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      observer?.disconnect();
      el.removeEventListener("scroll", onScroll);
      window.clearTimeout(idle);
      el.removeAttribute("data-scrolling");
    };
  }, [scroller, rowHeight]);

  const top = viewport.top - OVERSCAN * rowHeight;
  const bottom = viewport.top + viewport.height + OVERSCAN * rowHeight;
  let start = 0;
  while (start < items.length && (offsets[start + 1] ?? 0) < top) start++;
  let end = start;
  while (end < items.length && (offsets[end] ?? 0) < bottom) end++;

  const indices: number[] = [];
  if (keepIndex >= 0 && keepIndex < start) indices.push(keepIndex);
  for (let i = start; i < end; i++) indices.push(i);
  if (keepIndex >= end) indices.push(keepIndex);
  return (
    <>
      {indices.map((i) => {
        const item = items[i];
        return item ? renderItem(item, i) : null;
      })}
    </>
  );
}

/* ---------- Row ---------- */

/** The row action callbacks: select, pin, mute, archive and delete. @internal */
export type RowActions = {
  select: (conversation: ChatConversation, via: "pointer" | "keyboard") => void;
  focus: (index: number) => void;
  swipe: (conversationId: string, open: boolean) => void;
  action: (conversation: ChatConversation, action: ChatConversationAction) => void;
  keyDown: (event: KeyboardEvent<HTMLDivElement>, index: number) => void;
};

/** The props of one conversation row. @internal */
export type ConversationRowProps = {
  conversation: ChatConversation;
  index: number;
  count: number;
  domId: string;
  selected: boolean;
  tabbable: boolean;
  swiped: boolean;
  swipeEnabled: boolean;
  people: ParticipantMap;
  currentUserId: string;
  query: string;
  now: Date;
  locale?: string;
  labels: ChatLabels;
  density: "comfortable" | "compact";
  reduced: boolean;
  selectionId: string;
  actions: RowActions;
  rowMenu: ReturnType<typeof createMenuHandle<string>> | null;
  hasActions: boolean;
  /** Windowed: the row's offset from the top of the list (it is absolutely positioned). */
  windowTop?: number;
};

/** One conversation row with swipe actions and a context menu. @internal */
export const ConversationRow = memo(function ConversationRow({
  conversation: c,
  index,
  count,
  domId,
  selected,
  tabbable,
  swiped,
  swipeEnabled,
  people,
  currentUserId,
  query,
  now,
  locale,
  labels: L,
  density,
  reduced,
  selectionId,
  actions,
  rowMenu,
  hasActions,
  windowTop,
}: ConversationRowProps) {
  const onSwipe = (open: boolean) => actions.swipe(c.id, open);
  const onAction = hasActions ? (action: ChatConversationAction) => actions.action(c, action) : undefined;
  const others = otherMembers(c, people, currentUserId);
  const group = isGroup(c);
  const title = conversationTitle(c, people, currentUserId);
  const direct = group ? undefined : others[0];
  const unread = c.unreadCount ?? 0;
  const last = c.lastMessage;
  const lastDate = toDate(last?.createdAt ?? c.updatedAt);
  const time = lastDate ? formatListTime(lastDate, now, locale, L.justNow) : null;
  const typing = (c.typingIds ?? []).filter((t) => t !== currentUserId);
  const ownLast = last?.senderId === currentUserId;
  const compact = density === "compact";

  /* Preview line */
  let preview: ReactNode;
  if (typing.length) {
    const names = typing.map((t) => firstName(people.get(t)?.name ?? ""));
    preview = (
      <span className="flex min-w-0 items-center gap-1.5 font-medium text-sheen-accent">
        <span className="truncate">{L.typing(names, group)}</span>
        <TypingDots className="shrink-0" />
      </span>
    );
  } else if (c.draft) {
    preview = (
      <span dir="auto" className="min-w-0 truncate text-start">
        <span className="font-semibold text-sheen-danger-text">{L.draftPrefix} </span>
        <Highlight text={c.draft} query={query} />
      </span>
    );
  } else if (last) {
    const summary = last.kind === "system" ? (last.text ?? "") : messageSummary(last, L, ownLast);
    const prefix =
      last.kind === "system"
        ? ""
        : ownLast
          ? L.youPrefix
          : group
            ? `${firstName(people.get(last.senderId)?.name ?? "")}:`
            : "";
    const ticks = ownLast && !last.deleted && last.kind !== "system";
    preview = (
      <span className="flex min-w-0 items-center gap-1">
        {ticks && <DeliveryStatus status={last.status ?? "sent"} labels={L} spoken={false} />}
        <span dir="auto" className={cn("min-w-0 truncate text-start", last.deleted && "italic")}>
          {prefix && <span className={cn(ownLast ? "" : "font-medium text-sheen-fg")}>{prefix} </span>}
          <Highlight text={summary} query={query} />
          {/* Ticks come first on screen (WhatsApp); spoken after the text: "You: see you there, Read". */}
          {ticks && <span className="sr-only">, {L.status[last.status ?? "sent"]}</span>}
        </span>
      </span>
    );
  }

  /* Swipe: drag the row towards the start to reveal its actions. */
  const rowRef = useRef<HTMLDivElement>(null);
  const drag = useRef<{ x: number; y: number; dx: number; active: boolean; pointerId: number; base: number } | null>(
    null,
  );
  const suppressClick = useRef(false);
  const actionsWidth = SWIPE_ACTION_WIDTH * 3;
  const openOffset = -actionsWidth;

  const setOffset = (px: number, animate: boolean) => {
    const el = rowRef.current;
    if (!el) return;
    const rtl = isRtlAt(el);
    el.style.transition =
      animate && !reduced ? "transform var(--sheen-duration-smooth) var(--sheen-ease-smooth)" : "none";
    el.style.transform = px === 0 ? "" : `translateX(${rtl ? -px : px}px)`;
  };

  // Opened / closed from outside (another row, a tap elsewhere). Not on mount: a row that mounts
  // closed has nothing to move (and reading its direction would force a style pass per row while
  // a long list scrolls).
  const wasSwiped = useRef(swiped);
  // Reads the live drag and offset when the outside state changes: a changed offset mid-drag must not re-run it.
  const followOutside = useEffectEvent((open: boolean) => {
    if (!drag.current?.active) setOffset(open ? openOffset : 0, true);
  });
  useEffect(() => {
    if (wasSwiped.current === swiped) return;
    wasSwiped.current = swiped;
    followOutside(swiped);
  }, [swiped]);

  const onPointerDown = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!swipeEnabled || e.pointerType !== "touch") return;
    drag.current = {
      x: e.clientX,
      y: e.clientY,
      dx: 0,
      active: false,
      pointerId: e.pointerId,
      base: swiped ? openOffset : 0,
    };
  };
  const onPointerMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (d?.pointerId !== e.pointerId) return;
    const rtl = isRtlAt(e.currentTarget);
    const raw = (e.clientX - d.x) * (rtl ? -1 : 1);
    const dy = e.clientY - d.y;
    if (!d.active) {
      if (Math.abs(dy) > 10 && Math.abs(dy) > Math.abs(raw)) {
        drag.current = null; // a scroll
        return;
      }
      if (Math.abs(raw) < 8) return;
      d.active = true;
      e.currentTarget.setPointerCapture(e.pointerId);
      e.currentTarget.parentElement?.setAttribute("data-dragging", "");
    }
    // Resist past the open position (rubber band) and past the closed one.
    let next = d.base + raw;
    if (next > 0) next = next * 0.25;
    if (next < openOffset) next = openOffset + (next - openOffset) * 0.35;
    d.dx = next;
    setOffset(next, false);
  };
  const onPointerEnd = (e: ReactPointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    drag.current = null;
    if (!d || !d.active || e.pointerId !== d.pointerId) return;
    suppressClick.current = true;
    window.setTimeout(() => (suppressClick.current = false), 0);
    const open = d.dx < openOffset / 2.5;
    setOffset(open ? openOffset : 0, true);
    onSwipe(open);
    const wrapper = e.currentTarget.parentElement;
    window.setTimeout(() => wrapper?.removeAttribute("data-dragging"), open ? 0 : 400);
  };

  const timeTone = unread > 0 && !c.muted ? "font-semibold text-sheen-accent" : "text-sheen-fg-muted";

  return (
    <div
      role="none"
      data-conversation-row={c.id}
      style={
        windowTop === undefined
          ? undefined
          : { position: "absolute", top: windowTop, insetInline: 0, height: compact ? 64 : 72 }
      }
      className={cn("group/row relative isolate overflow-hidden", compact ? "h-16" : "h-[72px]")}
    >
      {/* Swipe actions, under the row */}
      {swipeEnabled && onAction && (
        <div
          aria-hidden
          className={cn("absolute inset-y-0 end-0 flex", !swiped && "invisible group-data-[dragging]/row:visible")}
          data-swipe-actions=""
        >
          {[
            {
              key: "pin",
              label: c.pinned ? L.unpin : L.pin,
              icon: c.pinned ? <PinOffIcon /> : <PinIcon />,
              action: (c.pinned ? "unpin" : "pin") as ChatConversationAction,
              tone: "bg-(--sheen-violet-700)",
            },
            {
              key: "mute",
              label: c.muted ? L.unmute : L.mute,
              icon: c.muted ? <BellIcon /> : <BellOffIcon />,
              action: (c.muted ? "unmute" : "mute") as ChatConversationAction,
              tone: "bg-(--sheen-amber-700)",
            },
            {
              key: "archive",
              label: c.archived ? L.unarchive : L.archive,
              icon: c.archived ? <UnarchiveIcon /> : <ArchiveIcon />,
              action: (c.archived ? "unarchive" : "archive") as ChatConversationAction,
              tone: "bg-(--sheen-ink-600)",
            },
          ].map((a) => (
            <button
              key={a.key}
              type="button"
              tabIndex={-1}
              onClick={() => {
                onAction(a.action);
                onSwipe(false);
              }}
              className={cn(
                "flex h-full flex-col items-center justify-center gap-1 text-2xs font-semibold text-sheen-accent-fg [&_svg]:size-5",
                a.tone,
                "forced-colors:border forced-colors:border-[ButtonText]",
              )}
              style={{ width: SWIPE_ACTION_WIDTH }}
            >
              {a.icon}
              {a.label}
            </button>
          ))}
        </div>
      )}

      <div
        ref={rowRef}
        id={domId}
        role="option"
        aria-selected={selected}
        aria-posinset={index + 1}
        aria-setsize={count}
        tabIndex={tabbable ? 0 : -1}
        onClick={() => {
          if (suppressClick.current) return;
          if (swiped) {
            onSwipe(false);
            return;
          }
          actions.select(c, "pointer");
        }}
        onKeyDown={(e) => {
          if (e.target !== e.currentTarget) return;
          if (e.key === "Escape" && swiped) {
            onSwipe(false);
            return;
          }
          actions.keyDown(e, index);
        }}
        onFocus={(e) => e.target === e.currentTarget && actions.focus(index)}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerEnd}
        onPointerCancel={onPointerEnd}
        className={cn(
          // Its own layer above the swipe actions (its tints sit inside it).
          "relative isolate z-[1] flex h-full cursor-pointer items-center gap-3 px-3 outline-none select-none @sm:px-4",
          "[-webkit-tap-highlight-color:transparent] [-webkit-touch-callout:none] touch-pan-y touch-pinch-zoom",
          "focus-visible:after:pointer-events-none focus-visible:after:absolute focus-visible:after:inset-x-1.5 focus-visible:after:inset-y-1 focus-visible:after:rounded-sheen-md focus-visible:after:outline-2 focus-visible:after:-outline-offset-2 focus-visible:after:outline-sheen-focus",
          "forced-colors:aria-selected:outline-2 forced-colors:aria-selected:-outline-offset-4 forced-colors:aria-selected:outline-[Highlight]",
        )}
      >
        {/* Surface: solid while swiping (covers the actions), hover / selected tints */}
        <span
          aria-hidden
          className={cn(
            "absolute inset-x-1.5 inset-y-1 -z-10 rounded-sheen-md transition-[background-color] duration-(--sheen-duration-fast)",
            !selected && "group-hover/row:bg-sheen-hover",
          )}
        />
        {swipeEnabled && (
          <span
            aria-hidden
            className={cn(
              "absolute inset-0 -z-20 bg-(--sheen-surface-solid)",
              !swiped && "opacity-0 group-data-[dragging]/row:opacity-100",
            )}
          />
        )}
        {selected && (
          <motion.span
            aria-hidden
            layoutId={reduced ? undefined : selectionId}
            transition={spring.snappy}
            className="absolute inset-x-1.5 inset-y-1 -z-10 rounded-sheen-md border border-sheen-accent-border bg-sheen-accent-soft"
          />
        )}

        <ChatAvatar
          people={others.slice(0, 2)}
          src={c.avatarUrl}
          name={title}
          size={compact ? "md" : "lg"}
          presence={direct?.presence}
        />

        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
          <div className="flex min-w-0 items-center gap-2">
            <span
              dir="auto"
              className={cn(
                "min-w-0 flex-1 truncate text-start text-[0.9375rem] leading-5",
                unread > 0 ? "font-semibold text-sheen-fg" : "font-medium text-sheen-fg",
              )}
            >
              <Highlight text={title} query={query} />
            </span>
            {c.muted && (
              <span className="shrink-0 text-sheen-fg-subtle">
                <BellOffIcon className="size-3.5" />
                <span className="sr-only">, {L.muted}</span>
              </span>
            )}
            {time && (
              <time
                dir="auto"
                dateTime={lastDate?.toISOString()}
                title={time.long}
                className={cn("shrink-0 text-xs tabular-nums", timeTone)}
              >
                <span aria-hidden>{time.short}</span>
                <span className="sr-only">, {time.long}</span>
              </time>
            )}
          </div>
          <div className="flex min-w-0 items-center gap-2 text-sm leading-5 text-sheen-fg-muted">
            <span className="sr-only">, </span>
            <span className="flex min-w-0 flex-1">{preview}</span>
            {c.pinned && (
              <span className="shrink-0 text-sheen-fg-subtle">
                <PinIcon className="size-3.5 rotate-45" />
                <span className="sr-only">, {L.pinned}</span>
              </span>
            )}
            {unread > 0 && (
              <>
                <span className="sr-only">, </span>
                <UnreadBadge
                  count={unread}
                  muted={c.muted}
                  overflow={L.unreadOverflow}
                  label={L.unreadCount(unread)}
                  className={cn(
                    "motion-ok:animate-[sheen-chat-pop_var(--sheen-duration-smooth)_var(--sheen-ease-smooth)]",
                    chatAppearReduced,
                  )}
                />
              </>
            )}
          </div>
        </div>
      </div>

      {/* ⋯ (mouse): a shortcut to the same actions as the context menu (Shift + F10) */}
      {rowMenu && onAction && (
        <MenuTrigger
          handle={rowMenu}
          payload={c.id}
          tabIndex={-1}
          aria-hidden
          className={cn(
            // A solid little button (no blur: one per row would blow the glass budget, even while hidden).
            "absolute end-3 top-1/2 z-[2] flex size-8 -translate-y-1/2 cursor-pointer items-center justify-center rounded-full border border-sheen-border bg-sheen-surface text-sheen-fg-muted shadow-sm",
            "opacity-0 transition-opacity duration-(--sheen-duration-fast) group-hover/row:opacity-100 data-popup-open:opacity-100 hover:text-sheen-fg",
            "pointer-coarse:hidden",
          )}
        >
          <MoreIcon className="size-4" />
        </MenuTrigger>
      )}
    </div>
  );
});

"use client";

import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent } from "react";

import { cn } from "../lib/cn";
import { defaultEmojiCategories, type ChatEmoji, type ChatEmojiCategory } from "./emoji";
import { resolveChatLabels, type ChatLabels } from "./labels";
import { SearchIcon, XIcon } from "./icons";
import { isRtlAt } from "../hooks/use-direction";
import { useSheenReducedMotion } from "../hooks/use-preferences";

/** Props of {@link EmojiPicker}. Only `onSelect` is required. */
export type EmojiPickerProps = {
  /** Called with the emoji character. */
  onSelect: (emoji: string) => void;
  /** The emoji to offer, by category (defaults to a curated ~170). */
  categories?: ChatEmojiCategory[];
  /** Emoji shown first under "Frequently used" (e.g. the quick reactions). */
  frequent?: readonly string[];
  /** Emoji to mark as chosen (your current reactions): aria-pressed + a tint. */
  selected?: readonly string[];
  /** Focus the search field when it mounts (off on touch screens, where it would raise the keyboard). */
  autoFocusSearch?: boolean;
  /** Any UI string (i18n); see {@link ChatLabels}. */
  labels?: Partial<ChatLabels>;
  /** Adds extra classes to the picker. */
  className?: string;
};

type Section = { id: string; title: string; icon: string; emojis: ChatEmoji[] };

const FREQUENT_ID = "frequent";

/** Lowercased text an emoji is matched on. */
const haystack = (e: ChatEmoji) => `${e.name} ${e.keywords ?? ""}`.toLowerCase();

/**
 * A compact emoji picker: search, category shortcuts and a grid. The grid is one tab stop:
 * arrow keys move between emoji (up and down keep the column), Home / End jump to the ends,
 * Enter or Space picks one. Typing in the search field narrows the grid; Enter there picks the
 * first match and ↓ moves into the results.
 *
 * Props: see {@link EmojiPickerProps} (`onSelect` required; `categories` a curated set by default,
 * `frequent`, `selected`, `autoFocusSearch` false, `labels`, `className`).
 *
 * Keyboard: The grid is one tab stop: arrows move between emoji (up and down keep the column), Home / End jump to the ends, Enter or Space picks. In the search field Enter picks the first match and Down moves into the results.
 * Accessibility: Every emoji is a button named by its spoken name ("red heart"); chosen emoji use `aria-pressed` plus a tint; the search field and category shortcuts have names; the result count is announced politely.
 * Glass: A flat panel meant to sit inside a popover or sheet (which provide the glass), so it adds no blur of its own.
 *
 * @example
 * ```tsx
 * import { EmojiPicker } from "@sheenui/theme";
 *
 * export const Reactions = () => <EmojiPicker onSelect={(emoji) => console.log(emoji)} frequent={["👍", "❤️", "😂"]} selected={["👍"]} />;
 * ```
 *
 * @see /chat/thread
 */
export function EmojiPicker({
  onSelect,
  categories = defaultEmojiCategories,
  frequent,
  selected,
  autoFocusSearch = false,
  labels: labelsProp,
  className,
}: EmojiPickerProps) {
  const L = useMemo(() => resolveChatLabels(labelsProp), [labelsProp]);
  const id = useId();
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const [current, setCurrent] = useState<string | null>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);
  const chosen = useMemo(() => new Set(selected ?? []), [selected]);

  const sections = useMemo<Section[]>(() => {
    const all = new Map<string, ChatEmoji>();
    for (const c of categories) for (const e of c.emojis) all.set(e.char, e);
    const list: Section[] = [];
    if (frequent?.length) {
      list.push({
        id: FREQUENT_ID,
        title: L.reactions,
        icon: frequent[0] ?? "⭐",
        emojis: frequent.map((char) => all.get(char) ?? { char, name: char }),
      });
    }
    for (const c of categories) {
      const title = (L.emojiCategories as Record<string, string>)[c.id] ?? c.id;
      list.push({ id: c.id, title, icon: c.icon, emojis: c.emojis });
    }
    return list;
  }, [categories, frequent, L]);

  const q = query.trim().toLowerCase();
  const results = useMemo(() => {
    if (!q) return null;
    const seen = new Set<string>();
    const out: ChatEmoji[] = [];
    for (const s of sections) {
      if (s.id === FREQUENT_ID) continue;
      for (const e of s.emojis) {
        if (seen.has(e.char) || !haystack(e).includes(q)) continue;
        seen.add(e.char);
        out.push(e);
      }
    }
    return out;
  }, [q, sections]);

  // The flat order of every emoji button, for roving focus.
  const flat = useMemo(() => results ?? sections.flatMap((s) => s.emojis), [results, sections]);
  const activeIndex = Math.min(active, Math.max(0, flat.length - 1));

  useEffect(() => {
    if (autoFocusSearch) searchRef.current?.focus({ preventScroll: true });
  }, [autoFocusSearch]);

  // A new search starts at the first result (adjusted in the same render, before it paints).
  const [seenQuery, setSeenQuery] = useState(q);
  if (seenQuery !== q) {
    setSeenQuery(q);
    setActive(0);
  }

  /* Which category is in view (for the tab highlight). */
  useEffect(() => {
    const grid = gridRef.current;
    if (!grid || results) return;
    const onScroll = () => {
      const top = grid.getBoundingClientRect().top;
      let found: string | null = null;
      for (const el of grid.querySelectorAll<HTMLElement>("[data-emoji-section]")) {
        if (el.getBoundingClientRect().top - top <= 24) found = el.dataset.emojiSection ?? null;
      }
      setCurrent(found ?? sections[0]?.id ?? null);
    };
    onScroll();
    grid.addEventListener("scroll", onScroll, { passive: true });
    return () => grid.removeEventListener("scroll", onScroll);
  }, [results, sections]);

  function buttons() {
    return Array.from(gridRef.current?.querySelectorAll<HTMLButtonElement>("button[data-emoji-index]") ?? []);
  }

  function focusIndex(index: number) {
    const list = buttons();
    const target = list[Math.max(0, Math.min(list.length - 1, index))];
    if (!target) return;
    setActive(Number(target.dataset.emojiIndex));
    target.focus();
    target.scrollIntoView({ block: "nearest" });
  }

  /** The button in the row above / below whose centre is closest to this one's (sections break rows). */
  function vertical(from: HTMLElement, direction: 1 | -1) {
    const list = buttons();
    const rect = from.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const rows = list
      .map((b) => ({ b, r: b.getBoundingClientRect() }))
      .filter(({ r }) => (direction === 1 ? r.top > rect.top + 2 : r.top < rect.top - 2));
    if (rows.length === 0) return null;
    const rowTop = direction === 1 ? Math.min(...rows.map(({ r }) => r.top)) : Math.max(...rows.map(({ r }) => r.top));
    const row = rows.filter(({ r }) => Math.abs(r.top - rowTop) < 2);
    row.sort((a, b) => Math.abs(a.r.left + a.r.width / 2 - cx) - Math.abs(b.r.left + b.r.width / 2 - cx));
    return row[0]?.b ?? null;
  }

  function onGridKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const target = event.target as HTMLElement;
    const index = Number(target.dataset.emojiIndex);
    if (Number.isNaN(index)) return;
    const rtl = isRtlAt(target);
    switch (event.key) {
      case "ArrowRight":
        event.preventDefault();
        focusIndex(index + (rtl ? -1 : 1));
        break;
      case "ArrowLeft":
        event.preventDefault();
        focusIndex(index + (rtl ? 1 : -1));
        break;
      case "ArrowDown":
      case "ArrowUp": {
        event.preventDefault();
        const next = vertical(target, event.key === "ArrowDown" ? 1 : -1);
        if (next) focusIndex(Number(next.dataset.emojiIndex));
        else if (event.key === "ArrowUp") searchRef.current?.focus();
        break;
      }
      case "Home":
        event.preventDefault();
        focusIndex(0);
        break;
      case "End":
        event.preventDefault();
        focusIndex(flat.length - 1);
        break;
    }
  }

  // Script-requested smooth scrolling ignores the reduced-motion CSS, so it is chosen here (WCAG 2.3.3).
  const reducedMotion = useSheenReducedMotion();
  function jumpTo(sectionId: string) {
    setQuery("");
    requestAnimationFrame(() => {
      const grid = gridRef.current;
      const el = grid?.querySelector<HTMLElement>(`[data-emoji-section="${CSS.escape(sectionId)}"]`);
      if (!grid || !el) return;
      // The grid is `relative`, so it is the section's offsetParent: `offsetTop` is already the distance
      // inside the scroller (the grid's own offset in its popover must not be subtracted).
      grid.scrollTo({ top: el.offsetTop, behavior: reducedMotion ? "auto" : "smooth" });
      setCurrent(sectionId);
    });
  }

  let counter = 0;
  const renderButton = (e: ChatEmoji) => {
    const index = counter++;
    const pressed = chosen.has(e.char);
    return (
      <button
        key={`${e.char}-${index}`}
        type="button"
        data-emoji-index={index}
        tabIndex={index === activeIndex ? 0 : -1}
        aria-label={e.name}
        aria-pressed={selected ? pressed : undefined}
        title={e.name}
        onClick={() => onSelect(e.char)}
        onFocus={() => setActive(index)}
        className={cn(
          "relative flex aspect-square w-full cursor-pointer items-center justify-center rounded-sheen-sm text-[1.375rem] leading-none select-none",
          "transition-[background-color,scale] duration-(--sheen-duration-fast) ease-sheen-out",
          "hover:bg-sheen-hover motion-ok:hover:scale-110 motion-ok:active:scale-95",
          "focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sheen-focus",
          "touch-manipulation [-webkit-tap-highlight-color:transparent]",
          pressed && "bg-sheen-accent-soft ring-1 ring-sheen-accent-border ring-inset forced-colors:ring-[Highlight]",
        )}
      >
        <span
          aria-hidden
          className="font-[system-ui,'Apple_Color_Emoji','Segoe_UI_Emoji','Noto_Color_Emoji',sans-serif]"
        >
          {e.char}
        </span>
      </button>
    );
  };

  const gridClass =
    "grid grid-cols-[repeat(auto-fill,minmax(2.25rem,1fr))] gap-0.5 any-pointer-coarse:grid-cols-[repeat(auto-fill,minmax(2.75rem,1fr))]";

  return (
    <div
      data-slot="emoji-picker"
      className={cn("flex w-[min(20rem,calc(100vw-2.5rem))] max-w-full min-w-0 flex-col gap-2", className)}
    >
      {/* Search */}
      <div className="glass-1 flex h-9 items-center gap-2 rounded-sheen-full border-sheen-control-border px-3 [-webkit-backdrop-filter:none] [backdrop-filter:none] has-[input:focus-visible]:outline-2 has-[input:focus-visible]:outline-offset-2 has-[input:focus-visible]:outline-sheen-focus any-pointer-coarse:h-11">
        <SearchIcon className="size-4 text-sheen-fg-muted" />
        <input
          ref={searchRef}
          type="search"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown") {
              e.preventDefault();
              focusIndex(0);
            } else if (e.key === "Enter" && results?.[0]) {
              e.preventDefault();
              onSelect(results[0].char);
            }
          }}
          aria-label={L.searchEmoji}
          aria-controls={`${id}-grid`}
          placeholder={L.searchEmoji}
          enterKeyHint="search"
          className="h-full w-full min-w-0 bg-transparent text-sm text-sheen-fg outline-none placeholder:text-sheen-fg-subtle forced-colors:focus-visible:outline-none! any-pointer-coarse:text-base [&::-webkit-search-cancel-button]:hidden"
        />
        {query && (
          <button
            type="button"
            onClick={() => {
              setQuery("");
              searchRef.current?.focus();
            }}
            aria-label={L.clearSearch}
            className="relative -me-1.5 flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-full text-sheen-fg-muted hover:bg-sheen-hover hover:text-sheen-fg focus-visible:outline-2 focus-visible:outline-sheen-focus any-pointer-coarse:after:absolute any-pointer-coarse:after:size-11"
          >
            <XIcon className="size-3.5" />
          </button>
        )}
      </div>

      {/* Category shortcuts */}
      {!results && (
        <div className="flex items-center justify-between gap-0.5" role="group" aria-label={L.emoji}>
          {sections.map((s) => (
            <button
              key={s.id}
              type="button"
              onClick={() => jumpTo(s.id)}
              aria-label={s.title}
              title={s.title}
              aria-current={current === s.id ? "true" : undefined}
              className={cn(
                "relative flex size-8 cursor-pointer items-center justify-center rounded-sheen-sm text-base leading-none grayscale-[0.6] transition-[background-color,filter] duration-(--sheen-duration-fast)",
                "hover:bg-sheen-hover hover:grayscale-0 focus-visible:outline-2 focus-visible:outline-sheen-focus",
                "aria-[current=true]:bg-sheen-accent-soft aria-[current=true]:grayscale-0",
                "after:absolute after:inset-x-2 after:-bottom-0.5 after:h-0.5 after:rounded-full after:bg-sheen-accent after:opacity-0 aria-[current=true]:after:opacity-100 forced-colors:aria-[current=true]:after:bg-[Highlight]",
                "any-pointer-coarse:size-9",
              )}
            >
              <span aria-hidden>{s.icon}</span>
            </button>
          ))}
        </div>
      )}

      {/* Grid */}
      {/* eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- roving-focus grid: the handler moves focus between the emoji buttons with the arrow keys */}
      <div
        ref={gridRef}
        id={`${id}-grid`}
        role="group"
        aria-label={results ? L.resultsCount(results.length) : L.emoji}
        onKeyDown={onGridKeyDown}
        className="relative h-56 overflow-y-auto overscroll-contain [scrollbar-width:thin] -mx-1 px-1"
      >
        {results ? (
          results.length === 0 ? (
            <p role="status" className="flex h-full items-center justify-center text-sm text-sheen-fg-muted">
              {L.noEmoji}
            </p>
          ) : (
            <div className={gridClass}>{results.map(renderButton)}</div>
          )
        ) : (
          sections.map((s) => (
            <div key={s.id} data-emoji-section={s.id} role="group" aria-labelledby={`${id}-${s.id}`} className="pb-2">
              <p
                id={`${id}-${s.id}`}
                className="px-1 pt-1 pb-1.5 text-2xs font-semibold tracking-wide text-sheen-fg-muted uppercase"
              >
                {s.title}
              </p>
              <div className={gridClass}>{s.emojis.map(renderButton)}</div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

import { formatBytes } from "../file-upload/file-utils";
import type { ChatLabels } from "./labels";
import type { ChatConversation, ChatDateInput, ChatMessage, ChatParticipant } from "./types";

/**
 * Date, time and preview helpers for the chat components. Everything goes through Intl with
 * the component's `locale`, so "5m", "Yesterday", weekdays and dates follow the language.
 */

export function toDate(value: ChatDateInput | undefined): Date | undefined {
  // `== null` also catches a null from untyped callers.
  if (value == null) return undefined;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? undefined : date;
}

/** Milliseconds since the epoch of a date input, or 0 when it is missing or unreadable (handy as a sort key). Pure, safe to call on the server. */
export function toTime(value: ChatDateInput | undefined): number {
  return toDate(value)?.getTime() ?? 0;
}

/** Whole calendar days from `date` to `now` (0 = same day, 1 = yesterday). */
export function calendarDayDiff(date: Date, now: Date): number {
  const a = Date.UTC(date.getFullYear(), date.getMonth(), date.getDate());
  const b = Date.UTC(now.getFullYear(), now.getMonth(), now.getDate());
  return Math.round((b - a) / 86_400_000);
}

/** A string that is equal for two dates on the same local calendar day (used to group messages by day). Pure, safe to call on the server. */
export function dayKey(date: Date): string {
  return `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
}

/* Intl objects are slow to build: cache them per locale + options. */
const cache = new Map<string, Intl.DateTimeFormat | Intl.RelativeTimeFormat | Intl.NumberFormat>();

function dtf(locale: string | undefined, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `d|${locale}|${JSON.stringify(options)}`;
  let f = cache.get(key) as Intl.DateTimeFormat | undefined;
  if (!f) {
    f = new Intl.DateTimeFormat(locale, options);
    cache.set(key, f);
  }
  return f;
}

function rtf(locale: string | undefined, options: Intl.RelativeTimeFormatOptions): Intl.RelativeTimeFormat {
  const key = `r|${locale}|${JSON.stringify(options)}`;
  let f = cache.get(key) as Intl.RelativeTimeFormat | undefined;
  if (!f) {
    f = new Intl.RelativeTimeFormat(locale, options);
    cache.set(key, f);
  }
  return f;
}

function nf(locale: string | undefined, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = `n|${locale}|${JSON.stringify(options)}`;
  let f = cache.get(key) as Intl.NumberFormat | undefined;
  if (!f) {
    f = new Intl.NumberFormat(locale, options);
    cache.set(key, f);
  }
  return f;
}

/** First letter upper case, in the locale's rules ("yesterday" → "Yesterday"). */
function capitalize(text: string, locale: string | undefined) {
  return text ? text.charAt(0).toLocaleUpperCase(locale) + text.slice(1) : text;
}

/** "14:05" / "2:05 PM". */
export function formatTime(date: Date, locale: string | undefined) {
  return dtf(locale, { hour: "numeric", minute: "2-digit" }).format(date);
}

/** Full date and time for tooltips and message info: "Thu, 30 Oct 2026, 14:05". */
export function formatDateTime(date: Date, locale: string | undefined) {
  return dtf(locale, { dateStyle: "medium", timeStyle: "short" }).format(date);
}

/**
 * The conversation list's compact time: "now", "5m", "14:05", "Yesterday", "Mon", "12 Mar",
 * "12/03/2025". Also returns a spoken version ("5 minutes ago", "yesterday at 14:05").
 */
export function formatListTime(
  date: Date,
  now: Date,
  locale: string | undefined,
  justNow: string,
): { short: string; long: string } {
  const seconds = (now.getTime() - date.getTime()) / 1000;
  const days = calendarDayDiff(date, now);
  if (seconds < 60 && seconds > -60)
    return { short: justNow, long: rtf(locale, { numeric: "auto" }).format(0, "second") };
  if (seconds < 3600 && days === 0) {
    const minutes = Math.max(1, Math.floor(seconds / 60));
    return {
      short: nf(locale, { style: "unit", unit: "minute", unitDisplay: "narrow" }).format(minutes),
      long: rtf(locale, { numeric: "auto" }).format(-minutes, "minute"),
    };
  }
  const time = formatTime(date, locale);
  if (days === 0) return { short: time, long: time };
  if (days === 1) {
    const yesterday = capitalize(rtf(locale, { numeric: "auto" }).format(-1, "day"), locale);
    return { short: yesterday, long: `${yesterday}, ${time}` };
  }
  if (days > 1 && days < 7) {
    return {
      short: dtf(locale, { weekday: "short" }).format(date),
      long: dtf(locale, { weekday: "long", hour: "numeric", minute: "2-digit" }).format(date),
    };
  }
  const sameYear = date.getFullYear() === now.getFullYear();
  return {
    short: sameYear
      ? dtf(locale, { day: "numeric", month: "short" }).format(date)
      : dtf(locale, { dateStyle: "short" }).format(date),
    long: dtf(locale, { dateStyle: "long" }).format(date),
  };
}

/** Day separator: "Today", "Yesterday", "Monday", "12 March", "12 March 2024". */
export function formatDayLabel(date: Date, now: Date, locale: string | undefined) {
  const days = calendarDayDiff(date, now);
  if (days === 0 || days === 1) return capitalize(rtf(locale, { numeric: "auto" }).format(-days, "day"), locale);
  if (days > 1 && days < 7) return dtf(locale, { weekday: "long" }).format(date);
  const sameYear = date.getFullYear() === now.getFullYear();
  return dtf(
    locale,
    sameYear ? { weekday: "short", day: "numeric", month: "long" } : { day: "numeric", month: "long", year: "numeric" },
  ).format(date);
}

/** "5m ago", "2h ago", "yesterday", "3 days ago", or a date further back. */
export function formatRelative(date: Date, now: Date, locale: string | undefined) {
  const seconds = Math.max(0, (now.getTime() - date.getTime()) / 1000);
  const narrow = rtf(locale, { numeric: "auto", style: "narrow" });
  if (seconds < 60) return rtf(locale, { numeric: "auto" }).format(0, "second");
  if (seconds < 3600) return narrow.format(-Math.floor(seconds / 60), "minute");
  if (seconds < 86_400) return narrow.format(-Math.floor(seconds / 3600), "hour");
  const days = calendarDayDiff(date, now);
  if (days < 7) return rtf(locale, { numeric: "auto" }).format(-days, "day");
  return dtf(locale, { day: "numeric", month: "short" }).format(date);
}

/* ---------- Text direction ---------- */

const RTL_SCRIPT =
  /[\p{Script=Arabic}\p{Script=Hebrew}\p{Script=Syriac}\p{Script=Thaana}\p{Script=Nko}\p{Script=Adlam}]/u;

/**
 * The direction of a message from its first letter (the Unicode "first strong character" rule),
 * so an English message in an Arabic interface reads left to right, time and all. Undefined
 * when there are no letters (emoji, numbers): it then follows the page.
 */
export function textDirection(text: string | undefined): "ltr" | "rtl" | undefined {
  const first = text?.match(/\p{L}/u)?.[0];
  if (!first) return undefined;
  return RTL_SCRIPT.test(first) ? "rtl" : "ltr";
}

/* ---------- People and previews ---------- */

/** Participants indexed by id, for quick lookups while rendering. */
export type ParticipantMap = Map<string, ChatParticipant>;

/** Builds a `ParticipantMap` from a participant list (an empty map when it is missing). Pure, safe to call on the server. */
export function toParticipantMap(participants: readonly ChatParticipant[] | undefined): ParticipantMap {
  return new Map((participants ?? []).map((p) => [p.id, p]));
}

/** Everyone in the conversation except you. */
export function otherMembers(
  conversation: ChatConversation,
  people: ParticipantMap,
  currentUserId: string,
): ChatParticipant[] {
  return conversation.participantIds
    .filter((id) => id !== currentUserId)
    .flatMap((id) => {
      const p = people.get(id);
      return p ? [p] : [];
    });
}

/** True when the conversation is a group chat rather than a one-to-one chat. Pure, safe to call on the server. */
export function isGroup(conversation: ChatConversation) {
  return conversation.kind === "group";
}

/** The name to show for a conversation: its own `title`, otherwise the other members' names joined with commas, otherwise its id. Pure, safe to call on the server. */
export function conversationTitle(
  conversation: ChatConversation,
  people: ParticipantMap,
  currentUserId: string,
): string {
  if (conversation.title) return conversation.title;
  const others = otherMembers(conversation, people, currentUserId);
  return others.map((p) => p.name).join(", ") || conversation.id;
}

/** First name for compact group mentions ("Riya is typing…"). */
export function firstName(name: string) {
  return name.split(/\s+/)[0] ?? name;
}

/** A message as one line of plain text (previews, quotes, announcements). */
export function messageSummary(
  message: Pick<ChatMessage, "text" | "attachments" | "deleted">,
  labels: ChatLabels,
  own = false,
): string {
  if (message.deleted) return own ? labels.deletedOwnMessage : labels.deletedMessage;
  const text = message.text?.trim();
  if (text) return text.replace(/\s+/g, " ");
  const files = message.attachments ?? [];
  if (files.length === 0) return "";
  const images = files.filter((f) => f.kind === "image").length;
  return images === files.length
    ? labels.attachmentSummary("image", images)
    : labels.attachmentSummary("file", files.length);
}

/** "2 KB", "1.4 MB" via Intl: the file upload component's formatter, so sizes read the same everywhere. */
export const formatFileSize = formatBytes;

/** Formats a count with the locale's digits and grouping (undefined `locale` = the runtime default); the Intl formatter is cached. Safe to call on the server. */
export function formatCount(count: number, locale: string | undefined) {
  return nf(locale, {}).format(count);
}

