import type { ChatConversation, ChatParticipant } from "../types";

/** What {@link ThreadHeader} needs from the thread. */
export type ThreadHeaderProps = {
  showHeader: boolean;
  conversation: ChatConversation;
  others: readonly ChatParticipant[];
  typingPeople: readonly ChatParticipant[];
  group: boolean;
  title: string;
  titleId: string;
  headingLevel: HeadingLevelOption;
  headingRef: Ref<HTMLHeadingElement> | undefined;
  density: "comfortable" | "compact";
  L: ChatLabels;
  now: Date;
  locale: string | undefined;
  onBack: (() => void) | undefined;
  onCall: (() => void) | undefined;
  onVideoCall: (() => void) | undefined;
  onInfo: (() => void) | undefined;
  headerActions: ReactNode;
};

/**
 * The header of a `ChatThread`: back button, avatar, name, a status line (typing, members, presence or last seen) and
 * the call / info buttons. Without a visible header the name is still rendered, as a screen-reader-only heading.
 *
 * @internal
 */
export function ThreadHeader({
  showHeader,
  conversation,
  others,
  typingPeople,
  group,
  title,
  titleId,
  headingLevel,
  headingRef,
  density,
  L,
  now,
  locale,
  onBack,
  onCall,
  onVideoCall,
  onInfo,
  headerActions,
}: ThreadHeaderProps) {
  const Heading = HEADING_TAGS[headingBelow(headingLevel, 0)];
  const direct = !group ? others[0] : undefined;
  let subtitle: ReactNode;
  let subtitleTone: "accent" | "success" | "muted" = "muted";
  if (typingPeople.length) {
    subtitle = L.typing(
      typingPeople.map((p) => firstName(p.name)),
      group,
    );
    subtitleTone = "accent";
  } else if (group) {
    const members = conversation.participantIds.length;
    const online = others.filter((p) => p.presence === "online").length;
    subtitle = L.members(members, online);
  } else if (direct?.presence === "online") {
    subtitle = L.online;
    subtitleTone = "success";
  } else if (direct?.presence === "away") {
    subtitle = L.away;
  } else if (direct?.lastSeenAt) {
    const seen = toDate(direct.lastSeenAt);
    subtitle = seen ? L.lastSeen(formatRelative(seen, now, locale)) : undefined;
  }

  return (
    <>
      {showHeader ? (
        <header
          role="none"
          className={cn(
            "relative z-[4] flex min-w-0 shrink-0 items-center gap-2 border-b border-sheen-border",
            density === "compact" ? "px-2 py-2" : "px-2.5 py-2.5 @lg:px-4",
            // Phones at 320–360px: a little less padding leaves room for the name beside three buttons.
            "@max-[22.5rem]:gap-1 @max-[22.5rem]:px-1.5",
          )}
        >
          {onBack && (
            <Tooltip content={L.back} delay={300}>
              <button type="button" onClick={onBack} aria-label={L.back} className={chatIconButton}>
                <ChevronLeftIcon className="size-5" />
              </button>
            </Tooltip>
          )}
          <div
            // A pointer shortcut for "contact info"; the keyboard route is the info button in the header actions.
            role="presentation"
            className={cn("flex min-w-0 flex-1 items-center gap-2.5 @max-[22.5rem]:gap-2", onInfo && "cursor-pointer")}
            onClick={onInfo}
          >
            <ChatAvatar
              people={others.slice(0, 2)}
              src={conversation.avatarUrl}
              name={title}
              size="md"
              presence={direct?.presence}
            />
            <div className="flex min-w-0 flex-col">
              <Heading
                id={titleId}
                ref={headingRef}
                tabIndex={-1}
                className="truncate text-[0.9375rem] leading-5 font-semibold outline-none focus-visible:rounded-sm focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus"
              >
                {title}
              </Heading>
              {subtitle && (
                <p
                  className={cn(
                    "flex min-w-0 items-center gap-1 truncate text-xs leading-4",
                    subtitleTone === "accent"
                      ? "font-medium text-sheen-accent"
                      : subtitleTone === "success"
                        ? "text-sheen-success-text"
                        : "text-sheen-fg-muted",
                  )}
                >
                  <span className="truncate">{subtitle}</span>
                </p>
              )}
            </div>
          </div>
          <div className="flex shrink-0 items-center gap-0.5 @max-[22.5rem]:gap-0 any-pointer-coarse:gap-2!">
            {onCall && (
              <Tooltip content={L.call} delay={300}>
                <button type="button" onClick={onCall} aria-label={L.call} className={chatIconButton}>
                  <PhoneIcon />
                </button>
              </Tooltip>
            )}
            {onVideoCall && (
              <Tooltip content={L.videoCall} delay={300}>
                <button type="button" onClick={onVideoCall} aria-label={L.videoCall} className={chatIconButton}>
                  <VideoIcon />
                </button>
              </Tooltip>
            )}
            {onInfo && (
              <Tooltip content={group ? L.groupInfo : L.contactInfo} delay={300}>
                <button
                  type="button"
                  data-chat-info=""
                  onClick={onInfo}
                  aria-label={group ? L.groupInfo : L.contactInfo}
                  className={chatIconButton}
                >
                  <InfoIcon />
                </button>
              </Tooltip>
            )}
            {headerActions}
          </div>
        </header>
      ) : (
        <Heading id={titleId} ref={headingRef} tabIndex={-1} className="sr-only">
          {title}
        </Heading>
      )}
    </>
  );
}

import { cn } from "../../lib/cn";
import { dayKey, formatDayLabel, toDate, toTime } from "../format";
import type { ChatMessage } from "../types";

/** One message of the log with its run position: first and last of its run, whether its name shows, and whether the unread divider sits above it. */
export type Row = { message: ChatMessage; first: boolean; last: boolean; showName: boolean; unreadBefore: boolean };
/** One day of the log: its key, the day label and its rows. */
export type Day = { key: string; label: string; rows: Row[] };

/**
 * The log's rows: messages grouped into days, and within a day into runs (the same sender within `RUN_GAP`, so the
 * avatar and name show once per run). The first unread message always starts a run, so its divider can sit above it.
 */
export function buildDays(
  shown: readonly ChatMessage[],
  {
    firstUnreadId,
    now,
    locale,
    group,
    currentUserId,
  }: {
    firstUnreadId: string | null | undefined;
    now: Date;
    locale: string | undefined;
    group: boolean;
    currentUserId: string;
  },
): Day[] {
  const out: Day[] = [];
  let day: Day | undefined;
  let prev: ChatMessage | undefined;
  let prevRow: Row | undefined;
  for (const m of shown) {
    const date = toDate(m.createdAt) ?? new Date(0);
    const key = dayKey(date);
    if (day?.key !== key) {
      day = { key, label: formatDayLabel(date, now, locale), rows: [] };
      out.push(day);
      prev = undefined;
    }
    const unreadBefore = m.id === firstUnreadId;
    const continues =
      !unreadBefore &&
      prev !== undefined &&
      prev.kind !== "system" &&
      m.kind !== "system" &&
      prev.senderId === m.senderId &&
      toTime(m.createdAt) - toTime(prev.createdAt) < RUN_GAP;
    if (continues && prevRow) prevRow.last = false;
    const row: Row = {
      message: m,
      first: !continues,
      last: true,
      showName: group && m.senderId !== currentUserId && !continues && m.kind !== "system",
      unreadBefore,
    };
    day.rows.push(row);
    prev = m;
    prevRow = row;
  }
  return out;
}

/** Classes of a day label in the log: the incoming-bubble lift, with no blur of its own (one blurred pill would float while scrolling). */
export const dayLabelClass = cn(
  "glass-1 [-webkit-backdrop-filter:none] [backdrop-filter:none] bg-(--sheen-chat-in-fill)",
  "rounded-full px-3 py-1 text-xs font-medium text-sheen-fg-muted shadow-sm",
);

/** Earlier messages added to the page per frame (see `prepend`). */
export const PREPEND_STEP = 10;

/** Messages further apart than this start a new run (avatar and name again). */
export const RUN_GAP = 5 * 60_000;
/** How close to the bottom (px) the log counts as scrolled to the end. */
export const BOTTOM_SLACK = 48;

"use client";

import type { ReactNode } from "react";
import { MenuGroup, MenuItem, MenuSeparator } from "../../menu/menu";
import { CopyIcon, InfoIcon, PencilIcon, ReplyIcon, RetryIcon, SmilePlusIcon, TrashIcon } from "../icons";
import type { ChatLabels } from "../labels";
import type { ChatMessage } from "../types";
import { ReactionMenuItem } from "./parts";

/** Everything {@link MessageMenuItems} reads from the thread. */
export type MessageMenuContext = {
  currentUserId: string;
  L: ChatLabels;
  coarse: boolean;
  quickReactions: readonly string[];
  hasReact: boolean;
  onRetry: ((message: ChatMessage) => void) | undefined;
  hasDelete: boolean;
  toggleReaction: (message: ChatMessage, emoji: string) => void;
  openReactionsFor: (message: ChatMessage) => void;
  openInfoFor: (message: ChatMessage) => void;
  startReply: (message: ChatMessage) => void;
  startEdit: (message: ChatMessage) => void;
  canEdit: (message: ChatMessage) => boolean;
  copy: (message: ChatMessage) => void;
  remove: (message: ChatMessage) => Promise<void>;
};

/**
 * The entries of a message's actions menu (reactions row, reply, copy, edit, retry, info, delete), for the context menu
 * and the hover toolbar's ⋯ menu.
 *
 * @internal
 */
export function MessageMenuItems({
  message: m,
  from,
  ctx,
}: {
  message: ChatMessage;
  from: "context" | "more";
  ctx: MessageMenuContext;
}) {
  const { currentUserId, L, coarse, quickReactions, hasReact, onRetry, hasDelete } = ctx;
  const { toggleReaction, openReactionsFor, openInfoFor, startReply, startEdit, canEdit, copy, remove } = ctx;
  const own = m.senderId === currentUserId;
  const mineReactions = new Set(
    (m.reactions ?? []).filter((r) => r.userIds.includes(currentUserId)).map((r) => r.emoji),
  );
  const items: ReactNode[] = [
    hasReact && (
      <MenuGroup
        key="reactions"
        aria-label={L.reactions}
        className="flex items-center justify-between gap-0.5 px-0.5 pb-1"
      >
        {quickReactions.map((emoji) => (
          <ReactionMenuItem
            key={emoji}
            emoji={emoji}
            checked={mineReactions.has(emoji)}
            onToggle={() => toggleReaction(m, emoji)}
          />
        ))}
        <MenuItem
          key="more"
          aria-label={L.moreEmoji}
          onClick={() => openReactionsFor(m)}
          className="size-9 min-h-9 shrink-0 justify-center gap-0 rounded-full px-0 text-sheen-fg-muted any-pointer-coarse:size-10"
        >
          <SmilePlusIcon className="mx-auto size-[1.125rem]" />
        </MenuItem>
      </MenuGroup>
    ),
    hasReact && <MenuSeparator key="sep1" />,
    <MenuItem
      key="reply"
      icon={<ReplyIcon />}
      shortcut={from === "context" && !coarse ? "r" : undefined}
      onClick={() => startReply(m)}
    >
      {L.reply}
    </MenuItem>,
    m.text?.trim() && (
      <MenuItem key="copy" icon={<CopyIcon />} onClick={() => copy(m)}>
        {L.copy}
      </MenuItem>
    ),
    canEdit(m) && (
      <MenuItem
        key="edit"
        icon={<PencilIcon />}
        shortcut={from === "context" && !coarse ? "e" : undefined}
        onClick={() => startEdit(m)}
      >
        {L.edit}
      </MenuItem>
    ),
    own && m.status === "failed" && onRetry && (
      <MenuItem key="retry" icon={<RetryIcon />} onClick={() => onRetry(m)}>
        {L.retry}
      </MenuItem>
    ),
    own && (
      <MenuItem key="info" icon={<InfoIcon />} onClick={() => openInfoFor(m)}>
        {L.messageInfo}
      </MenuItem>
    ),
    own && hasDelete && <MenuSeparator key="sep2" />,
    own && hasDelete && (
      <MenuItem key="delete" icon={<TrashIcon />} tone="danger" onClick={() => void remove(m)}>
        {L.delete}
      </MenuItem>
    ),
  ];
  return <>{items}</>;
}

