/* ---------- A quick reaction in the actions menu ---------- */

/** A menuitemcheckbox: aria-checked says which reaction is already yours (the ring shows it). */
export function ReactionMenuItem({
  emoji,
  checked,
  onToggle,
}: {
  emoji: string;
  checked: boolean;
  onToggle: () => void;
}) {
  return (
    <BaseMenu.CheckboxItem
      checked={checked}
      onCheckedChange={onToggle}
      closeOnClick
      aria-label={emojiName(emoji)}
      className={cn(
        "relative isolate flex size-9 shrink-0 cursor-default items-center justify-center rounded-full text-xl leading-none outline-none select-none any-pointer-coarse:size-10",
        "touch-manipulation [-webkit-tap-highlight-color:transparent]",
        checked &&
          "bg-sheen-accent-soft ring-1 ring-sheen-accent-border forced-colors:ring-2 forced-colors:ring-[Highlight]",
      )}
      render={(itemProps, state) => (
        <div {...itemProps} className={cn(itemProps.className, state.highlighted && "sheen-fill")}>
          <MenuHighlight active={state.highlighted} className="rounded-full" />
          {itemProps.children}
        </div>
      )}
    >
      <span aria-hidden>{emoji}</span>
    </BaseMenu.CheckboxItem>
  );
}

/* ---------- Reaction picker ---------- */

/** The reaction picker of a message: the quick reactions and the ones already given. */
export function ReactionPanel({
  message,
  currentUserId,
  quickReactions,
  labels: L,
  labelsProp,
  coarse,
  onPick,
}: {
  message: ChatMessage;
  currentUserId: string;
  quickReactions: readonly string[];
  labels: ChatLabels;
  labelsProp?: Partial<ChatLabels>;
  coarse: boolean;
  onPick: (emoji: string) => void;
}) {
  const [more, setMore] = useState(false);
  const mine = (message.reactions ?? []).filter((r) => r.userIds.includes(currentUserId)).map((r) => r.emoji);
  return (
    <div className="flex flex-col gap-2">
      <div role="group" aria-label={L.reactions} className="flex items-center justify-between gap-1">
        {quickReactions.map((emoji) => {
          const pressed = mine.includes(emoji);
          return (
            <button
              key={emoji}
              type="button"
              aria-label={emojiName(emoji)}
              aria-pressed={pressed}
              onClick={() => onPick(emoji)}
              className={cn(
                "flex size-10 cursor-pointer items-center justify-center rounded-full text-[1.375rem] leading-none",
                "transition-[background-color,scale] duration-(--sheen-duration-snappy) ease-sheen-snappy hover:bg-sheen-hover motion-ok:hover:scale-125 motion-ok:active:scale-95",
                "focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-sheen-focus any-pointer-coarse:size-11",
                pressed && "bg-sheen-accent-soft ring-1 ring-sheen-accent-border forced-colors:ring-[Highlight]",
              )}
            >
              <span aria-hidden>{emoji}</span>
            </button>
          );
        })}
        <button
          type="button"
          aria-label={L.moreEmoji}
          aria-expanded={more}
          onClick={() => setMore((v) => !v)}
          className={cn(
            "flex size-10 cursor-pointer items-center justify-center rounded-full text-sheen-fg-muted transition-[background-color,rotate] duration-(--sheen-duration-base)",
            "hover:bg-sheen-hover hover:text-sheen-fg focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-sheen-focus any-pointer-coarse:size-11",
            more && "bg-sheen-hover text-sheen-accent motion-ok:rotate-45",
          )}
        >
          <svg
            aria-hidden
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            className="size-5"
          >
            <path d="M12 5v14M5 12h14" />
          </svg>
        </button>
      </div>
      {more && (
        <EmojiPicker
          onSelect={onPick}
          selected={mine}
          autoFocusSearch={!coarse}
          labels={labelsProp}
          className={coarse ? "w-full" : undefined}
        />
      )}
    </div>
  );
}

/**
 * Where the reaction picker lives: a popover beside the bubble (mouse), a bottom sheet (touch). `children` is the
 * {@link ReactionPanel}; `finalFocus` is the message focus returns to when the picker closes.
 */
export function ReactionPicker({
  open,
  coarse,
  anchor,
  align,
  label,
  finalFocus,
  onClose,
  children,
}: {
  open: boolean;
  coarse: boolean;
  anchor: HTMLElement | null;
  align: "start" | "end";
  label: string;
  finalFocus: () => HTMLElement | true;
  onClose: () => void;
  children: ReactNode;
}) {
  if (coarse) {
    return (
      <Drawer open={open} onOpenChange={(next) => !next && onClose()}>
        <DrawerContent finalFocus={finalFocus}>
          <DrawerHeader>
            <DrawerTitle>{label}</DrawerTitle>
          </DrawerHeader>
          <DrawerBody className="pb-[max(1rem,env(safe-area-inset-bottom))]">{children}</DrawerBody>
        </DrawerContent>
      </Drawer>
    );
  }
  return (
    <BasePopover.Root open={open} onOpenChange={(next) => !next && onClose()}>
      <BasePopover.Portal>
        <BasePopover.Positioner
          anchor={anchor}
          side="top"
          align={align}
          sideOffset={8}
          collisionPadding={12}
          className="z-50"
        >
          <BasePopover.Popup
            aria-label={label}
            finalFocus={finalFocus}
            className={cn(
              "glass-3 origin-(--transform-origin) rounded-sheen-lg p-2 outline-none",
              "[transition:opacity_var(--sheen-duration-fast)_var(--sheen-ease-out),scale_var(--sheen-duration-snappy)_var(--sheen-ease-snappy)]",
              "data-starting-style:opacity-0 motion-ok:data-starting-style:scale-90",
              "data-ending-style:[transition:opacity_var(--sheen-duration-exit)_var(--sheen-ease-exit),scale_var(--sheen-duration-exit)_var(--sheen-ease-exit)]",
              "data-ending-style:opacity-0 motion-ok:data-ending-style:scale-95",
            )}
          >
            {children}
          </BasePopover.Popup>
        </BasePopover.Positioner>
      </BasePopover.Portal>
    </BasePopover.Root>
  );
}

/* ---------- Short notes ("Copied") ---------- */

/** A short note over the bottom of the log; it is also announced, so it is hidden from assistive tech here. */
export function ThreadNotice({ notice, reduced }: { notice: string | null; reduced: boolean }) {
  return (
    <AnimatePresence>
      {notice && (
        <motion.p
          key={notice}
          initial={reduced ? { opacity: 0 } : { opacity: 0, y: 10, scale: 0.95 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={reduced ? { opacity: 0, transition: exitTransition } : { opacity: 0, y: 6, transition: exitTransition }}
          transition={reduced ? { duration: duration.fast } : spring.snappy}
          aria-hidden
          className="rounded-full bg-sheen-fg px-3.5 py-1.5 text-center text-xs font-medium text-sheen-bg shadow-lg"
        >
          {notice}
        </motion.p>
      )}
    </AnimatePresence>
  );
}

/* ---------- Message info ---------- */

/** The info sheet of a message: who read or received it and when. */
export function MessageInfo({
  message,
  coarse,
  locale,
  labels: L,
  returnFocus,
  onClose,
}: {
  message: ChatMessage | undefined;
  coarse: boolean;
  locale?: string;
  labels: ChatLabels;
  /** Where focus goes once it has closed (the message). */
  returnFocus: () => HTMLElement | true;
  onClose: () => void;
}) {
  // Keep the last message while the dialog animates closed.
  const [kept, setKept] = useState(message);
  if (message && message !== kept) setKept(message);
  const m = message ?? kept;
  const open = Boolean(message);
  const when = (value: ChatMessage["createdAt"] | undefined) => {
    const date = toDate(value);
    return date ? formatDateTime(date, locale) : L.notYet;
  };
  const status = m?.status ?? "sent";
  const delivered = m?.deliveredAt ?? (status === "read" ? m?.readAt : undefined);
  const body = m ? (
    <div className="flex flex-col gap-4">
      <p className="line-clamp-4 rounded-[1.125rem] rounded-ee-[0.375rem] px-3.5 py-2 text-sm text-sheen-accent-fg [overflow-wrap:anywhere] [background-image:var(--sheen-accent-fill)] bg-(--sheen-violet-700) forced-colors:border forced-colors:border-[CanvasText]">
        {messageSummary(m, L, true)}
      </p>
      <DescriptionList
        size="sm"
        items={[
          { id: "sent", label: L.sentAt, value: when(m.createdAt) },
          {
            id: "delivered",
            label: L.deliveredAt,
            value: status === "delivered" || status === "read" ? when(delivered ?? m.createdAt) : L.notYet,
          },
          { id: "read", label: L.readAt, value: status === "read" ? when(m.readAt ?? m.createdAt) : L.notYet },
        ]}
      />
    </div>
  ) : null;

  if (coarse) {
    return (
      <Drawer open={open} onOpenChange={(next) => !next && onClose()}>
        <DrawerContent finalFocus={returnFocus}>
          <DrawerHeader>
            <DrawerTitle>{L.messageInfo}</DrawerTitle>
          </DrawerHeader>
          <DrawerBody className="pb-[max(1.25rem,env(safe-area-inset-bottom))]">{body}</DrawerBody>
        </DrawerContent>
      </Drawer>
    );
  }
  return (
    <Dialog open={open} onOpenChange={(next) => !next && onClose()}>
      <DialogContent finalFocus={returnFocus}>
        <DialogHeader>
          <DialogTitle>{L.messageInfo}</DialogTitle>
        </DialogHeader>
        {body}
      </DialogContent>
    </Dialog>
  );
}

/* ---------- Jump to latest: a pill with its own state, so the scroll that shows it never re-renders the thread ---------- */

/** State of the jump-to-latest pill: whether it shows and how many new messages are unseen. */
export type JumpState = { show: boolean; unseen: number };

/** Creates the small store behind the jump-to-latest pill, so the scroll that shows it never re-renders the thread. */
export function createJumpStore() {
  let state: JumpState = { show: false, unseen: 0 };
  const listeners = new Set<() => void>();
  const update = (next: JumpState) => {
    if (next.show === state.show && next.unseen === state.unseen) return;
    state = next;
    listeners.forEach((fn) => fn());
  };
  return {
    get: () => state,
    subscribe: (fn: () => void) => {
      listeners.add(fn);
      return () => {
        listeners.delete(fn);
      };
    },
    setShow: (show: boolean) => update({ ...state, show }),
    setUnseen: (value: number | ((n: number) => number)) =>
      update({ ...state, unseen: typeof value === "function" ? value(state.unseen) : value }),
  };
}

/** A pill that scrolls the log to the newest message, with the count of unseen ones. */
export function JumpToLatest({
  store,
  empty,
  reduced,
  label,
  newBelow,
  onJump,
}: {
  store: ReturnType<typeof createJumpStore>;
  empty: boolean;
  reduced: boolean;
  label: string;
  newBelow: (count: number) => string;
  onJump: () => void;
}) {
  const { show, unseen } = useSyncExternalStore(store.subscribe, store.get, store.get);
  return (
    <AnimatePresence>
      {show && !empty && (
        <motion.button
          key="jump"
          type="button"
          onClick={onJump}
          aria-label={unseen ? `${label}, ${newBelow(unseen)}` : label}
          initial={reduced ? { opacity: 0 } : { opacity: 0, y: 14, scale: 0.85 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={
            reduced
              ? { opacity: 0, transition: exitTransition }
              : { opacity: 0, y: 8, scale: 0.92, transition: exitTransition }
          }
          // The pill pops in (bouncy); the glass fades on its own element only, so its blur holds.
          transition={
            reduced ? { duration: duration.fast } : { ...spring.bouncy, opacity: { duration: duration.fast } }
          }
          className={cn(
            "glass-3 pointer-events-auto relative flex size-10 cursor-pointer items-center justify-center rounded-full text-sheen-fg",
            "hover:bg-sheen-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus any-pointer-coarse:size-11",
          )}
        >
          <ArrowDownIcon className="size-[1.125rem]" />
          {unseen > 0 && (
            <UnreadBadge
              count={unseen}
              className={cn(
                "absolute -end-1.5 -top-2 motion-ok:animate-[sheen-chat-pop_var(--sheen-duration-snappy)_var(--sheen-ease-snappy)]",
                chatAppearReduced,
              )}
            />
          )}
        </motion.button>
      )}
    </AnimatePresence>
  );
}

import type { HeadingLevelOption } from "../../lib/heading";
import { type ReactNode, type Ref } from "react";
import { type ChatComposerHandle } from "../composer";
import { type ChatLabels } from "../labels";
import type { ChatConversation, ChatDraft, ChatMessage, ChatParticipant } from "../types";

/** Props of {@link ChatThread}. Required: `conversation`, `messages`, `participants`, `currentUserId`. */
export type ChatThreadProps = {
  /** The conversation being shown (kind, title, members). */
  conversation: ChatConversation;
  /** The messages of the conversation, oldest first: the thread shows them in this order, newest at the bottom. */
  messages: ChatMessage[];
  /** Everyone who can appear in the chat (names, avatars, presence). */
  participants: ChatParticipant[];
  /** Your id: your messages sit on the right (left in RTL) in the accent colour. */
  currentUserId: string;

  /** The composer sent a message. Add it to `messages` at once with status "sending" (optimistic), then update it. */
  onSend?: (draft: ChatDraft) => void;
  /** Called when you save an edit of your message. */
  onEdit?: (messageId: string, text: string) => void;
  /** You confirmed deleting your message. Keep it with `deleted: true` (it shows a placeholder). */
  onDelete?: (message: ChatMessage) => void;
  /** Add (`add` true) or remove your reaction. */
  onReact?: (message: ChatMessage, emoji: string, add: boolean) => void;
  /** "Retry" on a message whose status is "failed". */
  onRetry?: (message: ChatMessage) => void;
  /** The reader reached the top: load earlier messages and prepend them (the scroll position is kept). */
  onLoadOlder?: () => void;
  /** There are earlier messages to load. */
  hasOlder?: boolean;
  /** Earlier messages are loading: skeleton bubbles show at the top. */
  loadingOlder?: boolean;
  /** The newest message was seen (the reader is at the bottom): mark the chat read. */
  onRead?: (lastMessageId: string) => void;
  /** Called with true when you start typing and false when you stop. */
  onTyping?: (typing: boolean) => void;
  /** Show a "New messages" line above this message (the first unread one when the chat opened). */
  firstUnreadId?: string | null;

  /**
   * Show the header (avatar, name, presence, call buttons).
   * @default true
   */
  showHeader?: boolean;
  /** Shows a back button in the header (phones: back to the chat list). */
  onBack?: () => void;
  /** Shows a call button in the header. */
  onCall?: () => void;
  /** Shows a video-call button in the header. */
  onVideoCall?: () => void;
  /** Shows an info button (opens contact or group info). */
  onInfo?: () => void;
  /** Extra buttons at the end of the header. */
  headerActions?: ReactNode;
  /**
   * Level of the chat's name (`2 | 3`), or `"none"` for a paragraph with no heading role (for an example).
   * @default 2
   */
  headingLevel?: HeadingLevelOption;
  /** The heading element (to move focus to it, e.g. after opening the chat on a phone). */
  headingRef?: Ref<HTMLHeadingElement>;

  /**
   * Shows the message composer below the thread.
   * @default true
   */
  showComposer?: boolean;
  /** The unsent text (controlled), e.g. a draft per chat. */
  draft?: string;
  /** Called with the unsent text as it changes. */
  onDraftChange?: (text: string) => void;
  /** Chips that send a ready-made reply (support chats). */
  quickReplies?: string[];
  /** The reactions offered as one-tap choices on a message. */
  quickReactions?: readonly string[];
  /**
   * Let people attach files and photos.
   * @default true
   */
  allowAttachments?: boolean;
  /** The `accept` attribute of the file picker, e.g. "image/*,.pdf". */
  accept?: string;
  /** Receives the ref to the composer's handle (`focus()`, `setText()`...). */
  composerRef?: Ref<ChatComposerHandle>;
  /** Focus the composer on mount. */
  autoFocus?: boolean;

  /**
   * "compact": smaller type and spacing (the chat widget).
   * @default "comfortable"
   */
  density?: "comfortable" | "compact";
  /**
   * "glass": its own glass panel. "none": no surface (inside ChatApp or your own card).
   * @default "glass"
   */
  surface?: "glass" | "none";
  /** Shown instead of the log when there are no messages. */
  emptyState?: ReactNode;
  /** Fixes the current time used for relative dates (for tests and screenshots). */
  now?: Date;
  /** BCP 47 locale for times and day labels. Pass one for prerendered pages. */
  locale?: string;
  /** Any UI string (i18n); see {@link ChatLabels}. */
  labels?: Partial<ChatLabels>;
  /** Adds extra classes to the outer element. */
  className?: string;
};

"use client";

import { useCallback, useMemo, type Dispatch, type KeyboardEvent, type SetStateAction } from "react";
import { useLatest } from "../../hooks/use-latest";
import type { ConfirmOptions } from "../../alert-dialog/alert-dialog";
import type { ChatComposerEditing } from "../composer";
import { emojiName } from "../emoji";
import type { ChatLabels } from "../labels";
import type { MessageMenuHandle, MessageRowActions } from "../message-row";
import type { ToolbarStore } from "../toolbar-store";
import type { ChatMessage, ChatReplyRef } from "../types";
import type { ChatThreadProps } from "./types";
import type { ReactionTarget, ThreadLightbox } from "./use-thread-overlays";

/** What the message actions need from the thread: its callbacks, labels, ids and the overlay setters they drive. */
export type MessageActionsInput = Pick<
  ChatThreadProps,
  "onEdit" | "onDelete" | "onReact" | "onRetry" | "onLoadOlder"
> & {
  /** The messages on the page, oldest first (the deferred list the rows are drawn from). */
  messages: ChatMessage[];
  currentUserId: string;
  hasOlder: boolean;
  loadingOlder: boolean;
  L: ChatLabels;
  reduced: boolean;
  nameOf: (id: string) => string;
  domIdOf: (id: string) => string;
  announce: (text: string) => void;
  confirm: (options: ConfirmOptions) => Promise<boolean>;
  showNotice: (text: string) => void;
  flash: (id: string) => void;
  setStick: (follow: boolean) => void;
  setPendingFocusUp: (id: string | null) => void;
  toolbar: ToolbarStore;
  moreMenu: MessageMenuHandle;
  setActiveId: Dispatch<SetStateAction<string | null>>;
  setReplyTo: Dispatch<SetStateAction<ChatReplyRef | null>>;
  setEditing: Dispatch<SetStateAction<ChatComposerEditing | null>>;
  setLightbox: Dispatch<SetStateAction<ThreadLightbox | null>>;
  setReactionTarget: Dispatch<SetStateAction<ReactionTarget | null>>;
  setReactionFromId: Dispatch<SetStateAction<string | null>>;
};

/**
 * Everything a message can be asked to do: reply, edit, react, copy, delete, retry, jump to the original, open its
 * actions menu, and the keyboard model of the log (↑ / ↓, Page keys, Home / End, Enter, R, E). Returns the stable
 * `actions` object the rows share (so a new inline handler from the parent never re-renders every message) and the
 * handlers the thread's menus call.
 */
export function useMessageActions({
  messages,
  currentUserId,
  hasOlder,
  loadingOlder,
  onEdit,
  onDelete,
  onReact,
  onRetry,
  onLoadOlder,
  L,
  reduced,
  nameOf,
  domIdOf,
  announce,
  confirm,
  showNotice,
  flash,
  setStick,
  setPendingFocusUp,
  toolbar,
  moreMenu,
  setActiveId,
  setReplyTo,
  setEditing,
  setLightbox,
  setReactionTarget,
  setReactionFromId,
}: MessageActionsInput) {
  const setHoverId = toolbar.setHover;
  const setPinnedId = toolbar.setPinned;

  const focusMessage = useCallback(
    (id: string) => {
      const node = document.getElementById(domIdOf(id));
      if (!node) return;
      node.focus({ preventScroll: true });
      node.scrollIntoView({ block: "nearest" });
    },
    [domIdOf],
  );

  const startReply = useCallback(
    (m: ChatMessage) => {
      if (m.deleted || m.kind === "system") return;
      const kind = m.attachments?.[0]?.kind;
      setEditing(null);
      const trimmed = m.text?.trim() ?? "";
      setReplyTo({
        id: m.id,
        senderId: m.senderId,
        text: trimmed || undefined,
        attachmentKind: trimmed ? undefined : kind,
      });
      announce(L.announceReplying(nameOf(m.senderId)));
    },
    [announce, L, nameOf, setEditing, setReplyTo],
  );

  const canEdit = useCallback(
    (m: ChatMessage) =>
      m.senderId === currentUserId && !m.deleted && m.kind !== "system" && Boolean(m.text?.trim()) && Boolean(onEdit),
    [currentUserId, onEdit],
  );

  const startEdit = useCallback(
    (m: ChatMessage) => {
      if (!canEdit(m)) return;
      setReplyTo(null);
      setEditing({ id: m.id, text: m.text ?? "" });
      announce(L.announceEditing);
    },
    [canEdit, announce, L, setEditing, setReplyTo],
  );

  // Callbacks from props are read through refs: an inline handler from the parent must not
  // change the rows' shared `actions` object (that would re-render every message).
  const callbacksRef = useLatest({ onReact, onRetry });
  const react = useCallback(
    (m: ChatMessage, emoji: string, add: boolean) => {
      callbacksRef.current.onReact?.(m, emoji, add);
      announce(L.announceReaction(emojiName(emoji), add));
    },
    [callbacksRef, announce, L],
  );

  const toggleReaction = useCallback(
    (m: ChatMessage, emoji: string) => {
      const mine = m.reactions?.find((r) => r.emoji === emoji)?.userIds.includes(currentUserId) ?? false;
      react(m, emoji, !mine);
    },
    [react, currentUserId],
  );

  const copy = useCallback(
    (m: ChatMessage) => {
      const text = m.text ?? "";
      // Missing on insecure origins, although the DOM types say it always exists.
      const clipboard = (navigator as Partial<Navigator>).clipboard;
      if (!clipboard) {
        showNotice(L.copyFailed);
        return;
      }
      clipboard.writeText(text).then(
        () => showNotice(L.copied),
        () => showNotice(L.copyFailed),
      );
    },
    [showNotice, L],
  );

  const remove = useCallback(
    async (m: ChatMessage) => {
      const id = domIdOf(m.id);
      const ok = await confirm({
        tone: "danger",
        title: L.deleteTitle,
        description: L.deleteDescription,
        confirmLabel: L.deleteConfirm,
        cancelLabel: L.cancel,
        finalFocus: () => document.getElementById(id),
      });
      if (!ok) return;
      onDelete?.(m);
      announce(L.announceDeleted);
    },
    [confirm, L, onDelete, announce, domIdOf],
  );

  const jumpTo = useCallback(
    (id: string) => {
      const node = document.getElementById(domIdOf(id));
      if (!node) {
        showNotice(L.originalNotLoaded);
        return;
      }
      setStick(false);
      node.scrollIntoView({ block: "center", behavior: reduced ? "auto" : "smooth" });
      node.focus({ preventScroll: true });
      flash(id);
    },
    [domIdOf, reduced, showNotice, L, setStick, flash],
  );

  /** Opens the actions menu at a message (Enter, or the keyboard's menu key). */
  const openMenuAt = useCallback((node: HTMLElement) => {
    const rect = node.getBoundingClientRect();
    const own = node.dataset.own !== undefined;
    const bubble = node.querySelector<HTMLElement>(":scope > div:last-child") ?? node;
    const b = bubble.getBoundingClientRect();
    node.dispatchEvent(
      new MouseEvent("contextmenu", {
        bubbles: true,
        cancelable: true,
        clientX: own ? Math.max(rect.left + 8, b.right - 16) : b.left + 16,
        clientY: Math.min(b.bottom - 4, b.top + 28),
      }),
    );
  }, []);

  const messagesListRef = useLatest(messages);
  const liveRef = useLatest({ hasOlder, onLoadOlder, loadingOlder, startReply, startEdit, focusMessage, openMenuAt });

  const actions = useMemo<MessageRowActions>(
    () => ({
      focus: (id) => setActiveId(id),
      hover: setHoverId,
      toolbar,
      keyDown: (event: KeyboardEvent<HTMLElement>, message: ChatMessage) => {
        const self = event.target === event.currentTarget;
        if (!self) {
          if (event.key === "Escape") {
            event.preventDefault();
            event.currentTarget.focus();
          }
          return;
        }
        if (event.altKey || event.ctrlKey || event.metaKey) return;
        const list = messagesListRef.current;
        const index = list.findIndex((m) => m.id === message.id);
        const move = (to: number) => {
          const target = list[Math.max(0, Math.min(list.length - 1, to))];
          if (target) liveRef.current.focusMessage(target.id);
        };
        switch (event.key) {
          case "ArrowUp":
            event.preventDefault();
            if (index === 0 && liveRef.current.hasOlder && liveRef.current.onLoadOlder) {
              setPendingFocusUp(message.id);
              if (!liveRef.current.loadingOlder) liveRef.current.onLoadOlder();
            } else move(index - 1);
            break;
          case "ArrowDown":
            event.preventDefault();
            move(index + 1);
            break;
          case "PageUp":
            event.preventDefault();
            move(index - 10);
            break;
          case "PageDown":
            event.preventDefault();
            move(index + 10);
            break;
          case "Home":
            event.preventDefault();
            move(0);
            break;
          case "End":
            event.preventDefault();
            move(list.length - 1);
            break;
          case "Enter":
          case " ":
            if (message.kind === "system" || message.deleted) return;
            event.preventDefault();
            liveRef.current.openMenuAt(event.currentTarget);
            break;
          case "r":
          case "R":
            if (message.kind === "system" || message.deleted) return;
            event.preventDefault();
            liveRef.current.startReply(message);
            break;
          case "e":
          case "E":
            event.preventDefault();
            liveRef.current.startEdit(message);
            break;
        }
      },
      react,
      openReactions: (message, anchorEl) => {
        setPinnedId(message.id);
        setReactionFromId(message.id);
        setReactionTarget({ messageId: message.id, anchor: anchorEl });
      },
      reply: (message) => liveRef.current.startReply(message),
      retry: (message) => callbacksRef.current.onRetry?.(message),
      jumpTo,
      openImage: (message, index) => setLightbox({ messageId: message.id, index, from: index }),
      nameOf,
      moreMenu,
    }),
    [
      react,
      jumpTo,
      nameOf,
      moreMenu,
      callbacksRef,
      liveRef,
      messagesListRef,
      setHoverId,
      setPinnedId,
      toolbar,
      setPendingFocusUp,
      setActiveId,
      setReactionFromId,
      setReactionTarget,
      setLightbox,
    ],
  );

  /* ----- Edit your last message (↑ in an empty composer) ----- */
  const editLast = useCallback(() => {
    for (let i = messages.length - 1; i >= 0; i--) {
      const m = messages[i];
      if (m && canEdit(m)) {
        startEdit(m);
        return;
      }
    }
  }, [messages, canEdit, startEdit]);

  return { startReply, canEdit, startEdit, toggleReaction, copy, remove, actions, editLast };
}

"use client";

import { useEffect, useMemo, useState } from "react";
import type { ChatMessage } from "../types";
import { PREPEND_STEP } from "./layout";

/**
 * Earlier messages, a few at a time. A batch of earlier messages (30, say) is added to the page `PREPEND_STEP` at a
 * time, nearest the reader first, one step per frame: no single frame has to build them all, and the reader's place
 * is kept after each step. Returns `hiddenOlder` (how many of the oldest messages are not on the page yet) and
 * `shown` (the messages that are).
 */
export function usePrependedMessages(messages: ChatMessage[]) {
  const [prepend, setPrepend] = useState({ first: messages[0]?.id ?? null, hidden: 0 });
  const firstMessageId = messages[0]?.id ?? null;
  if (prepend.first !== firstMessageId) {
    const oldFirst = prepend.first ? messages.findIndex((m) => m.id === prepend.first) : -1;
    setPrepend({
      first: firstMessageId,
      hidden: oldFirst > 0 ? Math.max(0, oldFirst + prepend.hidden - PREPEND_STEP) : 0,
    });
  }
  const hiddenOlder = Math.min(prepend.hidden, messages.length);
  useEffect(() => {
    if (!hiddenOlder) return;
    const frame = requestAnimationFrame(() =>
      setPrepend((p) => ({ ...p, hidden: Math.max(0, p.hidden - PREPEND_STEP) })),
    );
    return () => cancelAnimationFrame(frame);
  }, [hiddenOlder]);
  const shown = useMemo(() => (hiddenOlder ? messages.slice(hiddenOlder) : messages), [messages, hiddenOlder]);
  return { hiddenOlder, shown };
}

"use client";

import type { Menu as BaseMenu } from "@base-ui/react/menu";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createMenuHandle } from "../../menu/menu";
import type { ChatComposerEditing } from "../composer";
import { useLongPressMenuGuard } from "../hooks";
import type { ChatReplyRef } from "../types";

/** The photo viewer: which message's photos, the one shown (null = closed) and the one it was opened from. */
export type ThreadLightbox = { messageId: string; index: number | null; from: number };
/** The reaction picker: the message it is for and the bubble it sits beside. */
export type ReactionTarget = { messageId: string; anchor: HTMLElement | null };

/**
 * What the thread shows beside the log: the reply or edit the composer is on, the photo viewer, the reaction picker,
 * the info panel, the message a context menu was opened for, short notices ("Copied") and the flash of a message
 * that was jumped to. One piece of state each, plus the timers that clear the notice and the flash.
 */
export function useThreadOverlays(announce: (text: string) => void) {
  const [replyTo, setReplyTo] = useState<ChatReplyRef | null>(null);
  const [editing, setEditing] = useState<ChatComposerEditing | null>(null);
  const [lightbox, setLightbox] = useState<ThreadLightbox | null>(null);
  const [reactionTarget, setReactionTarget] = useState<ReactionTarget | null>(null);
  const [infoId, setInfoId] = useState<string | null>(null);
  // The message a picker / info panel was opened for: focus goes back to it when that closes.
  const [reactionFromId, setReactionFromId] = useState<string | null>(null);
  const [infoFromId, setInfoFromId] = useState<string | null>(null);
  const [contextId, setContextIdState] = useState<string | null>(null);
  // Read synchronously when the menu opens (the state is a render behind for keyboard opens).
  const contextRef = useRef<string | null>(null);
  const setContextId = useCallback((value: string | null) => {
    contextRef.current = value;
    setContextIdState(value);
  }, []);
  // A long-press menu stays open when the finger is held past a second (see useLongPressMenuGuard).
  const contextOpen = useRef(false);
  const longPressGuard = useLongPressMenuGuard(useCallback(() => contextOpen.current, []));
  /** The log's context menu opens only on a message (`setContextId` runs first, from the pointer or contextmenu event). */
  const onContextOpenChange = useCallback((open: boolean, details: { cancel: () => void; isCanceled: boolean }) => {
    if (open && !contextRef.current) details.cancel();
    if (!open) contextRef.current = null;
    contextOpen.current = open && !details.isCanceled;
  }, []);
  const onContextOpenChangeComplete = useCallback((open: boolean) => {
    if (!open && !contextRef.current) setContextIdState(null);
  }, []);
  const [notice, setNotice] = useState<string | null>(null);
  const noticeTimer = useRef<number | undefined>(undefined);
  const [flashId, setFlashId] = useState<string | null>(null);
  const flashTimer = useRef<number | undefined>(undefined);
  const moreMenu: BaseMenu.Handle<string> = useMemo(() => createMenuHandle<string>(), []);

  useEffect(
    () => () => {
      window.clearTimeout(noticeTimer.current);
      window.clearTimeout(flashTimer.current);
    },
    [],
  );

  const showNotice = useCallback(
    (text: string) => {
      setNotice(text);
      announce(text);
      window.clearTimeout(noticeTimer.current);
      noticeTimer.current = window.setTimeout(() => setNotice(null), 1800);
    },
    [announce],
  );

  /** Highlight a message briefly (after a jump to it). */
  const flash = useCallback((id: string) => {
    setFlashId(id);
    window.clearTimeout(flashTimer.current);
    flashTimer.current = window.setTimeout(() => setFlashId(null), 1400);
  }, []);

  return {
    replyTo,
    setReplyTo,
    editing,
    setEditing,
    lightbox,
    setLightbox,
    reactionTarget,
    setReactionTarget,
    infoId,
    setInfoId,
    reactionFromId,
    setReactionFromId,
    infoFromId,
    setInfoFromId,
    contextId,
    setContextId,
    onContextOpenChange,
    onContextOpenChangeComplete,
    longPressGuard,
    notice,
    showNotice,
    flashId,
    flash,
    moreMenu,
  };
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, type RefObject } from "react";
import { useLatest } from "../../hooks/use-latest";
import type { ChatComposerHandle } from "../composer";
import { messageSummary } from "../format";
import type { ChatLabels } from "../labels";
import type { ChatConversation, ChatMessage, ChatParticipant } from "../types";
import { BOTTOM_SLACK } from "./layout";
import { createJumpStore } from "./parts";

/** What {@link useThreadScroll} reads from the thread. */
export type ThreadScrollInput = {
  messages: readonly ChatMessage[];
  conversation: ChatConversation;
  people: ReadonlyMap<string, ChatParticipant>;
  currentUserId: string;
  lastId: string | null;
  hiddenOlder: number;
  firstUnreadId: string | null | undefined;
  hasOlder: boolean;
  loadingOlder: boolean;
  onLoadOlder: (() => void) | undefined;
  onRead: ((id: string) => void) | undefined;
  reduced: boolean;
  showComposer: boolean;
  composer: RefObject<ChatComposerHandle | null>;
  domIdOf: (id: string) => string;
  announce: (text: string) => void;
  L: ChatLabels;
  nameOf: (id: string) => string;
};

/**
 * All the scrolling behaviour of `ChatThread`: keeping the reader's place when messages arrive or history loads, following
 * the newest message while pinned to the bottom, the floating day pill, the jump-to-latest store, read receipts and
 * loading older messages near the top. Returns the refs to attach to the log and the handlers it needs.
 *
 * @internal
 */
export function useThreadScroll({
  messages,
  conversation,
  people,
  currentUserId,
  lastId,
  hiddenOlder,
  firstUnreadId,
  hasOlder,
  loadingOlder,
  onLoadOlder,
  onRead,
  reduced,
  showComposer,
  composer,
  domIdOf,
  announce,
  L,
  nameOf,
}: ThreadScrollInput) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const stick = useRef(true);
  const gliding = useRef(false);
  const anchor = useRef<{ id: string; offset: number } | null>(null);
  // The jump-to-latest pill lives in its own store and component: crossing the 240 px mark while
  // scrolling must not re-render the whole message list (a 100+ ms commit with a long history).
  const jump = useMemo(() => createJumpStore(), []);
  const setShowJump = jump.setShow;
  const setUnseen = jump.setUnseen;

  /** The first message whose bottom is below the log's top edge (rows are in order: a binary search, a few reads per scroll). */
  const topRow = useCallback((el: HTMLElement) => {
    const top = el.getBoundingClientRect().top;
    const rows = el.querySelectorAll<HTMLElement>("[data-message-id]");
    let lo = 0;
    let hi = rows.length - 1;
    let found: HTMLElement | null = null;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      const row = rows[mid];
      if (!row) break;
      if (row.getBoundingClientRect().bottom > top + 1) {
        found = row;
        hi = mid - 1;
      } else lo = mid + 1;
    }
    return { row: found, top };
  }, []);

  const measureAnchor = useCallback(
    (found?: { row: HTMLElement | null; top: number }) => {
      const el = scrollRef.current;
      if (!el) return;
      const { row, top } = found ?? topRow(el);
      anchor.current = row ? { id: row.dataset.messageId ?? "", offset: row.getBoundingClientRect().top - top } : null;
    },
    [topRow],
  );

  const restoreAnchor = useCallback(() => {
    const el = scrollRef.current;
    const a = anchor.current;
    if (!el || !a) return;
    const row = el.querySelector<HTMLElement>(`[data-message-id="${CSS.escape(a.id)}"]`);
    if (!row) return;
    const delta = row.getBoundingClientRect().top - el.getBoundingClientRect().top - a.offset;
    if (Math.abs(delta) > 0.5) el.scrollTop += delta;
  }, []);

  const pinBottom = useCallback(() => {
    const el = scrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, []);

  const loadRef = useLatest({ onLoadOlder, hasOlder, loadingOlder, revealing: hiddenOlder > 0 });
  const maybeLoadOlder = useCallback(() => {
    const el = scrollRef.current;
    const { onLoadOlder: load, hasOlder: more, loadingOlder: busy, revealing } = loadRef.current;
    if (!el || !load || !more || busy || revealing) return;
    if (el.scrollTop < 320) load();
  }, [loadRef]);

  const readRef = useLatest({ onRead, lastId, messages, currentUserId });
  const lastReported = useRef<string | null>(null);
  const reportRead = useCallback(() => {
    const { onRead: read, lastId: id, messages: list, currentUserId: me } = readRef.current;
    if (!read || !id || lastReported.current === id) return;
    const last = list[list.length - 1];
    if (!last || last.senderId === me) return;
    lastReported.current = id;
    read(id);
  }, [readRef]);

  /*
   * The floating day pill (WhatsApp / Telegram): while the reader scrolls, the day of the
   * messages at the top floats over the log, then fades out a second after scrolling stops. The
   * day labels in the log itself stay put, so nothing is covered while reading. Written straight
   * to the DOM (text + data-show) from the scroll frame: no React render per scroll event.
   */
  const dayPillRef = useRef<HTMLSpanElement>(null);
  // The reader scrolled by hand since the chat opened (a late "New messages" line then leaves them be).
  const readerMoved = useRef(false);
  const userScrolling = useRef(false);
  const dayPillTimer = useRef<number | undefined>(undefined);
  const updateDayPill = useCallback((found: { row: HTMLElement | null; top: number }) => {
    const pill = dayPillRef.current;
    if (!pill) return;
    let show = false;
    if (userScrolling.current) {
      const { row, top } = found;
      const day = row?.closest<HTMLElement>("[data-day]");
      const label = day?.firstElementChild?.getBoundingClientRect();
      // Hidden while that day's own label is on screen at the top (no double pill).
      if (day && label && label.bottom <= top + 4) {
        if (pill.textContent !== day.dataset.day) pill.textContent = day.dataset.day ?? "";
        show = true;
      }
    }
    pill.toggleAttribute("data-show", show);
  }, []);

  /** Scrolling stopped a second ago: the day pill fades out. */
  const settleDayPill = () => {
    window.clearTimeout(dayPillTimer.current);
    dayPillTimer.current = window.setTimeout(() => {
      userScrolling.current = false;
      dayPillRef.current?.removeAttribute("data-show");
    }, 1000);
  };

  /** The reader is scrolling by hand (wheel, touch, keys, the scrollbar): the day pill may show. */
  const noteUserScroll = () => {
    readerMoved.current = true;
    gliding.current = false;
    userScrolling.current = true;
    settleDayPill();
  };

  const scrollFrame = useRef(0);
  const scrollIdle = useRef<number | undefined>(undefined);
  function onScroll() {
    const el = scrollRef.current;
    if (!el) return;
    const distance = el.scrollHeight - el.scrollTop - el.clientHeight;
    const atBottom = distance <= BOTTOM_SLACK;
    if (gliding.current) {
      if (atBottom) gliding.current = false;
    } else {
      stick.current = atBottom;
    }
    setShowJump(distance > 240);
    if (atBottom) {
      setUnseen(0);
      reportRead();
    }
    cancelAnimationFrame(scrollFrame.current);
    // One read pass per frame (layout is clean here): the top row serves both.
    scrollFrame.current = requestAnimationFrame(() => {
      const found = topRow(el);
      measureAnchor(found);
      updateDayPill(found);
    });
    // While the log scrolls, messages passing under a still pointer don't show their toolbar (no re-render, no hit-testing per row).
    el.setAttribute("data-scrolling", "");
    window.clearTimeout(scrollIdle.current);
    scrollIdle.current = window.setTimeout(() => el.removeAttribute("data-scrolling"), 120);
    if (userScrolling.current) settleDayPill();
    maybeLoadOlder();
  }
  useEffect(
    () => () => {
      cancelAnimationFrame(scrollFrame.current);
      window.clearTimeout(dayPillTimer.current);
      window.clearTimeout(scrollIdle.current);
    },
    [],
  );

  function jumpToLatest() {
    const el = scrollRef.current;
    if (!el) return;
    stick.current = true;
    gliding.current = !reduced;
    setUnseen(0);
    el.scrollTo({ top: el.scrollHeight, behavior: reduced ? "auto" : "smooth" });
    if (showComposer) composer.current?.focus();
    else if (lastId) document.getElementById(domIdOf(lastId))?.focus({ preventScroll: true });
  }

  /* After each change: keep the reader's place, or follow the newest message. */
  const typingIds = useMemo(
    () => (conversation.typingIds ?? []).filter((id) => id !== currentUserId),
    [conversation.typingIds, currentUserId],
  );
  const typingPeople = useMemo(() => typingIds.flatMap((id) => people.get(id) ?? []), [typingIds, people]);
  const prev = useRef<{ first: string | null; last: string | null; mounted: boolean }>({
    first: null,
    last: null,
    mounted: false,
  });
  const knownIds = useRef(new Set<string>());
  /*
   * Messages that arrive after the thread opened (sent or received, at the end) animate in, and
   * keep that flag for the length of the entrance even when the thread re-renders meanwhile (a
   * status change must not cut it short). History loaded above never animates.
   */
  const lastMessageId = messages[messages.length - 1]?.id ?? null;
  const [arrivals, setArrivals] = useState<{ last: string | null; ids: ReadonlySet<string> }>({
    last: lastMessageId,
    ids: new Set(),
  });
  // Adjusting state while rendering (the pattern React documents for "previous value" logic): the
  // message is flagged in the very render that first shows it, with no ref or clock read.
  if (arrivals.last !== lastMessageId) {
    const lastIndex = arrivals.last ? messages.findIndex((m) => m.id === arrivals.last) : -1;
    const ids = new Set(arrivals.ids);
    // (Several messages into an empty log at once are history, like the layout effect below says.)
    if (lastIndex >= 0 || (arrivals.last === null && messages.length === 1)) {
      for (let i = lastIndex + 1; i < messages.length; i++) {
        const id = messages[i]?.id;
        if (id !== undefined) ids.add(id);
      }
    }
    setArrivals({ last: lastMessageId, ids });
  }
  // The flag lasts for the entrance (700 ms), and survives re-renders meanwhile.
  useEffect(() => {
    if (arrivals.ids.size === 0) return;
    const timer = window.setTimeout(() => setArrivals((p) => ({ last: p.last, ids: new Set() })), 700);
    return () => window.clearTimeout(timer);
  }, [arrivals.ids]);
  const appearing = (id: string) => arrivals.ids.has(id);
  const pendingFocusUp = useRef<string | null>(null);

  /** Open at the first unread message ("New messages"), otherwise at the newest. */
  const openAtStart = useCallback(() => {
    const el = scrollRef.current;
    if (!el) return;
    const divider = el.querySelector<HTMLElement>("[data-unread-divider]");
    if (divider) {
      el.scrollTop += divider.getBoundingClientRect().top - el.getBoundingClientRect().top - 56;
      // The newest message counts as seen only when it is on screen too.
      stick.current = el.scrollHeight - el.scrollTop - el.clientHeight <= BOTTOM_SLACK;
    } else {
      stick.current = true;
      pinBottom();
    }
  }, [pinBottom]);

  // Who "me" is and how names and labels read: current values for this effect without making it re-run when they change identity.
  const identityRef = useLatest({ currentUserId, L, nameOf });
  useLayoutEffect(() => {
    const el = scrollRef.current;
    const { currentUserId: me, L: text, nameOf: name } = identityRef.current;
    const firstId = messages[0]?.id ?? null;
    if (!el) return;
    const before = prev.current;
    // The first messages to show (several at once into an empty log: history, not news).
    const initial = !before.mounted || (before.last === null && messages.length > 1);
    if (initial) {
      openAtStart();
      for (const m of messages) knownIds.current.add(m.id);
    } else {
      const lastIndex = before.last ? messages.findIndex((m) => m.id === before.last) : -1;
      const added = lastIndex >= 0 ? messages.slice(lastIndex + 1) : before.last === null ? messages : [];
      const fresh = added.filter((m) => !knownIds.current.has(m.id));
      const mine = fresh.some((m) => m.senderId === me);
      if (mine) {
        stick.current = true;
        pinBottom();
      } else if (stick.current) {
        pinBottom();
      } else {
        restoreAnchor();
      }
      const incoming = fresh.filter((m) => m.senderId !== me && m.kind !== "system");
      if (incoming.length && !stick.current) setUnseen((n) => n + incoming.length);
      const latest = incoming[incoming.length - 1];
      if (latest) announce(text.announceIncoming(name(latest.senderId), messageSummary(latest, text)));
      for (const m of messages) knownIds.current.add(m.id);

      // ↑ on the first message loaded more: move on to the one just above it.
      if (pendingFocusUp.current && firstId !== before.first) {
        const index = messages.findIndex((m) => m.id === pendingFocusUp.current);
        const target = index > 0 ? messages[index - 1] : undefined;
        pendingFocusUp.current = null;
        if (target) {
          const node = document.getElementById(domIdOf(target.id));
          node?.focus({ preventScroll: true });
          node?.scrollIntoView({ block: "nearest" });
        }
      }
    }
    prev.current = { first: firstId, last: messages[messages.length - 1]?.id ?? null, mounted: true };
    measureAnchor();
    if (stick.current) reportRead();
    // Short history: load more until the log can scroll.
    maybeLoadOlder();
  }, [
    messages,
    loadingOlder,
    hasOlder,
    typingPeople.length,
    hiddenOlder,
    announce,
    openAtStart,
    pinBottom,
    restoreAnchor,
    measureAnchor,
    reportRead,
    maybeLoadOlder,
    identityRef,
    domIdOf,
    setUnseen,
  ]);

  // "New messages" decided after the chat opened (its messages arrived late): go there, unless the reader already scrolled.
  const placedUnread = useRef(firstUnreadId ?? null);
  useLayoutEffect(() => {
    if (!firstUnreadId || placedUnread.current === firstUnreadId) return;
    placedUnread.current = firstUnreadId;
    if (!prev.current.mounted || readerMoved.current) return;
    openAtStart();
    measureAnchor();
  }, [firstUnreadId, openAtStart, measureAnchor]);

  // Content that changes height on its own (photos loading, reactions, fonts).
  useEffect(() => {
    const content = contentRef.current;
    const el = scrollRef.current;
    if (!content || !el || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => {
      if (stick.current && !gliding.current) pinBottom();
      else if (!gliding.current) restoreAnchor();
    });
    observer.observe(content);
    observer.observe(el);
    return () => observer.disconnect();
  }, [pinBottom, restoreAnchor]);

  /** Follow the newest message from now on (`true`), or stay where the reader is (`false`). */
  const setStick = useCallback((follow: boolean) => {
    stick.current = follow;
  }, []);
  /** After the next batch of older messages loads, move focus to the message just above this one. */
  const setPendingFocusUp = useCallback((id: string | null) => {
    pendingFocusUp.current = id;
  }, []);
  return {
    scrollRef,
    contentRef,
    setStick,
    jump,
    dayPillRef,
    noteUserScroll,
    onScroll,
    jumpToLatest,
    typingPeople,
    appearing,
    setPendingFocusUp,
  };
}

"use client";

import { useCallback, useSyncExternalStore } from "react";

/** @internal The hover-toolbar state of a thread, outside React state so a hover re-renders two rows, not the whole thread. */
export type ToolbarStore = {
  /** Subscribe one row (by message id) to its own "shows the toolbar" flag. Returns the unsubscribe function. */
  subscribe: (id: string, callback: () => void) => () => void;
  /** Whether the row with this message id shows its toolbar now. */
  shown: (id: string) => boolean;
  /** The row under the pointer (null when the pointer left). */
  setHover: (id: string | null) => void;
  /** The row whose menu or reaction picker is open (it keeps its toolbar until the menu closes). */
  setPinned: (id: string | null) => void;
  /** The row that holds keyboard focus (focus-visible only). */
  setKeyboard: (id: string | null) => void;
  /** Touch devices have no hover toolbar: actions open as a sheet instead. */
  setCoarse: (coarse: boolean) => void;
};

/**
 * Accessibility: No UI of its own. It decides which message shows its (keyboard-reachable) toolbar.
 *
 * @internal Creates the store behind the hover toolbar. A thread owns one; each row listens only to its own id, so
 * moving the pointer from one message to the next notifies exactly two rows (the one it left and the one it entered).
 * Which row wins: the pinned one, then the hovered one, then the keyboard-focused one; none on a coarse pointer.
 *
 * @example
 * ```tsx
 * import { createToolbarStore } from "./toolbar-store";
 *
 * const store = createToolbarStore();
 * store.setHover("m1");
 * store.shown("m1"); // true
 * ```
 *
 * @see /chat/thread
 */
export function createToolbarStore(): ToolbarStore {
  let hover: string | null = null;
  let pinned: string | null = null;
  let keyboard: string | null = null;
  let coarse = false;
  const listeners = new Map<string, Set<() => void>>();

  const current = () => (coarse ? null : (pinned ?? hover ?? keyboard));
  const notify = (id: string | null) => {
    if (id) listeners.get(id)?.forEach((callback) => callback());
  };
  /** Runs a change and wakes only the rows whose answer flipped. */
  const change = (apply: () => void) => {
    const before = current();
    apply();
    const after = current();
    if (before === after) return;
    notify(before);
    notify(after);
  };

  return {
    subscribe(id, callback) {
      let set = listeners.get(id);
      if (!set) listeners.set(id, (set = new Set()));
      set.add(callback);
      return () => {
        set.delete(callback);
        if (set.size === 0) listeners.delete(id);
      };
    },
    shown: (id) => current() === id,
    setHover: (id) => change(() => void (hover = id)),
    setPinned: (id) => change(() => void (pinned = id)),
    setKeyboard: (id) => change(() => void (keyboard = id)),
    setCoarse: (value) => change(() => void (coarse = value)),
  };
}

/**
 * Accessibility: No UI of its own.
 *
 * @internal Whether the message with this id shows its hover toolbar. Re-renders only the row that calls it, and only
 * when its own answer changes.
 *
 * @example
 * ```tsx
 * import { useToolbarShown, type ToolbarStore } from "./toolbar-store";
 *
 * export function Row({ id, store }: { id: string; store: ToolbarStore }) {
 *   return useToolbarShown(store, id) ? <div role="toolbar" /> : null;
 * }
 * ```
 *
 * @see /chat/thread
 */
export function useToolbarShown(store: ToolbarStore, id: string) {
  const subscribe = useCallback((callback: () => void) => store.subscribe(id, callback), [store, id]);
  return useSyncExternalStore(
    subscribe,
    () => store.shown(id),
    () => false,
  );
}

/**
 * Chat data model: person-to-person messaging (direct chats and groups).
 *
 * Every chat component is controlled and presentational: you own the data (from your API,
 * a socket, local state) and pass it in; the components call back when people act
 * (onSend, onReact, onDelete, onLoadOlder, onSelect…). Dates accept a Date, an ISO string or
 * epoch milliseconds.
 */

/** Anything a date can come in as: a Date, an ISO string or epoch milliseconds. */
export type ChatDateInput = Date | string | number;

/** online: a green dot · away: an amber dot · offline: a hollow ring (shape differs, not only colour). */
export type ChatPresence = "online" | "away" | "offline";

/** A person in a chat: you, or someone you talk to. */
export type ChatParticipant = {
  /** Stable id; messages refer to it through `senderId`. */
  id: string;
  /** Display name. */
  name: string;
  /** Photo URL. Without one the avatar shows initials. */
  avatarUrl?: string;
  /** Whether they are online, away or offline. */
  presence?: ChatPresence;
  /** When they were last online (shown as "Last seen 5m ago" in direct chats). */
  lastSeenAt?: ChatDateInput;
  /** Phone number (ChatApp's info panel). */
  phone?: string;
  /** Email address (ChatApp's info panel). */
  email?: string;
  /** A short status line ("Building SheenUI ✨"). */
  about?: string;
  /** Job or team role, e.g. "Support" (ChatWidget's team header). */
  role?: string;
};

/**
 * Delivery state of your own message:
 * sending (clock) → sent (✓) → delivered (✓✓) → read (✓✓ accent), or failed ("Not delivered · Retry").
 */
export type ChatMessageStatus = "sending" | "sent" | "delivered" | "read" | "failed";

/** A photo or file attached to a message. */
export type ChatAttachment = {
  /** Stable identifier of the attachment, used as the React key and in callbacks. */
  id: string;
  /** "image" shows in the photo grid (with a full-size preview); "file" as a chip with a download link. */
  kind: "image" | "file";
  /** File name, shown on file chips and used as the fallback alt text. */
  name: string;
  /** Full image, or the file's download URL. */
  url?: string;
  /** Smaller image for the grid (defaults to `url`). */
  thumbnailUrl?: string;
  /** Size in bytes. */
  size?: number;
  /** MIME type, e.g. "application/pdf". Picks the file chip's colour and label. */
  mimeType?: string;
  /** Alt text for images (defaults to the file name). */
  alt?: string;
  /** Intrinsic pixel width of the image. With `height` it reserves the right box before the file loads (no layout shift). */
  width?: number;
  /** Intrinsic pixel height of the image. */
  height?: number;
};

/** One emoji and who reacted with it. Your own reaction is the one whose userIds include currentUserId. */
export type ChatReaction = { emoji: string; userIds: string[] };

/** A rich preview of a link in a message. */
export type ChatLinkPreview = {
  /** The link's address. */
  url: string;
  /** The page title. */
  title: string;
  /** A short description under the title. */
  description?: string;
  /** Site name shown above the title (defaults to the URL's host). */
  siteName?: string;
  /** Image or CSS background (gradient) for the card's banner. */
  imageUrl?: string;
};

/**
 * A snapshot of the message being replied to. Stored with the reply, so the quote shows even
 * when the original is not loaded (or was deleted).
 */
export type ChatReplyRef = {
  /** Id of the original message. */
  id: string;
  /** Id of the person who wrote the original. */
  senderId: string;
  /** The original's text at the time of the reply. */
  text?: string;
  /** What the original was when it had no text ("Photo", "File"). */
  attachmentKind?: ChatAttachment["kind"];
};

/** One message (a bubble, or a centred system note). */
export type ChatMessage = {
  /** Stable identifier of the message, used as the React key and in callbacks. */
  id: string;
  /** Id of the sender (a {@link ChatParticipant} `id`). */
  senderId: string;
  /** When it was sent. */
  createdAt: ChatDateInput;
  /** "system": a centred note ("Riya joined"), not a bubble. Defaults to "text". */
  kind?: "text" | "system";
  /** The message text. */
  text?: string;
  /** Photos and files. */
  attachments?: ChatAttachment[];
  /** Emoji reactions. */
  reactions?: ChatReaction[];
  /** The message this one replies to. */
  replyTo?: ChatReplyRef;
  /** A preview card for a link in the text. */
  linkPreview?: ChatLinkPreview;
  /** Set when the text was changed: shows "edited". */
  editedAt?: ChatDateInput;
  /** Deleted for everyone: shows a placeholder instead of the content. */
  deleted?: boolean;
  /** Your own messages only. Left out = "sent". */
  status?: ChatMessageStatus;
  /** When it was delivered (shown in the message details). */
  deliveredAt?: ChatDateInput;
  /** When it was read (shown in the message details). */
  readAt?: ChatDateInput;
};

/** One conversation in the list: a direct chat or a group. */
export type ChatConversation = {
  /** Stable identifier of the conversation, used as the React key and in callbacks. */
  id: string;
  /** "group" shows stacked avatars, sender names and member counts. Defaults to "direct". */
  kind?: "direct" | "group";
  /** Group name. Direct chats use the other person's name. */
  title?: string;
  /** Everyone in the chat (you may be included; you are left out where it matters). */
  participantIds: string[];
  /** Group photo. */
  avatarUrl?: string;
  /** The newest message, for the list's preview line and time. */
  lastMessage?: ChatMessage;
  /** Unread messages; shows a badge when above zero. */
  unreadCount?: number;
  /** Pinned conversations are listed first. */
  pinned?: boolean;
  /** Muted conversations get a quiet badge and a bell-off icon. */
  muted?: boolean;
  /** Archived conversations show under the "Archived" filter only. */
  archived?: boolean;
  /** People typing right now: the preview becomes "typing…" with animated dots. */
  typingIds?: string[];
  /** Unsent text: the preview shows "Draft: …". */
  draft?: string;
  /** Used for sorting and the time when there is no last message. */
  updatedAt?: ChatDateInput;
};

/** A file picked in the composer, before it is sent. */
export type ChatDraftAttachment = {
  /** Generated id. */
  id: string;
  /** The picked file. */
  file: File;
  /** File name. */
  name: string;
  /** Size in bytes. */
  size: number;
  /** MIME type of the file. */
  mimeType: string;
  /** Object URL for image thumbnails (revoked by the composer when removed or unmounted). */
  previewUrl?: string;
};

/** What the composer hands to onSend. */
export type ChatDraft = {
  /** The message text (trimmed). */
  text: string;
  /** Files picked for this message. */
  attachments: ChatDraftAttachment[];
  /** The message being replied to, if any. */
  replyTo?: ChatReplyRef;
};

/** Row actions in the conversation list (⋯ menu, right-click, long-press, swipe). */
export type ChatConversationAction =
  "pin" | "unpin" | "mute" | "unmute" | "archive" | "unarchive" | "markRead" | "markUnread";

/** Filters above the conversation list. */
export type ChatListFilter = "all" | "unread" | "groups" | "archived";

